/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20050308-3","meetingId":"h17-c-budget","date":"2005年3月8日","dateIso":"2005-03-08","committee":"予算特別委員会","time":"午前１０時０４分～午後６時１７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０４分開会 おはようございます。ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１７年度品川区一般会計予算","agenda":"○午前１０時０４分開会 おはようございます。ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１７年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"確認","question":"おはようあります。私は、８２ページ、１２款使用料及び手数料のところの総務手数料のうち諸証明手数料、建築確認証明等を質問します。平成１６年の予算特別委員会では１０２万円の手数料の見込みを立てました。本年においては２３９万円余の手数料の収入の見込みという予算立てをされました。平成１７年４月１日から確認申請手数料の改定が行われるということも含んだ上で、ご答弁をお願いしたいと思います。","respondent":"片田建築課長","answer":"来年度の予算としては４００件ほどの件数を見込んであるところですけれども、来年度は手数料条例を改定しますので、そういうことも想定した中での金額ということで考えてあります。諸証明のほうは、若干増えてあります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"私が理解した中では、１３５万円の予算の増収を見込まれているということですが、これは先ほどおっしゃった諸証明のアップ分と、手数料の改定のアップ分がその部分の金額の増収分だというふうに考えてよろしいわけでしょうか。","respondent":"片田建築課長","answer":"今委員おっしゃったとおり、諸証明の増分と手数料の増分を合算したものということで考えてあります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"本年４月１日から手数料のアップということで、先ほどもちょっとお伺いしましたけれども、改めまして、改定をすることによってどのくらいアップするのか、数字を教えていただきたいと思います。","respondent":"片田建築課長","answer":"どのぐらいアップですけれども、先ほど申し上げた、来年度の予算上の中では一応４００件の件数を見込んです。今回のアップ率というのは、確認手数料および許可の関係を含めて、従前から比較しますと１.０４％から１.０５％ぐらいのアップになってあります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"大沢委員","kind":"提案","question":"手数料も改定をしているということで、提案なんですが、事務事業概要の中の相談件数も、平成１２年度より品川区としては相談業務をアップしているということで、それに伴いまして事前相談件数が平成１３年度１万７０２件、平成１４年度１万３,１６３件、平成１５年度１万２,６５７件、微増で増えているわけでありますが、その部分におきまして。","respondent":"片田建築課長","answer":"そういうものに対して検討できないかと。それにつきましてはきちっと認定行為の中で、証明なり、書類としての整備したものを交付していますので、そういうものに見合った部分の対価が検討できないかということで、今検討をしているというような状況です。","voiceIndex":12,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"議会のほうとしても多く自分たちの無力化を感じたりすることがあるんですけれども、民間確認と、自治体のまちづくりについての意識の乖離をどういうふうに埋めていったらいいのか、私は常にわからないんですけれども、そこの部分、行政のお考えがあれば教えていただきたいと思います。","respondent":"片田建築課長","answer":"それについては要綱とか、いろいろな意味で事前に区のほうと協議をして行っていただくという中で確認を民間に出す、あるいは区に出すといったような流れになってありますので、その辺はきちっと仕分けをしているという認識です。","voiceIndex":14,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"建築基準法というのは国の法律であります大きな枠組みでありまして、平坦なものであって、色付けがされていない部分があります。建築行政におきましても、条例におきましても、品川区独自の顔というものが、色というもの、臭いというものがあると思いますので、そこのところを今後建築行政を進める上で、ご斟酌の上におきまして行っていっていただきたいと思います。要望にかえて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"若林委員","kind":"質問","question":"７３ページ、ベンチャー創業支援施設と、もう１点、９６ページ、マンション管理セミナー、２点でお伺いをしたいと思います。ベンチャー創業支援のほうです。たしか一昨年あたりスタートの西大井のベンチャー創業支援ですが、本来の立ち上げの目的、１年、２年経ったここまでの成果、ここら辺を２点お知らせを願いたいと思います。","respondent":"日下部産業振興課長","answer":"成果としましては、創業支援スペースに１０社、オフィススペース５社ということで入居していただいておりますけれども、実は具体的な成果としましては、毎月交流会も実施しております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"わすが短期間で本来の目的に沿って着々と成果を積み上げられている、こういうふうに感じました。そこで、新規に天王洲が立ち上がるということで、すでに選考が終わり、４月入居の準備という段階にきているというふうにお聞きしております。西大井の目的、成果を踏まえて、天王洲がどういう展開をされるのか、また、品川区にとってさらにパワーアップを狙っているのか、もう一回お聞きします。","respondent":"日下部産業振興課長","answer":"西大井の創業支援センターにつきましては、企業の創設ないしは新しい事業展開の初動期にある企業ないしは法人化を目的とした事業者を対象にしておりますけれども、天王洲につきましては、第２創業といいますか、分社化であるとか、新部門の創設といった形で、新たな分野。","voiceIndex":20,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"西大井の成果を踏まえながら、さらに、違う分野といいますか、職種といいますか、企業の形態に応じてさらに発展性を持たしていくということで、第２弾大変に期待をされているところです。さらに、入居者に対して、その上で区として、交流会等がありましたけれども、それ以外に技術支援、ネットワーク等々、また特記するものがあれば教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"私ども考えておりますのは、天王洲については、発展段階ということもありまして、特に専門スタッフを常駐するようなことはいたしませんけれども、ただ、西大井のスタッフを中心としまして、天王洲の皆さん方で、例えばいろいろな検討の課題があれば、これは西大井のスタッフが。","voiceIndex":24,"id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"そこで、昨年の１１月に大崎周辺の都市再生ビジョンが発表をされまして、その重点項目の１番目に、東京のものづくり産業をリードする拠点をつくっていくというふうにございました。この蓄積を大崎地域にどのように、ものづくりという観点で品川区全体としてネットワークというか、取り組みを広げていかれる計画があるのか、そこら辺のお考えをお聞かせ下さい。","respondent":"日下部産業振興課長","answer":"私ども産業振興の部門といたしましても、そういったこれまでの歴史的な経緯等を踏まえまして、従前どおりの形でどうするかというよりも、新しいまちの発展の中で、例えば先ほど申し上げました、産学連携とか。","voiceIndex":26,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区としても、国の施策を受けながら、それをどんどん進めていっていただきたいなというふうに思っております。そこで、今、教育の場、子どもたちがものづくりにふれる機会というのをぜひとももっと増やしていただきたいということで、教育委員会のほうとも連携をとりながら、工場見学、現場見学、操業見学、そういう工夫ができないものか、ちょっとお伺いをいたしたいと思います。","respondent":"日下部産業振興課長","answer":"伝統工芸の関係でも、学校との交流等も今実施をしておりますので、また今後とも教育委員会のほうと連携をしまして、さらに拡充するように検討をしてまいりたい、このように考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"高星委員","kind":"質問・要望","question":"私のほうからは、６４ページからの使用料及び手数料の款に関して２つばかりと、最後には３２６ページ、土地開発公社に関連してお聞きしたいと思います。したがって、２割自助努力というところの考え方をお聞かせいただきたいなというふうに思います。この経過について話せる程度でいいですから、お聞かせいただきたいと思います。","respondent":"市岡企画財政課長、西島障害者福祉課長、鷹倉経理課長","answer":"これは私どもの言葉で言えば、財政自主権の確立ということにつながると思うんですが、現状そのようには進んでいないようでありますが。旧大崎第一地域センター跡地の開設が遅れたということの経過ですけれども、昨年度開設予定で準備を進めてまいりました。前提として土地開発公社は区から計画的に土地の買収という形で、依頼に基づきまして買うという役目を土地開発公社が担っているということで。","voiceIndex":32,"id":"exchange-012"},{"speaker":"高星委員","kind":"質問・要望","question":"その請願の中身は、地元の方々の了解なしに建設するようなことのないように指導して下さいというということでありますけれども、こういった感覚に対する、どう扱うかというのは、基本的な区長の判断とか何か聞いているのではなくて、こういうふうな議会から上がってきたときにはどういうプロセスを経るんですかということだけ、手順だけお聞かせいただきたいと思います。","respondent":"市岡企画財政課長、宮地総務課長、榎本行財政改革担当課長","answer":"そのためには、先ほども品川区はいろいろ成熟しているというふうに言われましたが、まだまだ見直すところ、経常事業をいろいろ再検討するもの。当然さまざまなことを検討した上で、どういう取り組みになるかはわかりませんが、真摯に受け止めてまいります。全部で１６の学童保育クラブの今後の方針等を決めてきたわけですけれども、平成１６年度中にいろいろと有効活用を図ったのがかなりありますけれども。","voiceIndex":36,"id":"exchange-013"},{"speaker":"高星委員","kind":"質問・要望","question":"これが区の施策に、都から、国から、直でもって区民にかぶさってくる部分もあるわけですね。そういうことを考えると、トータルすると、区民の生活感、重税感、重圧感というのは物凄いものがあるというふうに思いますので、そのところをゆめゆめ、私たちは３４万人の品川区民の責任ある機関でありますので、そこのところに視点をあてた行政をお願いをしたいというふうに要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"最後の、土地開発公社のところで、先ほど高星委員も言ったように、答弁がよくわからなかったというところなので、私も聞き取れなかったんですけれども、東急電鉄側から土地開発公社にそういう要請があったのか、なかったのかということを聞かせていただきたい。それから、あったとしたら、どういうご返答をされたのか、聞かせていただきたいと思います。","respondent":"鷹倉経理課長","answer":"東急電鉄側から土地開発公社に直接そういう申し出があったことはございません。所管のほうからもそういうような話があったということは特に聞いてございません。","voiceIndex":42,"id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"私のほうから、雑入になりますけれども、１３６ページのしながわ水族館の運営収入についてお聞かせを願いたいというふうに思います。収入分配金ですけれども、平成１４年が９,３００万円、平成１５年が８,４００万円、平成１６年が７,４００万円、今期は５,１３０万円、このように落ちてきているというか、変わってきていますけれども、この要因についてまずお聞かせを願いたいと思います。","respondent":"松代道路公園課長","answer":"これまでも平成３年のオープン以来ずっと黒字ということで、収入、支出の関係で言いますと、区のほうへ運営費の収入ということで入ってきてあります。そういったものが少しずつ減っているですけれども、これは入館者が若干ずつ減ってきてあります。","voiceIndex":47,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"確かに単純に収入はあるとは言っても、実際には施設を維持するために大変なお金のかかる施設になっているというふうに思うんですけれども、今回の予算組みの理由というか、集客が望めなくなっている、この辺の理由ですね、以前は葛西臨海水族館の話とかの話が出ておりましたが、この辺の理由を教えていただきたい。","respondent":"松代道路公園課長","answer":"そういったもので、これまでも、５周年、１０周年、平成１８年に１５周年ですので、それに合わせまして、今回のアザラシ館をつくって、さらに魅力を高めていきたい、このように考えているところです。","voiceIndex":49,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"それと、水族館設置の当初の目的として教育施設だということですけれども、今回のアザラシ館の増設の理由にしても、魅力という意味では、営利を目的とする民間施設、民間事業者、この辺の集客のみに神経を注いでいるというふうに見えるんですけれども、この辺についてももう少し話していただきたいんですけれども、サンシャインに管理運営を委託をしているわけですから。","respondent":"松代道路公園課長","answer":"今回の水族館も運営当初２０万人から３０万人の入館者を見込んでおりまして、それに収入以外のものでも支出というものは当然見込んでおったわけです。","voiceIndex":51,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"品川プリンスホテルの値段まで言っていただきましてありがとうございました。私は、こういった民間の施設が充実をしてきている中で、民間業者と張り合うということではなくて、娯楽性の部分より、学習施設、教育施設の部分を評価する、充実をさせる、そういうしながわ水族館へ切り替える時期ではないかというふうに思いますが、いかがですか。","respondent":"松代道路公園課長","answer":"規模的には非常に大きゅうあります。そこで、私は感じたんですけれども、向こうはあくまでも娯楽施設を追求しています。学習機能としますれば、向こうは３００種類の、２万点ですけれども、しながわ水族館では４５０種ということで、広くやってあります。","voiceIndex":53,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは、予算書のページの順番でいきますと、８４ページ、１２款の使用料及び手数料、その中から薬事衛生手数料、それから、１１４ページの１４款、都支出金、３項都委託金、１目総務費委託金、１２４ページの１９款諸収入の中で２項の特別区預金利子、最後に１３８ページ、２０款特別区債、この４点についてお聞きしたいんですが、その前に、先ほど高星委員。","respondent":"鷹倉経理課長","answer":"それと、例えば直接何らかの目的で、目的がはっきりしている場合には、その関連する所管課を通じて経理課にくるということがあります。先ほど所管からもと言ったのは、それも含めて、土地開発公社も所管する経理課として情報はつかんでいないということを申し上げた次第です。","voiceIndex":56,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう一回確認するんですが、所管部署にも、区には話がなかったということで、そういう理解でよろしいでしょうか。分かりました。別の質問のほうに移っていきます。特別区預金利子の金額の中で、全体の区の予算１,２９２億円の中では、少ない金額ですが、前年度４万８,０００円のものが８０万３,０００円と増えている。特別区預金利子という意味で、もともとの内容を教えていただきたいと思います。","respondent":"小野副収入役","answer":"それ以外の資金につきましては、決済用預金ということで、科目存置ということで、１,０００円ということで計上しています。","voiceIndex":58,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"区民住宅の敷金２億円を使ったとおっしゃったんですが、債券購入ですが、全体ではどのぐらいの中の２億円を使われたのか。非常にいい運用だと思うんですが、ただ寝かせておくより、金額は小さいですけれども、有効に使っていくという意味では、大変にいいことではないかなと思うんです。","respondent":"市岡企画財政課長","answer":"３億３,０００万円のうちの２億円を運用しているです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この件は、これからも有効にしていただきたいということで終わります。特別区債の発行に関してですが、今回２０億９,４００万円の３件、土木債、教育債、住民税減税補てん債等を発行いたしますが、基本的に区債の発行の認められる条件というのをもう一回確認をさせていただきたいんです。","respondent":"市岡企画財政課長","answer":"ちなみに、１４ページのところで特別区債についての基本的な記載の方法ですとか、利率とか、こういうものを書いてございまして、これを議案としてご承認をいただくことによって、区のほうはその大枠については、ここで議決をいただきますので。","voiceIndex":62,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この件で、例えばこの３件、きのう補正の中で補助金の中から起債していた分を返還したのがありますけれども、逆に、土木債、教育債、減税補てん債、この中の返還の財源というと何と考えたらいいのか、当然今後の区税という問題にはなってくると思うんですが、例えば今言ったような、財源の確保されているものと、されていないものというのは、今までどういう形になっているのか。","respondent":"市岡企画財政課長","answer":"ざっと申し上げますと、私どもは起債は十分活用しておりますが、償還財源について非常に厳しく考えてございまして、いわゆる純然たる一般財源で還しているのは概ね４分の１ぐらいで、それ以外は全部返すあてのあるお金を使っておりまして。","voiceIndex":64,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前に話していただいたんですけれども、大井清掃工場を建設するときに、これからの清掃一部事務組合が解散した後も財調で補てんされるだろうと。あのときに一部事務組合が債券を発行していて、これがもし区に移管になった場合に、財調で補てんされるという形になると思うんですが、こういうものに対しての財調というのは、残り４分の３は財調が絡んでくる部分というのは大きいんですか。","respondent":"市岡企画財政課長","answer":"大井清掃工場のような一部事務組合建設の起債については、これは理屈から言えば、償還財源が各区の負担金分を全部財調措置されなければおかしいということで、この辺は間違いなく措置されると思いますし、そのために今５課題のうちの大きなものとして議論をしています。","voiceIndex":66,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"まだちょっと分かりきらない部分もあるんですけれども、これまでの税金というものからすると、区のもともと持っている基金というのをうまく活用もしていただきたいなというのが大前提にはあるんですけれども、この話というのは、ミニ公募債がここ２年発行されていない。今後の考え方としてはどういう対応なのかを確認したいと思います。","respondent":"市岡企画財政課長","answer":"この両方の意味を上手に活用していきたいというふうに考えておりまして、ミニ公募債は、これにプラス区民参加という意義がありますので、適才事業といいますか、いいものがあれば、今後も活用したいと思いますが。","voiceIndex":68,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"本来、こういうのをミニ公募債に充てるのがいいかどうかというのは、基本的にはあると思いますけれども、住民参加という意味では、例えば保育園の耐震の改築、それから児童センターとか、いろいろ出てくると思いますが、そういったものに対して、区としてミニ公募債、要するに、住民参加して、地域の中にある施設をお互いに見ていくんだよというような、そういう考え方というのはどうかなと思うんです。","respondent":"市岡企画財政課長","answer":"全体としてはご趣旨は私どももそのとおりだと思いますので、いろいろ研究をしていきたいと思うんですが、何しろまだ許可制が維持されておりまして、ちょっと言い訳めいてあれですけれども、起債許可というのは大変な細かな事務を伴いまして。","voiceIndex":70,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、事務作業も大変だと思いますし、さっきもちょっと言いましたように、基金がある中で、ミニ公募債を発行すると金利等が大分高くなってしまう。その中で、包括事務処理特例交付金ということが委託金で入ってくるというお話があったんですが、その数字的な面はお答えいただけるんでしょうか。人件費的なものと比較した上て、どのぐらいの数字が出てくるのか。","respondent":"高橋保健センター衛生課長","answer":"東京都から薬事事務が４月１日以降、１１事業が移譲されますが、その人件費につきましては、委員ご指摘のとおり、東京都の事務特例交付金より１名分ということで交付されるということになっております。","voiceIndex":72,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"というのは、１１４ページの中の事務処理特例交付金３億４,７８５万８,０００円、これが工場指定作業所等の規制に関する事務ほか８１事務事業、ですから、８２の事務事業全体の中で、前年は１億９,５００万円ぐらいですね。前年に比べまして相当大幅に金額が増えているんですが、そんなに事務処理が品川区のほうに移譲されているのかということの、２点の確認です。","respondent":"高橋保健センター衛生課長、市岡企画財政課長","answer":"金額の問題につきましては、ちょっと手元にないのでお答えできないんですが、今言ったとおり、１人分の人件費につきましてはくるということになります。ここの金額が大きく増えているのは、実は立会川の河口部の護岸工事を、こんな大規模な工事を事務処理特例でやれるというのも、所管のほうが一生懸命東京都と交渉しまして、これが１億６,３００万円ぐらいありまして。","voiceIndex":74,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほど大沢委員の質問の中で、建築確認のところでも特例交付金という話が出ておりましたが、これがずっと係わってくる、そういうことが今になって理解したんですが、先ほどのこれを例に出させてもらうと、例えば薬局を限定した場合、これから回っていく中で、それが私ははっきりわからないんですが、例えば年に１回、回れという指導があったとします、区としてそれを１.５回とか２回にしようというふうに。","respondent":"市岡企画財政課長","answer":"そのままもらえば、レベルアップすれば一般財源ですけれども、そういう協議を尽くしていきたいと考えております。","voiceIndex":77,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう中で、区がただ受けるのではなくて、協議の上で受けるということですから、事業自体をうまく進めていっていただきたいなということをお願いしたいなと思います。その中で、今言った、協議の中で財源を確保できればなおさらいいなという思いを感じておりましたので、これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"私は、５８ページ、特別区財政調整交付金についてお伺いをしますが、財調で、１月に特別区制度調査会が区長会に中間の報告をしたと、新聞の記事で読みました。なのに、この調査会の委員を見ると、ほとんどが大学の先生、学者なんですけれども、何で現状を一番知っている区長会がそのように学者たちに調査依頼をしなければいけないのか、それが疑問なんですけれども、まず教えていただけますか。","respondent":"市岡企画財政課長、高橋区長","answer":"このときに当事者同士の議論でやるよりは、もう一つ学識経験者と言いますか、第三者の目から、区が言っていることのほうが法律的にも論理的にも正しいということを言っていただきたいということで、先生方のご意見ですけれども。しかしながら、先生方が都区制度そのものをあまり実際の面で知らない方が多いわけでございまして、その実態の面を先生方にご説明をし、そこで先生方が中間のまとめとして論理的な報告書をつくっていただいた、これが経緯です。","voiceIndex":81,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"経緯はよく分かりました。中間のまとめが１月に出たんですけれども、主要５課題についてこの調査会はどんな見解を示したかということと、学者的と言ったら変かもしれませんけれども、学者的な発想で中間的な考え方をするのかなと思っているんですけれども、その中においてもどのような調査会での見解が出たか、また、この見解を区長会としてはどのように受け止めているか教えていただきたいと思います。","respondent":"高橋区長","answer":"その結果を見ながら、どのような仕切りにしていくか、これが一番重要な問題ですし、そういう問題につきましても制度調査会の方々と一緒になりまして検討をしていきたいと考えています。","voiceIndex":84,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"これからの抱負も今こ答弁をいただいて、次の質問だと思ったんですけれども、最後に、まさに今、地方自治といいますか、地方分権化が激しく動いていると思うんですが、その中で、首相の諮問機関である地方制度調査会が、東京都は特別扱いをして、大都市州にすべきだという認識で一致したという新聞記事が出たんですけれども、これは分かる範囲でいいんですが、どんなことかということと、それと。","respondent":"中尾根企画部長、高橋区長","answer":"その考え方の基本ですが、道州制というものの中に大都市という位置づけを州と市町村の二つの間に含ませるような形なんですね。いずれまた、そちらのほうに戻っていくようになると思います。現状では２３区の緊急な問題について討議をしていただこうということになっておるわけです。","voiceIndex":86,"id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"私のほうは、６４ページの総務使用料の中の総合区民会館使用料についてお伺いいたします。","respondent":"長田区民課長","answer":"目標ですけれども、こういった区民にご利用いただく施設につきましては、１００％が好ましいわけですけれども、幸いにも区民会館の場合は、区外の方も含みますけれども、多くの方、八十数％ぐらい利用されているようなことで。","voiceIndex":91,"id":"exchange-035"},{"speaker":"武内委員","kind":"意見","question":"８０％ぐらいのですが、歳出のほうでは、来年度の予算については運営費のほうでは人件費も含めて６億４,０００万円ぐらいかかるような予定になっておりますが、例えばこういった運営費に対して何割ですとか、そうした金額としての目標みたいなものがあるようでしたらお教え願います。","respondent":"長田区民課長","answer":"ですから、そういった意味では、本来でしたら財団のいろいろな収入の中で必要な経費について補われるべきだろうというふうに考えているところですけれども、この施設の中にはお金を取れないような施設も一緒に含まれてございまして、そういった部分を考え合わせますと。","voiceIndex":93,"id":"exchange-036"},{"speaker":"武内委員","kind":"質問","question":"例えば大小ホール、今回は１,３００件見込んでおられますけれども、昨年の予算では５６０件、金額のほうは７,０１１万円の見込みと、今回１,３００件ということで、件数は倍以上の見込みになっているんですが、使用料のほうは７,２７４万７,０００円ということで、昨年の５６０件に対してあまり増えていないんですが、その辺、大小の内訳等の関係もあるかと思うんですけれども。","respondent":"長田区民課長","answer":"平成１７年度からは、午前、午後、夜間ごとにそれぞれ１件というふうに数えておりますので、こういったカウントの仕方の違いによりまして、今回件数が大幅に増えているです。","voiceIndex":95,"id":"exchange-037"},{"speaker":"武内委員","kind":"質問","question":"件数の数え方の違いということですが、今お話に出ました大小ホール、イベントホールですが、これの利用の予約の入れ方というか、こういったところで、たしか午前、午後、夜間、また通してとかという予約の仕方があると思うんですが、ほかのところは午前、午後、夜間という、項目というか、予約できるんですが、たしか大ホール、小ホール、イベントホールは、例えば同じ団体であれば、昼借りて。","respondent":"長田区民課長","answer":"受付につきましては、具体的に財団の窓口、きゅりあんの窓口で実施をしております。","voiceIndex":97,"id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしたところをもうちょっと有効利用という考え方で、午前、午後、夜間、それで事情を聞いて、例えば夜の場合に仕込みが夕方からかかるというようなケースはもうしようがないと思うんですが、そうではないケースは、そういう形で昼に使えるようにしていったほうが、使用料も入るわけですし、その辺大いに検討いただきたいと思うんですが、いかがでしょうか。","respondent":"長田区民課長","answer":"そういったこともございまして、委員提案の内容が果たして可能なのかどうなのか、こういった部分につきましても、財団のほうへ伝えまして、できる限りそういう可能性については検討をしてまいりたい、このように考えてあります。","voiceIndex":99,"id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"最初に、午前中にあった高星委員のお話の中延駅前の問題の再関連質問といいますか、話があった、なかったというところですけれども、東急電鉄からなかったということで、東急電鉄以外のところからなかったのかという、その確認だけひとつするのと、荏原地区は、そういう土地が出てきたときに、昔助役の鈴木さんが言っておられたんだけれども、なかなか荏原では土地が出てこないということもあって。","respondent":"鷹倉経理課長、市岡企画財政課長","answer":"したがって、そこのところで、若干含みが持てるのかなというふうには考えてあります。財調のプラスの見込み方ですが、最終補正と１７億円で一致したのは全くの偶然でございまして、実際にどうやっているかと申しますと、平成１７年度財調を２３区全体では、３０４億円、普通交付金プラス平均でというか。","voiceIndex":102,"id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"財産価格審議会のほうは分かりました。それから、財調のほうですけれども、５.４％、平均より上だということで安心しました。１３０ページが基準になるかと思いますけれども、競馬組合の配分金等につきましてお聞きしていきます。競馬という事業そのものが賛否があるというふうにも認識をしています。そんなところで、２３区がどういうふうに競馬経営に係わっているのか、かいつまんで教えていただけますか。","respondent":"宮地総務課長","answer":"議決機関がありますので、特別区議会の各議長方２３人による議員定数があります。その中から議長、副議長、委員会等を構成するわけですけれども、一方、執行機関では管理者１人、これは区長がなっておりますが、副管理者は３人、このうち２人が区長、１人は知識経験者になります。","voiceIndex":105,"id":"exchange-041"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ですから、きちんと伝えていくことは伝えていかなければいけないと思っています。それがここに入っているのか、別枠でくるのか、それも教えていただきたいと思います。それから、株については、２３区でまだ２区か３区、自区で持っている区がありますよね。それを集約するんだという話がずって続いているんですけれども、その動きはどうなっているのかをお聞かせいただきたい。","respondent":"宮地総務課長","answer":"ただし、私どもの予算編成時期につきましては、一定の配分金を見込んだ予算編成をしておりますので、この５,０００万円も加えた形の４億９,０００万円で計上しています。","voiceIndex":107,"id":"exchange-042"},{"speaker":"林（宏）委員","kind":"意見","question":"各地の地方競馬がなくなっているというのは、もうご承知のとおりですし、各区に５,０００万円がいくお金がなくなると、従来から各区に場外発券所をつくってほしいという、これは２３区の共通した願いなんだけれども、各論反対が多くてなかなかできてこなかったといういきさつも聞いています。","respondent":"高橋区長","answer":"株の名義書き換えの問題、３区残っておりますけれども、正直言って、それは無理だと思います。","voiceIndex":109,"id":"exchange-043"},{"speaker":"川西委員","kind":"質問","question":"使用料を幾つか質問をいたします。昨日のご答弁の中では、できないんだというようなご答弁もありました。ですから、借り換えと繰上返済、利率を節約する意味で、まだいまだにできないのかどうか、これが一つです。それから、１３３ページの雑入の中で、各種事業参加費が幾つかありますけれども、なぜ雑入の中で処理しなければいけないのか、改めて伺いたいと思います。","respondent":"市岡企画財政課長","answer":"昨日出ておりましたＮＴＴ債のような返すお金自体が国からきたもの、この二つが繰り上げといいますか、満期一括償還ができる例外でございまして、それ以外のものについては、一時そういう声を挙げたら、国のほうができないようにしてしまいましたので、今のところ繰り上げとか。","voiceIndex":112,"id":"exchange-044"},{"speaker":"川西委員","kind":"質問","question":"次に移ります。１０８ページ、都の補助事業で、小児平日夜間診療というのが、２分の１補助というのであります。午後１時から夜間にかけての土曜日をこの事業に中に入れることはできるのかどうか伺います。これについても人口割等の規制があるのか、１年にこのぐらいしか予算はあげられないよというふうに国が言っているのかどうか、伺います。","respondent":"田中健康課長、岩田管理工事課長","answer":"休日という概念でいきますと、日曜とか祝日は入って体制は整えているわけですが、土曜の午後１時ぐらいまでは開業医がやっていらっしゃいますが、ということで、医師会等にも内々で相談をしておりますが。ご指摘の、交通安全整備事業費の３,６００万円の補助の件ですけれども、これは現在北品川地区で押し進めようとしている商店街地中化の補助です。","voiceIndex":114,"id":"exchange-045"},{"speaker":"川西委員","kind":"質問","question":"地中化の問題は、区が今後、区の方針に基づいて計画すれば補助金の２分の１は確保できるということで、分かりました。３９度ぐらいまでは、日曜日の休日診療まで待たせておく、しかし、子どもはそうはいかないというようなことが、大人はちょっと寝ていて、次の朝休日診療があるまで待っているということはできました。この辺についての内容、それから、跡利用について伺いたいと思います。","respondent":"田中健康課長","answer":"それが、この４月に移転をすることになりましたので、そこが空くという内容でございまして、まず跡地のほうは、今台場小学校のほうにあります在宅介護支援センターの移転先ということと、それから、私ども新規事業としまして。","voiceIndex":117,"id":"exchange-046"},{"speaker":"川西委員","kind":"確認","question":"分かりました。これらは、さっきから出ていました経営会議で決められたんですよね。その辺も伺っておきたいと思います。それから、次の質問に移りまして、８５ページ、８６ページの中で、建築確認手数料の件数、中間検査、完了検査の件数がこのように違いがあるのはどういうわけか、そこだけ伺わせて下さい。","respondent":"田中健康課長、片田建築課長","answer":"品川第一地域センタービルの跡地の関係ですけれども、予算のプレゼンテーションを行う事業部経営会議の中で審議をいただきまして、この予算の形になってあります。完了検査の件数についても、基本的には建物の確認を受けた場合には完了検査を受けなければいけないという義務はありますけれども、報告率が上がってきてはいるものの、１００％まではいっていないといったような状況の中で。","voiceIndex":121,"id":"exchange-047"},{"speaker":"川西委員","kind":"質問・要望","question":"その後すぐ区民部長のところへ電話を入れまして、４月から移るというけれども、できるのかしら、後はどうなるのかしらという話をしましたら、何か聞いていないようなお話も承りました。区民集会室のほうもみんながもっと安心して使えるように要望をしておきますのと、そういう跡利用については私どもにも早めにお知らせを願いたい。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-048"},{"speaker":"井上委員","kind":"提案","question":"私のほうからは、６６ページのシルバーセンターの使用料と、９２ページ、国庫支出金、１４５ページの議会運営費について伺いたいと思います。区議会議員の傍聴規則には、傍聴人数の枠ということで明記されているんですけれども、この人数の根拠はどういったところから出ているのでしょうか。","respondent":"福田区議会事務局長","answer":"委員会の傍聴規則を読みますと、第１委員会室が６５人、一番広い委員会室です。それから、第２委員会室から第５委員会室まで、これが各１０人とあります。面積の違い以外考えることができません。","voiceIndex":126,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"そういうことで決められているという中で、さまざまな傍聴者が事実上制限をされているという今の現状があるわけですが、逆に議会のほうではなくて、品川区のほうとして、議会では品川区の施策についてのことが決められたり、条例が審議されたりするということで、こういった場所を広く区民の方に知らせたほうがより区政の理解を得るかと思うんですけれども、区の施策を広報する立場として。","respondent":"福田区議会事務局長","answer":"議会を開く、閉じる、いろいろやり方はあるかと思いますけれども、それは議事機関である議会が判断することです。","voiceIndex":128,"id":"exchange-050"},{"speaker":"井上委員","kind":"質問・要望","question":"議会が判断するということですけれども、今までさまざまな委員会に自分たちの直接生活に係わることとか、問題意識を持たれている方たちがたくさん傍聴に見えているわけですが、そういう中で、傍聴規則にあるからということですけれども、認められない場合が多々あるということは先ほどもお話ししましたけれども、これを私たち議員としては、もちろんその役割として区政の内容を区民の方にお知らせし、また。","respondent":"福田区議会事務局長","answer":"品川区は条例で公開を定めているものです。しかも、申し上げたように、面積の制限はあるものの、その中で、おそらく定員いっぱいの定数を定めているのが傍聴規則であろうかというふうに思われます。現状における精いっぱいのことはしていると認識しております。","voiceIndex":130,"id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"そういう意味では、音声による傍聴の方法とかも検討できないということは、そういうふうな考え方次第だと思うんですけれども、可能性としてはできると思いますが、その辺はいかがでしょうか。","respondent":"福田区議会事務局長","answer":"これは議会運営委員会が確認をした事項に基づくものでございまして、おそらくその論拠といたしましては、ご存じのとおりこれは１人も傍聴はできません。そのやむを得ない代替措置として議会がお考えになった、そういう措置だろうというふうに思います。","voiceIndex":132,"id":"exchange-052"},{"speaker":"井上委員","kind":"質問・要望","question":"前例にはならないと言っても、実際に行われているということでは、先に進んでいきたいと思います。６６ページの民生使用料のシルバーセンター使用料ですけれども、シルバーセンターでは目的外利用の状況で使うことができるわけですが、日曜日の利用と、平日の利用はどのような状況になっているのか教えていただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"シルバーセンターの目的外利用についてのお尋ねですけれども、平成１５年度の実績で申し上げますと、件数が夜間が１,８６１件、日曜日が４４６件、合計２,３０７件という状況です。","voiceIndex":134,"id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"休日に限って言いますと、全体の使用枠から言うとどのぐらいの割合と考えたらよろしいんでしょうか。","respondent":"蓼沼高齢事業課長","answer":"割合ですけれども、休日、あるいは平日ということでの割合はとってございません。全体の稼働率ということになりますけれども、全体では平成１５年度は１１.９％という稼働状況です。","voiceIndex":136,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"実際に日曜日などに空いているシルバーセンターを子育て世代へも利用を積極的に拡大をしていくとか、今ある施設を有効に使うことができるかと思うんですけれども、これから箱ものを整備するよりも、そういった意味では大変立派な施設が空いているわけですから、そこのところをたくさんの方に、子育て世代に広報をして利用をすすめることもできるかと思うんですが、いかがでしょうか。","respondent":"蓼沼高齢事業課長","answer":"使用の際はしかるべき使用料をいただくということで運営をしております。ですので、今ご質問のありました、子育て支援についての活用ということでは、私どものほうでは今のところ特に何とも言えないような状況です。","voiceIndex":138,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問・要望","question":"しながわガイドのほうを見ても、シルバーセンターは日曜日休館と書いてあって、目的外使用として利用ができるんだということが分かりにくいと思うんです。ですから、広く広報でそういった利用もできるということも周知していただきたいし、異世代交流の事業としてこういった場を有効に活用することもできると思うんですが、高齢事業課と児童課で何かお考えがあれば、お聞きしたいと思います。","respondent":"辻田児童課長、蓼沼高齢事業課長","answer":"そういう中で、異世代間の交流ということで、特にシルバーセンターに来ている高齢者の方ということで限定したんですけれども、もっと広い地域の方と高齢者との交流の場にしていこうではないかというような事業も行っているです。シルバーセンターの活用の促進ですけれども、ご案内、チラシ等を作成しまして、各公共施設の窓口等でＰＲをしておりますし、広報のほうにも定期的にお知らせをしているですので。","voiceIndex":140,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問・要望","question":"９２ページの国庫支出金の１０と１２のところの婦人相談員活動費と、母子家庭自立支援給付金、事業補助金のところでお伺いしますけれども、婦人相談活動費のところで、委員会に資料を提示していただいた、予算特別委員会の補助金のところですけれども、ここの５ページの婦人相談員の活動という欄によりますと、ここは６９万１,０００円の予算ということで。","respondent":"辻田児童課長","answer":"今急に入ってきたもので、補助金の資料を持ってきておりませんので、ちょっとお待ちいただきたいと思います。調べまして、すぐにお答えいたします。","voiceIndex":143,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"今の金額の違うところを調べてということだと思うんですが、母子家庭自立支援給付金のほうの事業内容のほうはお分かりでしょうか。","respondent":"辻田児童課長、市岡企画財政課長","answer":"もう一つは、高等技能訓練促進費ということで、看護師とか、介護福祉士、こういう職業につく方について、直接の助成ではなく、いわゆる生活面での助成を、２年以上にわたってする場合は。予算書のほうの歳入と委員会資料の関係ですが、１６６万４,０００円のうち、事業費にあたっているものが、先ほど委員ご指摘をいただいた分で、あと８ページに職員給与費というのがありまして。","voiceIndex":146,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"仕事が決まっていなければ保育園にも行かれない、保育園が決まらなければ仕事もできないという今の現実の中で、母子家庭自立支援がいかに有効に使えるかということでは、子どもたちの預かり場所の支援も合わせて手当てをしていかないと有効に使える制度とは言えないと思うんですが、その辺のところも併せて考えられているのか、これから考えていく予定があるのか、その辺をお伺いしたいと思います。","respondent":"辻田児童課長","answer":"特に明日からこれをやるというような制度ではなく、自立支援の中で計画性を持って受講される方についてもそれをやっていただきたいということで、児童課の部分でいきますと、ファミリーサポートであるとか、一時預かりの制度であるとか、それから保育のほうにつきましても。","voiceIndex":149,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問","question":"多分現状が違うんだと思うんですけれども、準備をしていくのが当然だということは十分分かりますけれども、ここでファミリーサポートに、この事業に行くのに、その場所に行くのにどのくらいかかるか、半日も、３時間か４時間かかるということを、定期的にそういった学校に通うとなれば、ファミリーサポートのほうでも預けるのに１時間８００円という費用がかかるし、勉強する支援をいただいても。","respondent":"辻田児童課長","answer":"すでにお子さんが保育園に通っている方もあるかもしれませんし、すでにお仕事をしている方がさらにレベルアップをしていくような形の部分もあります。全体的に私どものほうもどういう形のシステムにしていくかは今後考えていきたいと思います。","voiceIndex":151,"id":"exchange-060"},{"speaker":"山路委員","kind":"質問・要望","question":"最初の、マイガーデン運営費負担金でありますが、ここに載っている理由は、先ほどお伺いいたしましたが、これは区の計画事業で、当時スタートしたときは、マスコミにも大変騒がれまして、新聞報道とかありましたけも、どういう理由で、どういう利用実態であるか、この辺についてお聞かせをいただきたいと思います。","respondent":"長田区民課長","answer":"マイガーデン事業ですけれども、区民の方には、なかなか都会では土いじりができないというようなことの中で、土いじりができるというようなこと、それから実際に自分で作物を植えて、収穫、また食べる喜びが味わえるというようなことで、大変人気な事業です。","voiceIndex":154,"id":"exchange-061"},{"speaker":"山路委員","kind":"質問・要望","question":"現場でも、今区民課長が説明されたとおりに、非常に評判があって、私もという方がたくさんいらっしゃるんですけれども、その中で身体障害者用の対応はどういうふうなことをされているか。周辺で身体障害者の方の利用に障害があるようなことがあるのかどうか、お聞かせをいただきたいと思います。","respondent":"長田区民課長","answer":"マイガーデンの身障者利用のことですけれども、実は私ども整備をする際に身障者のことまで考えなかったというのが正直なところです。東五反田のほうは、マイガーデンに入るところにＬ字溝がありますから、１０cmほどの段差があります。","voiceIndex":156,"id":"exchange-062"},{"speaker":"山路委員","kind":"質問・要望","question":"車椅子を利用されている区民の障害者の方から、マイガーデンに申し込みたいけれども、車椅子でも植えたり、土をいじったりできるような区画を設けてほしいという相談を受けました。それと、障害者に影響のあるようなバリアフリー化とか、そういう対応も今後ぜひしていただきたいと思いますけれども、どのようにお考えでしょうか。","respondent":"長田区民課長","answer":"私ども、当初そういったことで想定はしていなかったんですけれども、これからもこの事業、遊休地等で当面使っていないところを利用して、事業をさらに拡大をしていく予定ですので。","voiceIndex":158,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"車椅子に乗っている人が農作業といいますか、そういうことをやってみたいという一つの希望が見えてきたような感じがいたしますが、ぜひ花壇タイプとか、車椅子に乗っていて農作業ができるような、都会のオアシスを設けていただきたいことを要望しておきます。このことについて説明をしていただきたいと思います。","respondent":"金子保育課長","answer":"各種保育利用料とのご質問ですが、保育料につきましては三位一体改革でも説明申し上げているとおり、児童福祉法の中で保育の費用については国、都道府県、区市町村が負担をする。","voiceIndex":160,"id":"exchange-064"},{"speaker":"山路委員","kind":"質問・要望","question":"ところで、平成１７年度の保育入所者の入園の審査がこの間あったですが、入園状況ですね、私どもは待機児ゼロということで、都議会でも、国でも、総理も、待機児ゼロを目指そうということを言われているんですが、今回の状況はどういうふうになっているのか、お聞かせいただきたいと思います。","respondent":"金子保育課長","answer":"平成１７年４月入園の選考についてのお尋ねですけれども、これにつきましては全体としまして、転園、区外の方も含めて１,２５７人の方から申し込みがありまして、一次分としましては９１８人の方が入園を決定しています。","voiceIndex":162,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問・要望","question":"入園できなかった人の相談を受けましたので、私も非常に心配なところでありましたので、ここでお伺いしたいと思いますが、１２年間働いていて、ちょうど申し込み時期に産休に入りまして、二子が生まれるということでそれで申し込まれた。ところが、相談者は、産休というのは国の法律じゃないですか。これを差別するのはおかしいんじゃないですかという、審査基準についての疑問を持たれているわけです。","respondent":"金子保育課長","answer":"入園選考についてのお尋ねです。入園の枠に対してそれ以上の応募があった場合には選考すると、児童福祉法に規定されておりまして、それに基づいて私どもでは選考を実施しております。これは認可保育園、区立、私立を含めてですけれども、すべて私どもで入園者を決定しています。","voiceIndex":164,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問","question":"そこで、相談者の疑問の、国が認めている産休を、ちょうど二子めが生まれることで、１２年間働いていたので、働いている人と同じ条件でやるべきじゃないかです。この審査基準の制度というのはいつごろできたものでしょうか。","respondent":"金子保育課長","answer":"いつごろからできたかということですが、おそらく入園の選考が始まったときから何らかの形でやっていたと思いますが、これについては時代の状況、あるいは入園申込者の状況によって、絶えず形を変え、見直してきているものだというふうに考えてあります。","voiceIndex":166,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問","question":"この基準制度はいまだにずっと続いているということで、新しい時代の変化に応じて検討をしていく必要があるんじゃないかと思います。それと、もう１点は、仙台市に視察に行ったときに、入所基準の透明化を図るために公表しているというんですね、こういうこともこれから考えたらどうかと思うんですが、どのようにお考えでしょうか。","respondent":"金子保育課長","answer":"これの基準の公表についてですけれども、私どもこれについてお尋ねがあれば、お知らせしておりますので、非公開にしているというつもりではありませんので、ご理解をいただきたいと思います。","voiceIndex":168,"id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"６０ページの負担金、民生費負担金について伺いたいと思います。そして、３年間で２７％という、ここは来年度予算にはどういうふうに反映してきているのか、その辺を伺いたいと思います。","respondent":"金子保育課長","answer":"昨年の保育料の改定のときにご説明申し上げましたとおり、私どもは保育料に関しましては、現在の国の徴収基準額の６０％を目標と考えておりますが、平成１６年度につきましては、とりあえず９％の改定をご提案申し上げて、議決いただいたところです。","voiceIndex":171,"id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"経済情勢、他区の状況、国の動きを見て、今回は９％にとどまって、２年次分は考えなかったというふうに理解いたしましたが、そのこと自体は保育料は２７％上げるとしていた昨年の計画を中断せざるを得なかった、そういうことだというふうに私は受け止めながら聞いたんですけれども、そういうことでいいのかを、改めて伺いたい。","respondent":"金子保育課長","answer":"ですから、委員のご指摘と違いまして、私どもとしましては、適正な保育料というのは、現在のところ目標として国の徴収金基準額の６０％を想定しているところですので、種々の状況等々を勘案しながら検討をしてまいりたいと考えているところです。","voiceIndex":173,"id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"年収でお答えいただきたいというふうに質問をしたつもりですけれども、改めて年収で教えて下さい。","respondent":"金子保育課長","answer":"所得税の関係になりますので、所得税は、ご案内のとおり、さまざまな控除がありまして、人によりまして、同じ所得税額でも年収についてはかなり上下しますので、この額が中間層だということで申し上げにくいということだけご答弁をします。","voiceIndex":175,"id":"exchange-071"},{"speaker":"南委員","kind":"質問","question":"そして６月からは住民税も定率減税で１５％増税になりますね。先ほどいみじくも保育課長の答弁で、国の動きを見て上げなかったということもおっしゃっていましたけれども、ここはまさに定率減税の廃止等々によっての表現なのかなというふうに伺っていたんですけれども、定率減税によって保育料が値上げになってしまうのではないかというふうに心配するんですけれども、この点の認識はいかがでしょうか。","respondent":"金子保育課長","answer":"私ども保育料に関しましては、所得税の額をベースにして保育料を決定しておりますので、所得税が変われば変わるものというふうに考えてあります。","voiceIndex":177,"id":"exchange-072"},{"speaker":"南委員","kind":"確認","question":"所得税が変われば保育料が変わるということはそのとおりです。それは増税になったら、当然保育料は上がるということでいいんですか。確認します。","respondent":"金子保育課長","answer":"今も申し上げたとおりですけれども、所得税の額が変われば保育料もそれに応じて変わるです。","voiceIndex":179,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"ということは、私が求めた答弁はしませんてしたけれども、しかしながら、所得税が上がれば保育料が上がるということは、所得税が廃止されて、定率減税で、減税分がなくなれば、払わなければいけない保育料は高くなるということですから、保育料も自然に上がらざるを得ないということだと思います。したがって、影響というのは出てくるわけです。父母の負担が上がるということになるわけです。","respondent":"金子保育課長","answer":"保育料に関しましては、前年の所得を、一般的には源泉徴収票、あるいは確定申告等で３月に確定したものに基づいて私どもは保育料の算定をしておりますので、その辺は粛々と作業をするです。","voiceIndex":181,"id":"exchange-074"},{"speaker":"南委員","kind":"質問","question":"どうしても「保育料値上げになる」というふうな表現はしませんね。したがって、品川区としては、来年１月から３カ月分は負担がかかるわけですから、少なくともここの部分の引き下げをするのか、また、再来年度の平成１７年度には定率減税がしっかりかかってくることになりますから、ここの部分を保育料の引き下げの改定をするのか、しないのか、この辺についての答弁をお願いします。","respondent":"金子保育課長","answer":"いろいろ国等の考え方をお示しいただきましたけれども、私ども先ほど申し上げたとおり、いろいろな状況を加味して保育料の目標を持っているというところをどう実現していくかというところを今後とも検討をしていきたいというふうには考えてあります。","voiceIndex":183,"id":"exchange-075"},{"speaker":"南委員","kind":"質問","question":"それはそれとして、要するに、定率減税の部分の縮小、廃止の部分も、大きな負担に反映してくるということですから、やっぱりこれはきちんと条例を改定して、保育料を引き下げるということで、負担をかけない、厚生労働大臣の答弁のような、これ以上の負担はさせないという、そういう立場で保育行政をしっかりしていただかないといけないんじゃないかというふうに思うんですけれども。","respondent":"中尾根企画部長","answer":"ただ、先ほどるる委員のほうからいろいろありましたけれども、私どもとすれば、国の動きなどの環境が今すべて委員がおっしゃったように、そのように動くのかどうか、これは今後の問題で、もっと検証をしなければ、そのことについて今の時点でどうなんだ、答えを言えといっても。","voiceIndex":185,"id":"exchange-076"},{"speaker":"南委員","kind":"質問・要望","question":"というのは、そうじゃないんですか。国の方向に沿っていかない、そういう答弁、姿勢を品川区政は持っているというふうに理解せざるを得ないんですけれども、再度確認しますけれども、いかがでしょうか。ですから、子育て支援という観点から、保育料をしっかり見ていただきたいという点で質問をしているつもりですけれども、そこも含めて、先ほどのところをご答弁をお願いします。","respondent":"小沼児童保健事業部長","answer":"総合施設というのはこれから伸びていきますと、当然のことながら料金体系を含めて、あるいは処遇の中に含めて、大きく変わらざるを得ない、また変わって当たり前だというような大きな状況変化がありますから、先ほど保育課長が申し上げたように、国のさまざまな動向。","voiceIndex":187,"id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"しかしながら、いろいろな社会情勢が変わって、経済情勢もこんなに変わってきている中で、経済的支援を本当に皆さんは強く求めていらっしゃいますよね。そういう今の状況の中で、国の施策の中で重い負担がかかってくるという状況になったときには、これはきちんと防波堤になって、保育料の引き下げも英断を持ってやるべきだということを強くお願いして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-078"},{"speaker":"田中委員","kind":"質問・要望","question":"先に都市計画のほうからお伺いをいたしますが、午前中の企画財政課長のご説明では、昨年度と比較して約２億円の減少だということのご説明の中に、事業が一定程度進んできている、需要がないということのお話でございましたが、改めて昨年と比較して約２億円削減された、この辺の状況についてお聞かせをいただきたいと思います。","respondent":"藤田都市計画課長","answer":"今回、都市計画交付金として現在予定されておりますのが補助２０５号、補助１８号、補助３２０号、補助１６３号、補助３０号ということで、事業のほうが大分進捗してきてありますので、そうした中で事業量のほうが費用として２億円ほど減になってきているというものです。","voiceIndex":191,"id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"予算編成上の考え方と言いますか、そういう視点でお伺いをしたいんですが、昨日の補正予算のときのことでは、交付金を増やす一つのテクニックが昨年度の中にはあって、ただ、相手のあることなので事業執行ができなかったので、それ相当の更正減額になったということですが、今回も平成１７年度予算もそういったテクニックも含めた上で、昨年と比較して約２億円減ってしまったのか、その辺も含めて。","respondent":"市岡企画財政課長","answer":"この都市計画交付金の歳入の内訳を少しご紹介しますと、大きく落ちているところは目黒線の立体交差事業、次に補助３２０号、このあたりは事業が進捗をしましたので、幾ら枠を取ると言っても、これも客観的な事業量ですから、あまり根拠のない都市計画交付金の。","voiceIndex":193,"id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"こういった状況の中で、確かに今ご答弁のように、いわゆる必要もない都市計画事業を水増しするということは当然あってはならないことでありますが、都市計画需要というものは実はこれだけあるんだといった、それが現実的な要素があって初めて予算上に反映されるわけですが、そういった予算にはいっとき反映はされないけれども。","respondent":"市岡企画財政課長","answer":"いろいろありますけれども、当面私どもは、区長もそうですが、交付率、今は事業費の２５％をはさんで、最大で３５％までしか交付率が認められておりませんが、これをもっと引き上げることによって２３区全体の事業意欲も。","voiceIndex":195,"id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"この合計によって事業がなされるわけですが、２５％、あるいはそれを意欲を示していただいて、増えたとするならば、逆に言うと、これまで財調として手当てされていたものが減ってしまうのかどうかということと、もし仮に減らないとするならば、これは一般財源化として、他の施策に転用できるという考えが仮にできるとするならば、そういった視点からも、２３区にとってより交付率を高めるということが。","respondent":"市岡企画財政課長","answer":"ご趣旨のとおり、これは全体として２３区の財源保障機能を高めるという意味で、財調と都市計画交付金で相殺されたのでは意味がありませんので、全体としては区側のこれから切実な区民の需要をしっかり財調なり都市計画交付金なり。","voiceIndex":197,"id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"続きまして、もう一つ、学校施設整備費も主要５課題の一つの視点からお聞かせをいただきたいと思います。都側としては、これまでの財調の算定の中に改築分も含まれているのでといった主張もありますが、中には、他の２２区においては、これもすでに使い切ってしまっている等々があるようですが、改めて品川区においての、将来の改築需要に対する現状についての状況をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"東京都の言うように、５０年に１校ずつずっと、私どもで言えば、小中学校すべてが均等に建て替えるのであれば、東京都の言っていることもあながちわからないわけではありませんが、そんなことでは現実の改築に対応できないというところから。","voiceIndex":199,"id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"そのような姿勢で臨んでいただきたいんですが、１点、気になるといいますか、先日の文教委員会でもお示しをいただいた、これまでさまざまな公共施設の耐震診断がなされて、その中でも学校の診断もなされたと。このことが学校の５課題のほうに影響があるのかどうかという部分で確認なんですが、まず改築をするにあたっての財源をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"ただ、いずれにしても、これらは補助金の単価と、実勢単価とがかなり開きがありますので、２分の１だ、３分の１だと言っても、実際に国庫負担金、補助金は実績から言って、建設費全体の１割程度というのが実際のところです。","voiceIndex":201,"id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"要は、耐震という視点から改築、国の一定のお金が入っているために、５課題のほうで言うところの財調手当てを減額されてしまうというようなことがあってはならないと我々は思うんですけれども、その辺の見方をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"あまり時間がありませんので、簡単に申し上げますと、言ってみれば、そういう制度矛盾を内包したような財調算定は、これはだれのための算定かというと、東京都が財源を絞りたいための算定につながりますので、絶対そういうことのないように。","voiceIndex":203,"id":"exchange-085"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそのような主張でお願いしたいのと同時に、もう一つ、とは言いながらも、今は少子高齢化社会が進んでおりまして、子どもの数も減っているという現象が、長期レンジではまだ一定程度進んでしまうのかな。そういう視点も含めて、大変デリケートな話かもしれませんが、いわゆる学校の適正な配置という視点でのお考えをぜひお聞かせいただきたいと思います。","respondent":"谷田部学務課長","answer":"４０校ないし１８校を選んでいただくということで、その学校を選んでいただく保護者やお子さんがいる限り、私ども現在の学校数を維持していきたいという考えを持ってあります。","voiceIndex":205,"id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"私は、７４ページ、総務使用料、１３２ページ、諸収入、１４２ページ、議会費、時間がありましたら、学校施設使用料をやらせていただきます。議会費についてお伺いいたします。議会費の中で海外調査費７４０万円と出ております。これは実際、その調査した後報告書等の本を出版していると思うんですけれども、この金額を含めて７４０万円なのか、それは別項目になるのか、その辺をもし分かればお聞かせ下さい。","respondent":"福田区議会事務局長","answer":"海外調査の報告書経費につきましては別に計上をしているものです。","voiceIndex":209,"id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"私の聞いたところによりますと、総額１,０００万円かかっているという話を前に聞いたことがあるんですけれども、もしそういうことならば、海外調査費ということで、議会で派遣されているんですから、ここに項目として出ているんですから、総額を書くのが筋じゃないかなと思うんですけれども、いかがでしょうか。","respondent":"福田区議会事務局長","answer":"これは予算の説明欄ですけれども、どちらが分かりやすさを重視するかという問題だろうかというふうに思われます。","voiceIndex":211,"id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"どちらを重視ということですけれども、一般的に会計報告ということならば、また、予算報告ということならば、やはりその項目ごとにきちっとやっていただけたらと思います。議会のほうも、きのうもお話ししましたけれども、インターネットで今放映している市もあります、自治体もあります。そういう方向で、議会のほうも放映についてそういう方法論をとるような考えはないんでしょうか。","respondent":"福田区議会事務局長","answer":"そういう方向性をとるかどうかということにつきましては、これは典型的な議会運営上の課題でございまして、議会運営委員会という所管の委員会を通さざるを得ない、かように思います。","voiceIndex":213,"id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"引き続きまして、学校施設使用料についてお伺いいたします。地域、地域の小中学校がその場所で使う人がいるわけですから、その人たちを優先するならば、そういう形で、パソコンを使って申し込みできるようなシステムを早急にとらないと、私は２年前から言っているんですけれども、いまだに手で書いて、３０団体が月曜日、火曜日、水曜日、木曜日、金曜日、土曜日、日曜日と並べていくわけです。","respondent":"上川内生涯学習課長","answer":"私どものほうも４連複写の下のほうにいくと文字が薄くなってしまうような状況は分かっております。今後これをどうにか効率よくやっていかなければならないということで、検討にとりかかろうですので、いましばらくお時間をいただきたいと思います。","voiceIndex":215,"id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"毎月１日、夜７時集合です。このようなシステムは、区民の皆さんの利便性を最優先で考えてほしいですね。やはり皆さん学校を使いたい、使うにあたって、ほかの地域センター、または運動施設は、インターネットで申し込めるところもありますし、各文化センターもパソコンで申し込めるという時代になっているんですから、今後早急に改善していただければありがたいなと思います。夏は水泳場もあります。","respondent":"榎本行財政改革担当課長","answer":"それと、あとは、水族館もあそこのところで今回リニューアルをして、さらに団体施設の利用もできるようなところもつくろうということで、さらに利用価値が増すような形で改築をしていくという形ですので、それぞれの使い方によって、訪れる方が喜んでいただけるような。","voiceIndex":217,"id":"exchange-091"},{"speaker":"須貝委員","kind":"意見","question":"今、品川歴史館の話が出ましたけれども、あそこの資料を、住居跡を壊せというのではなくて、ほとんど展示物で、あそこに置いておいたら、見ない方、触れない方がいっぱいいるんです。だったら、大勢集まるところに一部でもいいから展示物を持っていって、そういう工夫というのはあっていいんじゃないか。せっかくの品川区の資料をもっと有効に使っていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-092"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうから３点お伺いいたします。一つ目に１３０ページの競馬組合配分金に関連して、二つ目には６４ページ、集会所使用料、三番目、１２６ページ、東京臨海高速鉄道に関連してお伺いいたします。そういう意味で、我が党としても、一昨年ですか、要望もいたしました、アニマルセラピー、ホースセラピーとかあります。","respondent":"宮地総務課長、西島障害者福祉課長","answer":"これにつきましては、相手方の飼料会社のほうが損害額については非常に誠意を持って対応するという答えをいただいておりますので、今後組合との間で金額や支払い方法について具体的な協議に入るというふうに伺っております。引き続き検討課題とさせていただきたいと思います。","voiceIndex":222,"id":"exchange-093"},{"speaker":"嶋委員","kind":"質問・要望","question":"そうしますと、小さいお子さんも、障害者だけでなくて、これから教育の現場でも体験学習、あそこでは宿泊もできますので、宿泊体験学習とか、ポニーもやっている場合もありますし、また、一時女性の乗馬体験クラブもやっていたかと思いますが、そういう意味で、今後そういう教育の現場とか、体験学習、また宿泊体験、午前２時ごろから起きて調教をなさったりとか、えさのあげ方、先ほどもお話ししたように。","respondent":"宮地総務課長、西島障害者福祉課長","answer":"競馬組合のほうも少しでも親しんでもらおうと、それから、売り上げの向上にもつなげたいということで、さまざま何かアイデアはないかということで、あちらも模索をしているようですので。動物とふれあうことは、先ほどお話ししましたように、効果がある部分もありますが、本人の好き嫌い等の問題もあります。どのようにしたらいいかということも含めまして検討をさせていただきたいと思います。","voiceIndex":225,"id":"exchange-094"},{"speaker":"嶋委員","kind":"質問・要望","question":"次に移らせていただきます。６５ページの集会所の使用料についてですが、荏原第一地域センターについてお伺いをします。今回リニューアルをした部分がありますが、その後、施設を使用する方たちから何か現場の声を聞いていらっしゃるのか、私が聞いている部分では、使い勝手が大変悪くなっているということでお聞きをしておりますが、何か届いておりましたら、お聞かせをいただきたいと思います。","respondent":"田村地域活動課長","answer":"荏原第一地域センターは最近リニューアルというよりも、若干ここのところ利用のときに空調機が故障したり、あるいは上の住宅の部分から水漏れ等をして、一定の期間利用ができなかったということで、抜本的な改革としても、大成温調に委託しているんですが。","voiceIndex":228,"id":"exchange-095"},{"speaker":"嶋委員","kind":"質問","question":"そのぐらいしか届いていないんでしょうか。ここは今まで高齢者の方がダンスで大変使い勝手が良いということで、評判のいい講習室があったんですが、今回残念ながら、滑らなくて、足が痛くなって、とてもダンスができる状況ではないということで、今あるサークルがほとんどここを使えなくて、大変遠いところの会場探しで困っているようです。そこら辺をお答えをいただけたらと思います。","respondent":"田村地域活動課長","answer":"トイレにつきましては、区民集会所すべてですが、今のところ通常のトイレを設置しているような状況です。","voiceIndex":230,"id":"exchange-096"},{"speaker":"嶋委員","kind":"質問・要望","question":"普通の方が使うには滑らなくされたのかもしれませんけれども、ダンスサークルが、今まであんなに月に何回も使っていた方たちが１回も使えなくなったということは、大変悲しいことですので、今後手を加えられる予定があるのかだけお聞かせいただきたいと思います。","respondent":"田村地域活動課長","answer":"先ほど申し上げましたが、平成１５年度一定の手を入れたので、来年度は特に荏原第一地域センターについてはリニューアル等の経費は見込んでおりません。","voiceIndex":232,"id":"exchange-097"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ高齢者の方たちが元気に戻っていらっしゃるようにご配慮をいただけたらと思いますので、よろしくお願いいたします。次に、１２６ページの東京臨海高速鉄道ですが、これに関連して、今回地震がいろいろございました。そういう意味で、事業主の品川区として、地震のときに、そういう対策とか、どういう周知をされるように連絡をとっていらっしゃるのか、お聞かせいただきたいと思います。","respondent":"藤田都市計画課長","answer":"現在私どもといたしましては、臨海高速鉄道の会社のほうにそういったことで早期にお知らせができるような設備を設置してほしいということで要望をしています。","voiceIndex":234,"id":"exchange-098"},{"speaker":"嶋委員","kind":"質問・要望","question":"鉄道といいますと、区民が始発という部分では大変期待が大きいものですが、りんかい線については、始発に関しては直通の電車になっていないということで、区民の方が、せめて始発は直通にしていただくと、区民サービスになるのではないかというご意見がありますが、そこら辺のご意見をお聞かせいただきたいと思います。","respondent":"藤田都市計画課長","answer":"始発ですけれども、大崎から始発になると、どうしても乗り入れができないという形になりますので、新木場方面からきたときの、新木場での始発になりますけれども、その電車については乗り入れをこれまで以上に本数を増やせるように。","voiceIndex":236,"id":"exchange-099"},{"speaker":"本間委員","kind":"意見","question":"私からは、使用料及び手数料の件で、６４ページから、集会所使用料についてお尋ねします。もう一つは、７５ページ、自転車駐車場使用料についてお尋ねします。ここに示されている定期利用、一時利用のそれぞれ台数と金額が出てきておりますが、この状況は、数字が物語っていると思いますけれども、利用率についてどのように判断をしたらいいのか、飽和状態なのか、まだ余力があるのか等も含めてお尋ねします。","respondent":"山口交通安全担当課長","answer":"利用率については、２月末現在ですが、全体で６２.５％となっております。利用率の高いところについては大崎西、五反田、戸越、大井町西、西大井、青物横丁、立会川等となっております。","voiceIndex":240,"id":"exchange-100"},{"speaker":"本間委員","kind":"確認","question":"かなり高い利用率だというふうに判断いたします。最近有料駐輪場の近くの路上に放置をされている自転車を見ます。その辺の事実確認といいますか、状況についてどのように把握されておりますでしょうか。","respondent":"山口交通安全担当課長","answer":"駐輪場自体は駅周辺が主なんですが、昨年の調査によりますと、詳しい数字を申し上げますと、駅周辺で４,５００台です。","voiceIndex":242,"id":"exchange-101"},{"speaker":"本間委員","kind":"質問","question":"尋ね方について漠然としすぎていてごめんなさい。放置自転車禁止区域以外の部分ということですが、今の数字で大体よろしいでしょうか。","respondent":"山口交通安全担当課長","answer":"これについては駅周辺と、放置禁止区域ならびに放置禁止区域外も入りますが、主に放置禁止区域内を重点として調査しております。","voiceIndex":244,"id":"exchange-102"},{"speaker":"本間委員","kind":"質問","question":"放置禁止に括られたところ以外にもあるというふうに判断します。いわゆる駅周辺で４,５００台と言いましたが、それを越えるものが周辺にも存在しているです。お尋ねしますが、その中で、１カ月、３カ月、６カ月というような部分ですが、定期利用の期限の切れた部分についてはどのように対応をされていらっしゃるでしょうか。","respondent":"山口交通安全担当課長","answer":"その都度月ごとに契約者の調査をしまして、期限の切れた定期利用者については、調査の結果、札をつけて、一定期間連絡等をして、引き取るようにしております。","voiceIndex":246,"id":"exchange-103"},{"speaker":"本間委員","kind":"意見","question":"毎月そのような調べはしているということでございましたが、これは蒸し返すことはよろしいことではないんですけれども、１年も前のオートバイの部分があったことがありますので、その辺もどのようなきちんとした管理がされているのかということでお尋ねをさせていただきました。","respondent":"山口交通安全担当課長","answer":"防犯カメラも全有料駐輪場については設置しておりますが、いたずらをされたとか、また壊されたとか等の事故的な報告は今のところ受けておりません。","voiceIndex":248,"id":"exchange-104"},{"speaker":"本間委員","kind":"意見","question":"職員の部分についてお尋ねしますが、現在はシルバー人材センターから派遣されているというふうに聞きましたか、この人々の労働条件について一、二聞いてみたいと思いますが、前品川区から雇用されていた段階と、シルバー人材センターから派遣されてきたときの単価の切り下げが行われたように思われますが、その辺の契約の仕方等について、もしお分かりでしたら、お答え願います。","respondent":"山口交通安全担当課長","answer":"管理人の方については、一部常駐のところもありますが、他は巡回等となっております。経費節減の関係で、ほかの横並びといいますか、他の時間給等を勘案して、時間給の見直しをしたところです。","voiceIndex":250,"id":"exchange-105"},{"speaker":"本間委員","kind":"質問・要望","question":"次にいきます。集会所使用料につきましてたくさん出ております。４桁で利用されている集会所もあれば、３桁の低い回数のところ、さまざま出てきておりますが、それぞれ数字がその利用状況を物語っているのではないかというふうに思いますが、特にこの中で、幾つかありますが、すべてを聞く時間がございませんので、西中延にあります平塚橋会館の回数についてはどのように受け止めたらよろしいでしょうか。","respondent":"田村地域活動課長","answer":"平塚橋会館の利用状況ですが、集会室の利用が平成１６年８月末現在で、一般の集会利用が４９７件、平成１５年度で、一般の集会所の利用件数が１,１７６件、平成１４年度が１,１５４件です。","voiceIndex":252,"id":"exchange-106"},{"speaker":"本間委員","kind":"質問","question":"６７ページにある平塚橋会館３０６回という数字の部分が合わないのでびっくりいたしておりますが、いずれにしましても、平塚橋会館は葬祭利用という部分が残っておりますね。この部分につきましては、平塚橋会館と葬祭利用も含めて、将来的な見直しというふうなことでお話は聞いているわけですが、地域住民の葬祭利用についてのご意見はいかがなものでしょうか。","respondent":"田村地域活動課長","answer":"そういう意味から、荏原第３の町会長会議に私のほうでお伺いしまして、こういう見直しについてのご意見等を私のほうからご説明して、ご意見をもらいました。","voiceIndex":254,"id":"exchange-107"},{"speaker":"本間委員","kind":"質問","question":"特に西中延というのは住宅の密集地域ですね。それから、入口の整備の部分が何か不自然に思います。おそらく車椅子利用の方のサービスとしてあのような形にしたのかもしれませんけれども、一般の人たちはかなり大股で上がらなければならないような部分も出てきておりますので、その辺のお考えがありましたら、お願いします。","respondent":"田村地域活動課長","answer":"それ以外に１階の斎場として使う部分の照明を明るくするとか、ご指摘のあった、２階の会議室の防音設備を何とか工夫できないか、入口のほうも暗いのではないか、駐輪場のところも薄暗いので、何とかできないだろうかというようなことで、３月１１日から年度内に手を付けて。","voiceIndex":256,"id":"exchange-108"},{"speaker":"本間委員","kind":"質問・要望","question":"新しく生まれ変わって、地域コミュニティの活動拠点として頑張っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私ども自民党からさまざまな問題点を指摘しておりますけれども、ここで確認だけしておきたいのが、公的住宅に求められる社会的な公平性が一つ。そういう中で、なぜ２,０００件を組んだのか。もしかして新しい、品川区のほうから売り込みをかけるわけでも何でもないでしょうから、何かしらの意図があってこの２,０００件という数字を決めてきたと思われますので、そのことの考え方をお聞かせ下さい。","respondent":"阿部住宅課長、冨田戸籍住民課長","answer":"その中では、今申し上げました保有資産についても審議が進められるというふうに聞いてありますので、その動向を見極めていきたいというふうに考えてあります。住基カードの発行件数予定ですけれども、２,０００件と組んだ理由ですが、現在は毎月七、八十件受けております。","voiceIndex":260,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問・要望","question":"住宅のほうは確かにそうです。法律が変わらない限りは品川区はどうしようもないということは分かりきっておりますけれども、実際は資産が評価されないということは、いろいろな問題が起きていることも事実です。そんなあいまいなことでいいんでしょうか。それで去年は６４８件だった。それがなぜ今年２,０００件なのか、もう少し具体的な答弁をいただければありがたいんですが、いかがでしょうか。","respondent":"冨田戸籍住民課長","answer":"もちろん条例化する必要があるんですけれども、現在のところその予定はございませんけれども、全体的には国の交付率が昨年の８月現在で０.２８％、品川区の場合には０.４％ということで、全国平均よりも上向いている状況にはあります。","voiceIndex":263,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"これも事務事業評価には月平均で６８戸の入居だと。でも、最も重要なところであるところの職員住宅とか、職員待機寮等々に職員の皆さんが常にいるということから、具体的なところから始めていきませんと、そういう具体的ものが生きてこなくなりますので、ここでは職員の意識の向上とか、職員住宅に入るための確保策、職員の研修等々はどうされているんでしょうかということをお聞かせ下さい。","respondent":"桑村人事課長","answer":"採用も若干始めてまいりましたし、待機寮そのもの自体についての入居についての心配はあまりないけれども、委員おっしゃったとおりの、いわゆる防災に対する体制についてはまだこれから検討をする必要があるというふうに思ってあります。","voiceIndex":265,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それはそれでいいんですが、冷静に考えていって、品川区に災害が起きた瞬間にいる職員の皆さんが貴重な人材となるわけであって、となれば、品川区に住んでおられるところであります職員住宅にお住まいの職員の皆さんとか、待機寮の職員の皆さんの意識とか考え方、それをどう組織づけていくかということまで落とし込んでいきませんと、万が一のことがあった場合には。","respondent":"久保田防災課長","answer":"今話題に出ました待機寮職員につきましても、毎月１回定期的に訓練をしておりまして、待機寮につきましては、消火ポンプ、通信訓練等々で、緊急の災害対策本部ができたときにはある程度対応できるような知識なり、あるいは技術を身に付けてまいっております。","voiceIndex":267,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問・要望","question":"最後に要望だけしておきますけれども、何度も言いますが、体制をつくって計画をつくるのは幾らでも構わないんですが、要は、そこにどれだけの職員が瞬間にいるかということが勝負になってきますので、この職員住宅、待機寮の皆さんは非常に貴重な職員なわけでありますから、ぜひその皆様方の活用と、十分な防災意識の向上をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-114"},{"speaker":"飯沼委員","kind":"提案","question":"私からは、８８ページの国庫支出金、１０２ページの都支出金の中で、障害者保健福祉関係についてお伺いをしたいと思います。２００５年障害者の保健福祉が大きく変わろうとしています。質問をしますけれども、改革のグランドデザインと、障害者自立支援給付法の内容を教えていただきたいのと、今後のスケジュール、そして区の予算への影響を教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"区への予算への影響ですが、先ほどお話ししましたように、自立支援法は骨格法ですので、まだ具体的な数字等が、例えば利用者負担についても、４区分に分けるというような話が出ている段階ですので。","voiceIndex":271,"id":"exchange-115"},{"speaker":"飯沼委員","kind":"質問","question":"内容のことなんですけれども、一つは、今後のことなので、詳しくはわからないとは思うんですが、支援費ができてまだ２年も経っていない状況の中の、変化の中で、利用者の立場として、どこがどう変わるのか、利用者として受けられていたものが受けられなくなるのかどうかというのが最も心配だと思うので、支援費との違いをひとつお伺いしたいのと、区民にとって一体どこが一番影響が大きい。","respondent":"西島障害者福祉課長","answer":"どこが変わるかというところは大変難しい質問ですが、一つは、一番大きいのは、医療費の公費負担も含め、応益負担ということで、利用者負担制度のあり方が変わるということが一番大きいかなというふうに思っております。","voiceIndex":273,"id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問","question":"決定に係わるところはかなり改善をされていくのかなと思うんですが、私が伺っている最も大きな心配は、今おっしゃった応益負担の導入のことです。","respondent":"西島障害者福祉課長","answer":"利用者負担の問題ですけれども、これは厚生労働省の出している数字ですけれども、支援費制度の、居住関係で言いますと、実行の負担率が１.３％である。","voiceIndex":275,"id":"exchange-117"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害者がホームヘルパーなどを利用すること、これは益ではなくて、生活と権利を守るための当然の権利ではないか、障害者の方はこうおっしゃっているんですが、私はこの辺の応益負担ということは、福祉にそぐわないのではないかなと思うんですが、その辺を１点お答えいただきたいと思います。","respondent":"西島障害者福祉課長","answer":"例えば年金手当の支給というものがありますけれども、現在年金手当を合算して最大で月額１８万５,０００円ぐらいの支給という方もいらっしゃるという状況等を考えますと、必ずしも応益負担即悪だというふうには言えないのではないかというふうに考えているところです。","voiceIndex":277,"id":"exchange-118"},{"speaker":"飯沼委員","kind":"質問・要望","question":"脳性麻痺で、障害基礎年金の１級の方が、ある本に投稿されているんですが、「現在障害者福祉改革の中で、今まで応納負担だったものが、応益負担となり、利用者の１割負担が打ち出されています。１割負担が導入されると、無理をして生活をしなければなりません。私は、ぜひこの辺で障害者の方を守る立場で応益負担に対して反対の立場をぜひとっていただきたいなと思うんですが、再度よろしくお願いします。","respondent":"西島障害者福祉課長","answer":"現在でも居宅と施設では負担の率が違うということもありますので、一定その部分の改善というのは今後図られていくべきではなかろうかというふうに考えているところです。","voiceIndex":279,"id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、ぜひこの際、障害者の方々の現状をしっかりと実態を調査をしてつかんでいただきたいと思います。自立をして、社会参加をするというところで、ハンデのためのケアは本当に大事だと思いますので、実態調査をしていただきたいのと、開かれた説明会をしていただきたいと思うんですが、よろしくお願いします。","respondent":"西島障害者福祉課長","answer":"その点に関しましては、私どもはケースワーカーが一人ひとりお訪ねをして説明をしていますし、今度の制度改革につきましても、丁寧な説明に心がけていきたいというふうに考えているところです。","voiceIndex":281,"id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"教具費の件から、ここに入るのかどうかちょっとわからないんですが、国の補助金なのか、資金の中で、スクリーンと、マルチプロジェクターの補助という形で、小学校、中学校に支給するという、それが予算化されたという話が以前あったと思うんですが、それがなくなったというふうに聞いているんですが、その辺はいかがでしょうか。","respondent":"谷田部学務課長","answer":"ここで言う教具費ですけれども、理科教育振興費国庫補助金でございまして、理科、算数、数学の教具を購入する際に国のほうの補助があるということで、例えば小学校の理科ですと、計量器、長さとか、重さとか、その辺の天秤のたぐいとか、それから、実験機械器具とか。","voiceIndex":284,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほど私が申しましたスクリーンとマルチプロジェクターについては、国のほうの補助が出るという話についてはいかがでしょうか。過去にそういう経緯があったのか、それがなくなったというふうに聞いているんですが、その経緯がお分かりになれば教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"私が３年目になりますけれども、この間そのようなことは聞いたことはないです。","voiceIndex":286,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"今年学校関係の中では全員の教員にコンピュータを配置するということがありますので、それらを有効活用という意味もありまして、全教室にスクリーン、マルチプロジェクターを入れることで、教材のやり方もいろいろ変わるでしょうし、指導方法も変わるのではないかなということで、非常に期待をしていたんですけれども、そういう経緯がないということであれば、歳出になってしまうかもしれないんですけれども。","respondent":"谷田部学務課長","answer":"先ほど申し上げましたけれども、あくまで教具ですので、プロジェクターとかそういうものは、私どもでは校具というふうに指導しておりまして、実際に児童・生徒が学習で使うものを私どもは教具と言っておりまして、ですから、コンピュータ関係で言えば。","voiceIndex":288,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"ファミリーサポートセンターの件ですが、これが国等の補助金があるわけですけれども、品川区でいうと、家庭あんしんセンターの中にファミリーサポートセンターというのがあるんですが、家庭あんしんセンターというのはいろいろ機能を持っておりまして、いろいろな事業をされているんですが、それらに対して国、東京都の補助金があるのかどうか、それと、区の持ち出しの部分がどういう事業にあるのか。","respondent":"辻田児童課長","answer":"私どものほうは家庭あんしんセンターと申しておりますけれども、そこの中にはひまわり荘という母子支援施設、それと子育て支援センター、ファミリーサポートセンター、障害者の生活支援センターというような形の四つの機能をその中で実施しているです。","voiceIndex":290,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"それと、補助金に対して、今１カ所ですけれども、それが２カ所、３カ所と増やすと、この補助金の制度がどういうふうな形、その分だけ増えていくのか、それとも大枠が決まっていて、補助金はもう出ないということになってしまうのか、その辺はいかがでしょうか。","respondent":"辻田児童課長","answer":"子育て支援センターにつきましては、ぷりすくーる西五反田の中にある子育て支援センターは、子育て広場事業のＢ型というような形で位置づけをされまして、東京都のほうから補助金が３分の２出ているという状況です。","voiceIndex":292,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"ファミリーサポートセンターという形の機能があると思うんですが、それはほかのところでは、当然家庭あんしんセンターの中での事業ということでの理解でよろしいんでしょうか。","respondent":"辻田児童課長","answer":"そういう中での事業展開拡大ということをひとつ考えていく中で、今後東京都のほう、それから委託先の福栄会とも検討をしていかなければならないです。","voiceIndex":294,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"７１ページの健康センターについてお尋ねをしたいと思います。健康センターですと、今委託という形でやっているんですが、コース型とか、オープンスクールとかという形で、いろいろ利用方法があるんですが、どういう回数がここに載っているのか、それをまずお聞きしたいと思います。","respondent":"田中健康課長","answer":"健康スタジオおよびトレーニングルームといいますのは、７万４,４００回というふうになってありますが、これはフリー利用のことを指しています。それから、その下の講座は、トリムスクール、コース型の教室を回数として延べで入れております。","voiceIndex":296,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、講座のほうもかなり拡大している、それからオープンスクールの利用者も拡大が予測されているということですが、曜日によっては非常に利用率が高いという部分がありまして、現状の教室の中では人数を増やしていくというのがちょっと難しい部分があるかなというふうに思うんですが、今の施設だけを考えた形でこういう回数になっているのか、それとも将来的に、７階にホールがあるんですが。","respondent":"田中健康課長","answer":"７階のホールというようなお話も実は１回あったことがありますけれども、あそこはあそこでかなりの利用がありますので、貸出施設としての役目ということで、現状ではそこの部分をコース型、フリー利用の中で利用するということは現在は考えておりません。","voiceIndex":298,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"２つ指摘をしたいと思うんですが、プログラムを見ると、スタジオのところで空いているところが結構あるんですね。これは非常にもったいないと思いますので、この辺の拡大をぜひ考えていただきたい。その場合にはなかなか収容しきれない現状の中で、できないという実態もあるようですので、そこら辺はホール等とも有効活用もぜひ考えていただきたいと思いますが、その辺はいかがでしょうか。","respondent":"田中健康課長","answer":"ただ、あれだけの広さのものというのは、なかなかほかに確保しがたいので、事業等で押さえてしまいますと、一般区民の方、健康センターというだけでなくて、貸し出しの施設という考え方の中では貴重な施設かと考えていますので、私どもはいろいろな工夫を事業者のほうと。","voiceIndex":300,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"そのための利用者の変動がどういうふうになっているのか、ここは金額しかわからないんですが、例えば具体的に言いますと、１人に対する負担感が増えているのか、利用者が夜間はなるべく使わないようにということで、早く家に帰ってという努力を見ることができたのか、その辺の動向はいかがでしょうか。","respondent":"金子保育課長","answer":"単純な比較が難しいんですが、例えば全体として前年度より伸びているという傾向がそもそもありまして、それをベースに比較すると、１０月以降、今までと比べると１０％ちょっと利用者が減っているというのは、数字で現在確認をしています。","voiceIndex":302,"id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"特に延長保育というのは、なるべくご両親が努力されて、子どもたちと一緒に過ごしていただく時間を増やしてほしいという気持ちが非常に強くあります。負担感についてはいかがでしょうか。例えば意味合いが分かって、家族と一緒にというように利用されているのであればいいんですが、そうではなくて、負担は仕方ないという形でというようなクレーム等々があれば、いかがでしょうか。","respondent":"金子保育課長","answer":"私どもとしましては、委員ご指摘のとおり、必要な方には利用していただきたいけれども、不必要な方にはなるべくご家族で必要な時間を過ごしていただくというのを基本的に考えておりまして、日常的に園長、副園長をはじめとして保育士のほうもそういう指導をしています。","voiceIndex":304,"id":"exchange-131"},{"speaker":"中島委員","kind":"質問・要望","question":"私は、７４ページの区民住宅使用料、そして、時間があれば、９４ページの土木費の都市計画道路整備費について、関連してお伺いしたいと思います。区民住宅の使用料ですが、１６億８６９万５,０００円という使用料が入っております。この建設の財源、そういったものがどういうふうにたてられたのか、そして上がってきた使用料がどのように収益が生かされているのか、その辺の流れを初めに教えて下さい。","respondent":"阿部住宅課長","answer":"建設の経費ですけれども、国および東京都の補助金があります。例えば一番直近で区民住宅を建てたのが西五反田の東館４００戸ですけれども、それについては用地費についても家賃対策費の前倒しということで補助金をいただいております。は一般財源ということになります。","voiceIndex":307,"id":"exchange-132"},{"speaker":"中島委員","kind":"質問","question":"区民住宅というのは中堅所得者向けということで、昨年も２.２倍という競争率があったというふうに伺っております。その前には借上げ型の区民住宅もあると思うんですが、こうした両方を含めて家賃を滞納をされるような人も中には出てくるのかなと思うんですが、この辺のところはいかがでしょうか。","respondent":"阿部住宅課長","answer":"ただ、現年度につきましては、平成１５年度の収入で９９％を超えてあります。今年も去年を上回るような形で収入をしています。というのは、滞納者については早め早めの対応が第１だですので、まず現年度分の収入を上げていく。","voiceIndex":309,"id":"exchange-133"},{"speaker":"中島委員","kind":"質問","question":"非常に回収率がいいということを伺いました。最近私どものところに、親御さんが高齢になってしまって保証人の条件に当てはまらない、そして、今こういう時代ですから、なかなか保証人が見つからない。保証金制度というのがあるのではないかという問い合わせがありました。都民住宅などでは機関保証制度というのがあると思うんですが、これに代わるものは区では導入できないんでしょうか。","respondent":"阿部住宅課長","answer":"ですから、２年経てば更新という制度がありますけれども、区民住宅は更新という制度がございませんので、その点で一般の保証会社を即区民住宅に導入するということは難しい面もあるのは事実です。","voiceIndex":311,"id":"exchange-134"},{"speaker":"中島委員","kind":"質問","question":"確かに一般の保証制度というのを利用するのは難しいと思うんですが、時代から見て、現実的には全部連帯保証人を付けて入っていらっしゃると思うんですが、先ほど伺いましたら、滞納されている方にも再度督促状を送っていると。連帯保証人から取り上げるようなことはしていないのかなと思ったんですが、そこのところをちょっと教えて下さい。","respondent":"阿部住宅課長","answer":"連帯保証人の方に支払っていただくというのは現に今年もございました。今年退去なさった方でしたけれども、ご本人が払えないという状況を当然連帯保証人の方もご存じですので、連帯保証人の方に支払っていただいたという例もあります。","voiceIndex":313,"id":"exchange-135"},{"speaker":"中島委員","kind":"質問","question":"数少ない一つの例だったかと思うんですが、いずれにしましても、こういう保証金制度というのは今後導入する方向に向かっていけるのかどうか、この辺のところをお伺いしたいと思います。区としても、これは小規模ですから難しいことは分かりますけれども、何らかの策を立てて、その辺の努力をしていくということが必要ではないかと思うんですが、その辺もう一度ご答弁をお願いします。","respondent":"阿部住宅課長","answer":"ただ、その場合には、例えば毎月の使用料に上乗せをするとかということをやってありますけれども、その辺、例えば民間会社を使った場合には上乗せということはできませんので、例えば民間でやっているようなカード会社を利用できるのかどうか、あるいは先ほど言った。","voiceIndex":315,"id":"exchange-136"},{"speaker":"中島委員","kind":"質問・要望","question":"これは任意で連帯保証人をつけたり、機関保証制度を使うとか、そういった任意でやっていくべきだと私は思っておりますけれども、その辺の努力を要望しておきたいと思います。","respondent":"藤田都市計画課長","answer":"都市計画上は、その隣に一般道路としてつながる計画になってあります。現在国土交通省のほうでその辺の具体的な事業認可をすでに取得をしておりまして、どんな形で工事をやったらいいか、その方法の検討をしているというふうに確認をしています。","voiceIndex":317,"id":"exchange-137"},{"speaker":"中島委員","kind":"質問・要望","question":"この問題については、過去に私の先輩の議員が一般質問で質問をしておりますけれども、歩道とか、自転車で通れるような道路を実現してほしいという要望もしております。そういった意味も根底に置かれて、ぜひ前進するように交渉のほうをよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-138"},{"speaker":"石田委員","kind":"確認","question":"８４ページの建築確認手数料のことで１点、先ほど大沢委員がやりましたが、確認をしたいところがありますので、ご準備をいただければと思います。その中で主要５課題も今動き出しておりまして、区長は区長会の実質的な代表として非常に精力的に動かれている。そういう体制もつくってやっているんだというふうに信じておりますが、そこら辺の点を再度確認をしたいと思います。","respondent":"市岡企画財政課長","answer":"財調の主要５課題の問題というのは、一見財政問題に見えますけれども、これは都区間の役割分担、言葉を代えて言えば、特別区が区民に対して一体どういう責任を果たしていくのか、こういう仕事の根幹に係わる問題ですので。","voiceIndex":321,"id":"exchange-139"},{"speaker":"石田委員","kind":"意見","question":"１０２ページからの東京都の負担金、民生費負担金から始まりまして、その中にいろいろなものがあります。最後の部分の委託金はいいですが、それの前まで、１１３ページまでいろいろずっと書いてあります。私も大都市事務の３０ページぐらい書いてあるものを全部見て、この予算書にチェックをしてみました。","respondent":"市岡企画財政課長","answer":"考え方がよく分かるように資料も配ったんですが、個々の事務について、所管で一つずつチェックをするというのはなかなか難しいものですから、私のほうから一括してお答えします。","voiceIndex":323,"id":"exchange-140"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほども言いましたように、各事業部長にお答えいただきたいと言ったのはどうしてかと言いますと、私も一生懸命これを見て、丸をつけていったわけですけれども、ほとんどないはず、少なかったんですが、だから答えられるかなと思っていました。そういう形の中でいきますと、事業部制を引いて、一つ一つの問題を今度東京都と折衝するのは各所管の方だろうと思います。","respondent":"市岡企画財政課長","answer":"大都市事務の検討会でも、東京都が１兆２,０００億円という数字を出してきましたが、これからは、特に今月中に個々の事務について一つずつ反論をしていくことになります。","voiceIndex":325,"id":"exchange-141"},{"speaker":"石田委員","kind":"質問・要望","question":"東京都にしてみたら、我々が負担金なり補助金を出しているんだぜという感覚があるんでしょうから、逆に、区のほうとしても、東京都が出してきたものに対して、結局市町村民税でやっているじゃないか、財調プラス補助金と書いてきているけれども、市町村民税でやっているだろう、こういう気持ちでぶつかっていくべきだと思うんですが、そこら辺の考え方を教えて下さい。","respondent":"市岡企画財政課長","answer":"ここに議論のとっかかりがありますので、そこらを切り口にして、委員の今のご意見も十分参考にして主張をしていきたいと考えています。","voiceIndex":327,"id":"exchange-142"},{"speaker":"石田委員","kind":"意見","question":"これはこれで秋から準備をされていて、まだ大都市事務が出てきていなかったから、これはこれでしようがないけれども、正誤表みたいなものをつくるとか、シールをつくるとか、これは市町村民税負担分ですよとか、そういうぐらいの気概を見せるべきだったんじゃないのかなと私は思うんですが、そこら辺の考え方を最後に聞きます。","respondent":"市岡企画財政課長","answer":"そういう極めて鋭いご意見があったということを、協議の中で都側に示していきたいと考えています。","voiceIndex":329,"id":"exchange-143"},{"speaker":"石田委員","kind":"質問","question":"その部分を今度どうやって捉えていこうか、これは行財政改革特別委員会の中でもちょっとお話が出ましたけれども、利用できない方を違うところとか、そういう連携をとっていかなくてはならない部分も出てくるかもしれないし、あとは、ある健康センターでお伺いをしたら、土・日の抽選などというのは６０倍を超えるというようなお話もあるし、そうすると。","respondent":"田中健康課長","answer":"ただ、現在の施設予約のシステムの中でとったりということは、抽選制度自体も機械でやらせていただいておりまして、どうしても例えば休みの日が高いのも事実ですし、それも午後、夜間が高いのも事実なので、これは倍率というのを出して、何か改善策をというのも。","voiceIndex":331,"id":"exchange-144"},{"speaker":"石田委員","kind":"質問・要望","question":"そこら辺のところは非常に難しい問題もあると思うんですが、天王洲の野球場、私の知っている中では、例えば健康センター、きゅりあんのホールとか、とろうとしても、なかなかとれない部分が多いと考えています。そういうところには何らかの方法というか、考え方を１回ぜひ考えていただきたい。これは要望しておきます。それと、建築確認の手数料の部分であります。先ほど法律上の技術審査のお話をされました。","respondent":"片田建築課長","answer":"先ほどのお話の中でも民間への導入が、昨年の時点では６割ぐらいの確認が出されている。今年度の見通しでも、まだ１カ月弱ありますけれども、若干４割を切りそうだというような認識を持ってあります。","voiceIndex":333,"id":"exchange-145"},{"speaker":"石田委員","kind":"質問・要望","question":"全く私も同じような考えであります。先ほど言ったように、難しい面もあるから、認定ぐらいからスタートするんだろうけれども、そういうことを含めて、建築確認の件数が増えていく方策を考えていただきたいなと思っていますので、そこら辺の考えをもう一回最後にお聞きします。","respondent":"片田建築課長","answer":"そういう中で、私どもも慎重に審査を努めているところですけれども、今後民間に対して、民間に相談を持っていくものでも、区にご相談に来て認定とか、そういう形に残るものとして認証を行うものについては、必要な検討を行って。","voiceIndex":335,"id":"exchange-146"},{"speaker":"沢田委員","kind":"質問・要望","question":"９５ページの国庫支出金の土木費補助金に関連しまして、再開発まちづくり問題で聞かせていただきたいと思います。来年度の予算案で、第３地区、西口中地区、南地区、二丁目第３地区、それからＪＲの広町地区の調査予算もつきました。全般的に言ってもわかりませんので、大崎の都市整備の地域指定をされた、この地域でどう見込んでいるのかをお答え願いたいと思います。","respondent":"上野都市開発課長","answer":"区としての第三次品川区長期基本計画や、あるいは市街地整備方針、マスタープランに沿った形でのまちづくりを推進していく立場から、そういう上位計画と整合のとれたものが地元から提案された場合に、区として推進していく。","voiceIndex":338,"id":"exchange-147"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、都市計画と言いながら、どれだけのビル需要がこの地域で必要だとか、どれだけのマンションの購入層がいるのかというのは全くないんですか。ヒートアイランドで４０度にもなった、さあ大変だ、これでは私は都市無計画だというふうに思わざるを得ません。大崎の東五反田地区と西口地区で、住宅で供給されたものと、これから供給するものが分かっている範囲でいいですから、お教えいただけますか。","respondent":"上野都市開発課長","answer":"それから東口につきましては、第３地区で今計画の事業が進んでございまして、約５８０戸です。西口につきましては、ただいま中地区で計画決定の手続きが進んでございまして、約１,１００戸の住宅がこれから供給される予定です。","voiceIndex":340,"id":"exchange-148"},{"speaker":"沢田委員","kind":"意見","question":"再開発の名によって、今言われただけでも約２,０００戸弱、凄まじい住宅供給が大崎西と東でされているわけです。ちょっと聞きたいんですが、もしこれが、すでに建ってしまったものは、オーバルコートなどはあれですけれども、今後建てるマンションが予想どおり売れなかったらどういうことになるのか、仕組みも含めてちょっと説明を願えますか。","respondent":"上野都市開発課長","answer":"今後これから供給されるものの考え方ですけれども、さまざまなお話が巷でされてありますけれども、肝心なところは、便利なところで立地条件の良いところで、質の良い住宅を供給していくです。","voiceIndex":342,"id":"exchange-149"},{"speaker":"沢田委員","kind":"意見","question":"もしこれで売れ残って、例えば中地区などで１,１００戸の住宅をつくって、これが売れ残ってしまったら、あの開発は一体どう帳尻を合わせていくんだ、このことが問われているんじゃないかなというふうに思うんですが、もう一度問題整理をする意味で言いますけれども、今マンションの供給過剰がいろいろなところで言われて、こうしたデータが毎日のように出ていることに対して、品川区はどう思うのか。","respondent":"上野都市開発課長","answer":"その中で地域間競争に打ち勝って、なおかつ地元の方々からも支持されるような良好な住宅を供給していきたい、そういうまちづくりを推進していきたいと考えています。","voiceIndex":344,"id":"exchange-150"},{"speaker":"沢田委員","kind":"質問・要望","question":"とても続かない。これはみんな借金をしてゼネコンを建てているわけですから、これが売れなかったら、倒産ですよ。特に私が心配なのは、住宅街、８８の権利者がいて、借地、借家人が１２０名いるといわれる中地区ですよ。高岡市の駅前に再開発ビルがあって、文教委員会ですから、図書館の勉強に行ったんです。改めてそういう危険がないのかどうなのか。再開発の仕組みのところなので、よろしくお願いします。","respondent":"上野都市開発課長","answer":"そういう意味におきましては、将来でき上がった後に保留床は全部参加組合員が引き取ることになってありますから、そういう意味において担保されている事業は成立するということになってありますので、今のところ事業を失敗するというような想定は全くしてございません。","voiceIndex":346,"id":"exchange-151"},{"speaker":"沢田委員","kind":"質問","question":"都市計画審議会でも言ったんですけれども、私どもで住友不動産の重役の方に連絡をとりまして、「あそこは３年前都市計画決定を品川区でやって、東京都に持ち上げて決めたけれども、あなた方は見通しをどう思っているんですか」と言ったら、そのときの重役は、「我々はそのことを十分承知した上で、リスクを負わないようにしていますから大丈夫です」という話だった。報じられているんですよ。","respondent":"岩野まちづくり事業部次長","answer":"ただ、私ども今見てみますと、これは大崎ばかりではございませんが、東京都全体のご心配されたマンションの空室率については５％台ということで、ほぼ理想的な状況になってありますので、このマンションの問題につきましても、いろいろご懸念の点はあると思いますが。","voiceIndex":348,"id":"exchange-152"},{"speaker":"沢田委員","kind":"意見","question":"理事者の方は何年か経つと定年でいなくなってしまいますけれども、そのマンションを買った人は、低廉で買えるというかもしれないけれども、そのときの値段で買ったときのローンだけが残るんです。区の開発によって区民に大損害を与えることになる。そのことだけ言って、終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":350,"id":"exchange-153"},{"speaker":"土井委員","kind":"質問・要望","question":"私のほうからは、先ほど話のありました５８ページの財調に関すること、それからまた先ほど話のありました建設確認手数料に係わること、１３１ページにあります、競馬組合の配分金に係わることでお伺いをいたします。調整税等でなくて、それは特別区税と、代行徴収分にすぎないんですよ。もう一つは、平成１８年度ということでの一つのハードルといいますか、山があるわけです。","respondent":"市岡企画財政課長、濱野助役","answer":"それは例外的、限定的でなければいけない。これが基本的な都区の役割分担、なかんずく東京都がなぜ例外として、本来区の仕事をしなければいけないかということの基本的な論理ですので、ここはしっかり主張していきたいと思います。後段のご質問です。これからの戦術、あるいは戦略だろうというふうに思いますが、品川区長以下、区長会としては、東京都が時間切れをねらっているのではないかということは認識しています。","voiceIndex":352,"id":"exchange-154"},{"speaker":"土井委員","kind":"質問・要望","question":"建築確認手数料の件です。そうすると、先ほどのまちづくりの良好な住宅等が本当にできたのかというところをどう担保していくのかというのでは、民間を信用しましょう、民間の活力をやりましょう、これは結構なんですけれども、その部分を指導も含めてどうしていかれるのかということをお伺いしたいと思います。","respondent":"片田建築課長","answer":"例えば今回新たな防火制度というような制度を立ち上げた、区としても指定したところがありますけれども、そういう制度についても、きちっと民間のほうに、こういう制度をつくったので、それにきちっと守っていただきたいということで、日ごろから働きかけてありますので。","voiceIndex":355,"id":"exchange-155"},{"speaker":"土井委員","kind":"質問","question":"そのときに、どう担保するかということになるわけですね。ですから、年に何回かその種のものを皆さんのほうで、民間でやったところであっても、完了検査的なものを、強制執行というわけにいかないのかもしれないけれども、何かやるような要綱も含めてつくっていかなければいけないんじゃないかと思うんですけれども、その辺はいかがなものでしょうか。","respondent":"片田建築課長","answer":"実は民間を認める場合についても、国土交通省の認可を受けなければいけないといったような対応になっております。","voiceIndex":357,"id":"exchange-156"},{"speaker":"土井委員","kind":"質問","question":"１３１ページの競馬組合の関係についてお伺いをいたします。午前中もありましたが、ここに分配金が書かれています。そういうようなものも含めての企画とかも含めて、きちんとどう参入をしていくのか、意見が言えるのか、もっとそういう専門的なことも含めたものをどのようにしていくのかという面では、品川区等の発言力等々はどうなっているんでしょうかということをお聞かせ下さい。","respondent":"宮地総務課長","answer":"ただ、これがいつまでも続くのかということを考えていきますと、生活も成り立たなければ解散するしかなくなってしまうわけですから、それは常にこの中の専門家も含めた検討会の中で検討をしながら進めていくということで、説明は受けました。","voiceIndex":359,"id":"exchange-157"},{"speaker":"土井委員","kind":"質問","question":"まさしく雇用関係という意味では、契約関係という意味では、非常に難しいことは事実です。それと、馬主、調教師、騎手、厩務員、８０、１０、５、５だという話を伺っておりますけれども、これが旧態依然のまま取り分として固まってしまっていると、下がれば下がる。窓口の皆さんだって減ってしまうわけですから、パート収入ですからね。そうすると、これも品川区民が多いですからね。","respondent":"宮地総務課長","answer":"総務省などからも開催権の付与を特別区は受けていますので、こちらからもさまざまな指導監督がありますので、そういったところの専門的な指導も受けられると聞いておりますので、そこら辺も今後もよく話を聞きながら、言うべきことは言っていきたいというふうに考えております。","voiceIndex":361,"id":"exchange-158"},{"speaker":"藤田委員","kind":"質問・要望","question":"私からは、１１８ページの職員住宅、その中で先ほどご答弁がありました、旗の台女子寮に対して非常に苦戦をしているというお話がありましたけれども、苦戦の中身を教えていただきたいと思います。これはどういうわけなのか教えて下さい。それから、７２ページの道路占有料につきましては、区道上に電柱を、区が必要があって移設する場合にはだれが負担をしてこの移設をするのか、これを教えて下さい。","respondent":"桑村人事課長、松代道路公園課長、岩田管理工事課長","answer":"ただ、全般的な意味では、老朽化が進んでいますので、寮のあり方そのものについて若干検討をしている部分もありますので、入居の状態と。私どもも各公園等でいろいろと花のボランティアを募集して、管理等をしていますけれども。ただ、民間の建物を改築して、入口なり、駐車場がちょうど電柱とぶつかってしまうので、電柱を動かす場合は有料となっております。","voiceIndex":364,"id":"exchange-159"},{"speaker":"藤田委員","kind":"質問・要望","question":"そういう面で、今ご答弁がありましたように、職員が住むのであれば、老朽していますから、ちゃんとした住みやすい住環境にすべきだと。今は中途半端なやり方ではないかなというふうに思いますので、ぜひ検討をしていただきたいということをお願いしておきます。それから、しながわ中央公園のほうです。これを何らかの手だてをしていかなければいけないと私は思うんですけれども、いかがでしょうか。","respondent":"岩田管理工事課長","answer":"私道のケースの場合は、東京電力にしても、ＮＴＴ柱にしても、２種類のタイプがございまして、私有地ですので、私有地の持ち主の方が東京電力なりに無償で土地を提供している場合、これはほとんどのケースがこういうケースなんですけれども。","voiceIndex":368,"id":"exchange-160"},{"speaker":"藤田委員","kind":"質問・要望","question":"今のご答弁でよく分かります。ですから、その辺は粘り強く、２項道路のために皆さんが貴重な土地をわざわざ下がっているわけですから、そうしたことによって、いざというときに入ってこれないというケースがあるわけなので、これは区としても関係の東京電力、ＮＴＴ等にも働きかけていただいて、ぜひともそういうことを少しでもなくしていきたい。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":370,"id":"exchange-161"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、５１ページの特別区民税と、６５ページの区民斎場なぎさ会館の件につきまして、お伺いをします。にもかかわらず、それが数字の上に表れていないのではないかなというふうに思っているので、そこのところの判断をお知らせいただきたい。そこのところでこの利用率の減につきまして、今後どういうふうな形を考えていかれるのかなというのをお伺いさせていただきたいと思います。","respondent":"太田税務課長、長田区民課長","answer":"平成１７年度の当初予算の区民税の歳入を算定するにあたりましては、退職所得は現年の課税をしてまいりますので、それ以外の税につきましては前年の所得をもとにして算定をしていくです。それから平成１７年度の予算の中ではホールの改修ですとか、廊下に手すりをつける予定です。こういったことで少しでも使いやすい施設というようなことを目指してまいりたいと考えています。","voiceIndex":372,"id":"exchange-162"},{"speaker":"原委員","kind":"質問・要望","question":"ただ、平成１７年度から平成１８年度にかけて、あるいは住民税の主な改正がいろいろされていると思うので、そういったところも今回の中にどう影響されているのか、先ほどちょっと触れたようですけれども、もう少し詳しく教えていただければと思います。ここのところはどう考えていらっしゃるのか。","respondent":"太田税務課長、長田区民課長","answer":"平成１８年度以降におきましては、公的年金の控除の上乗せ部分の廃止、老年者控除の廃止という部分を見込んでいるところです。なぎさ会館ですけれども、平成４年に開設ですから、現在１３年目に入ります。そういった意味ではそろそろ大規模改修が必要になってくるだろうというふうに思ってあります。","voiceIndex":375,"id":"exchange-163"},{"speaker":"原委員","kind":"質問・要望","question":"特別区民税のほうですけれども、今お話のとおり、経済的な状況、そしてまた、平成１７年度、平成１８年度、制度的なものが含まれてきているわけですが、平成１７年度は今回予算を組んでいますが、その後、平成１８年度の制度改正等も含めると、どういう形に今後の見通しを立てていらっしゃるのか、そこだけちょっと聞かせていただきたいと思います。","respondent":"太田税務課長","answer":"平成１７年度、平成１８年度以降ですけれども、いろいろな改正がありますが、総体としては税収としては伸びていく方向ということで考えてあります。","voiceIndex":378,"id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=840#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":121378,"voices":380}},{"id":"h17-20050310-3","meetingId":"h17-c-budget","date":"2005年3月10日","dateIso":"2005-03-10","committee":"予算特別委員会","time":"午前１０時０３分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を177件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私は１６２ページ、防災対策費についてお伺いしたいと思います。「住民、専門家、行政職員などが集まって相互に協働しながら自主性を発揮して自由に意見交換を行い、成果物をつくり上げていく住民参加、協働の手法を指す」という、内容が書かれておりますけれども、本区の実態に即した、わかりやすいワークショップという、防災に関するワークショップというのをご説明をお願いしたいと思います。","respondent":"久保田防災課長","answer":"防災に関するワークショップですけれども、現在防災課で取り組んでおりますワークショップの中には、避難誘導ワークショップというふうに言っておりますけれども、そういうものがあります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"今、防災課長の説明をいただきましたけれども、避難誘導に関するワークショップというのを行ってきたわけですけれども、今までに防災課長ご自身がお感じになられましたワークショップという手法に対する利点というのをお答えください。","respondent":"久保田防災課長","answer":"実際、これまで２６町会で計３０回のワークショップを行っておりますけれども、一番気づいたことは、普段私ども日常的に通いなれた道筋、あるいはまちの状況というのを、もう１回防災の視点で見直すというような意識を持って見直すことによって。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"しかしながら、とりわけ夜において震災が起きた場合、ワークショップがうまく機能するのかどうかというのは、私疑問に感じられますが、その点、どのようにお考えでしょうか。","respondent":"久保田防災課長","answer":"今ご指摘いただいた昼、夜との関係というのは、これからワークショップを進める上で、ものすごく大切なことだと私も認識しております。昨年、実は夜間のワークショップを実施し始めた町会が出てまいりました。","voiceIndex":10,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと、興味が沸きましたのでお伺いしたいんですが、先駆的に夜のワークショップの訓練をされている町会、おわかりにならならければ特定されなくても結構なんですが、大体どの地域で夜のワークショップを行われているのか、それだて蛇足なんですがお伺いしたいと思います。","respondent":"久保田防災課長","answer":"昨年、夜間のワークショップをやっていただいたのは、大井第３地区の出石町会です。","voiceIndex":12,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"今、大井地区ということで伺いましたが、荏原地区におきましても、大崎地区におきましても密集している部分があります。夜中に皆さんが集まっていただくということは、非常に不可能な部分もありますが、そういった場合、学校の体育館など広いところを暗がりにして訓練するのも一法かと思うんですが、その点にいてご意見をちょうだいしたいと思います。","respondent":"久保田防災課長","answer":"これは学校に着いたときに、さらに夜間の体制として、私どもは今発電機等を学校にも整備していきたいというふうに考えていますので、そういったときの臨時の明かりの中での訓練というのも、今後検討していきたいと、こんなふうには考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"それに付随しまして、私たち去年１２月に命を受けて海外調査に行ってまいりました。スイスのジュネーヴに行ってまいりました。シビルプロテクションという防災組織に行ってまいりました。そこには常設してあります防災訓練所があります。その点、お考えを伺いたいのが１点。それが不可能な場合、消防等々との連携を組みながら、場所をお借りして訓練ができないのか、２点お伺いしたいと思います。","respondent":"久保田防災課長","answer":"今、お話しに出たいろんな訓練も、やはりいろいろ考えられると思いますので、そういう施設を有効に使いまして、いろんな工夫をしながら想定訓練というのは、これからも可能だと思いますので、消防署の皆さんの協力を得ながら、今後も充実していきたいというふうに考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"先だって、国のほうでも首都圏に地震が起きた場合のシミュレーションが示されました。私たちは、やはり都民、区民の一員として、非常に危機感を持っているところでありますので、そこの部分、よろしく加味されながら、今後のワークショップに生かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"１５９ページのホームページ関連、それから１６２ページの防災対策費、１５５ページの生活安全推進事業、１５１ページの庁舎等維持管理費、時間がなくなってしまうかもしれませんが、できる限り手早くやっていきたいと思います。ホームページです。先ほどのご説明の中で、見やすく使いやすくというご説明がありましたけれども、この倍増の中身を教えていただきたいと思います。","respondent":"中川原広報広聴課長","answer":"１７年度のホームページの予算の増の部分ですが、今年度、ホームページの診断をしております。ＪＩＳ対応に向けまして、今年度診断を行いまして、その修正部分について来年度７００万円の予算でＪＩＳ対応に向けていきたいです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"アクセシビリティーは日本語で利便性と訳すのだと思いますが、そこのチェックをしていくと。現状は、ある程度の弱者対策、利便性を持たせたホームページであると。その基礎から、さらに見直しをかけていくということで承知してよろしいでしょうか。","respondent":"中川原広報広聴課長","answer":"今までもそういうことでやってまいりましたが、やはりわかりやすさ、それから情報の正確さというようなところで、今に合わせまして、途中でいろんなものが加わっていまして、ホームページが始まってから年数を経ていますので。","voiceIndex":24,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"私は、昨年の予算特別委員会でこのことを質問をさせていただきました。当時の課長のご答弁では、確かそのときは厚生労働省のホームページが文字拡大、音声読み上げということがちょうど始まった直後でございまして、これについてご見解を求めたところ、積極的に取り上げていくときには取り上げていくと、こういうようなご答弁がございました。","respondent":"中川原広報広聴課長","answer":"委員ご指摘のとおり、平成１６年６月２０日に経済産業省でＪＩＳ規格対応につきまして、設計指針というのが出ておりますので、それに基づいてもう一度、品川区のホームページの構成、デザイン等にも踏み込んだ再構築のための診断を今しております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、今の予算ではできないので、新年度の倍増の６,０００万円、７,０００万円の中でバリアフリーもしっかり踏み込んでやっていくということでよろしいでしょうか。","respondent":"中川原広報広聴課長","answer":"その後、事業部のホームページも持ってありますので、それは今事業部ごとにいろいろな状況が出ておりますので、その課題の整理をいたしまして、平成１８年度予算に事業部のＪＩＳ対応につきましては予算化をするという、１年ずれますが、そういったスケジュールです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"若林委員","kind":"確認","question":"そうすると平成１７年度は今のまま行くということだと理解をいたしますが、確認させてください。","respondent":"中川原広報広聴課長","answer":"それをリンクして皆様に見ていただいているんですが、まず本体の品川区のホームページを平成１７年度の診断結果に基づいてリニューアルを行いまして、それに基づいて事業部を翌年度にＪＩＳ対応に向けて直していくです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"しっかりと積極的に取り上げて、見直していただきたい。それから、やさしいまちガイドマップでいいますと、該当詳細マップ画面に入りますと、上にいろんなボタンがあるんですが、ボタンの文字が潰れたままになっているとか、バリアフリー以前の問題がまだあって、その辺の対応はリニューアルされたと同時にそういうふうになってしまったと思うんですが、この取り組み方を確認させてください。","respondent":"中川原広報広聴課長","answer":"ただ、私ども今回できたのはトップページのデザイン変更だけで、今ご指摘の見やすさとか地図が旧態依然のものになっているかというのは、できる限りはやっているんですが、どうしても漏れがあります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ見直しの中では、震災時の時間経過による活動想定というところで、一応時系列に並んでいるんですが、これをぱっと見て、だれがどういうふうに動いて、どのような助けがあるのかというのがわかりにくいというか、この辺の再度の検証と、そういった意味での見直しの仕方を教えていただきたいと思います。","respondent":"久保田防災課長","answer":"防災会議は区をはじめとして消防署、警察署の公共機関、鉄道等の公共指定機関という、それぞれの防災関係機関が集まって検討することになっていますが、区のほうで、まずはその辺は主体的にやるということになるかと思います。","voiceIndex":36,"id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"先ほど、ホームステイの受け入れというようなお話もありましたが、重点事業としてどういうふうにお考えになっているかお答えください。成人式経費、毎年伺わせていただいておりますが、大変落ち着いたいい成人式が行われているというふうに認識しております。これも平和使節派遣費と資料コーナー経費ということがありますけれども、この中身と今後の区の平和事業を進めていくお考えを改めて伺います。","respondent":"宮地総務課長","answer":"今後の非核平和都市品川宣言事業につきましては、本年２０周年を迎えることですので、周年事業をいたしまして、その後、やはり平和に関する普及を続けていくということで、私どもの課だけではなくて。","voiceIndex":39,"id":"exchange-015"},{"speaker":"川西委員","kind":"質問・要望","question":"最後の非核平和都市品川宣言事業から、要望を一つ申し上げます。成人式経費のことですけれども、これも要望です。品川女子学院の鼓笛隊というんですか、ちょっと呼び名が違うんでしょうか舞台でやるんですから。それから、質問の日本語教室、生け花教室、国際友好協会からの新聞で見ていますが、この人たちの費用弁償というのはどうなっているのか伺います。","respondent":"宮地総務課長","answer":"日本語教室を実際に実施していますのは、国際友好協会のほうで実施しておりますので、その中で評議員会、理事会の中でさまざま議論されているところですので、私のほうでは簡単にお話しをしますが、日本語教室も受講料７,０００円をお取りしています。","voiceIndex":41,"id":"exchange-016"},{"speaker":"川西委員","kind":"質問・要望","question":"二つ残っているんですけれども、あと一つだけ。１４９ページの代替職員雇用経費のことですけれども、区のほうは、この代替職員を派遣会社委託の方向にどんどん進めるという話を若干聞いたことがあります。ですから、効率的に経費の節約なのか、運営委託をしてしまった、あるいは派遣会社から人を採用したほうが有能な人材が求められるのか、その辺の区の考えを聞かせてください。","respondent":"桑村人事課長","answer":"ただ、現実には例えば最初から欠員が出るとか、それから病気で長い間の休みの方が出るというような事態も出てきておりますので、いわゆる人材派遣会社ですと、そういう意味では欠員の間を同じ職員で対応できるということもありますので、平成１７年度からこの辺の基準について。","voiceIndex":43,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地方公共団体に義務づけられた特定事業主行動計画の素案について、一般質問で区長より一般事業主の行動計画の模範になるべきであると、こういった認識を伺いました。期待をしていますので、よろしくお願いしたいと思います。具体的に４点目標値が示されていますけれども、今の品川区の現状と目標値と比較してお示しいただきたいと思います。","respondent":"桑村人事課長","answer":"平成１５年に１人、平成１２年に１人あったと思うんですけれども、そういう意味では２年に１回ぐらいですので、パーセントを出すのはなかなか難しいんですけれども、無理やり出せば１％か２％という数字なんだろうと思いますけれども、それを５％にしたいと考えています。","voiceIndex":46,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"出産支援休暇は２日間ですよね。出産後の母親の不安定な時期を支えるには、１００％２日ぐらいはみんなが取れる、またもっと続けて母親を支えられるようにしてほしいなと思っています。育児休業の取得なんですが、今、品川区の職員の体系からすると、２０代、３０代、４０代はどのぐらいの割合がいるんでしょうか。","respondent":"桑村人事課長","answer":"その意味では、男性の育児休業の取得というのは、これまでなかなか少なかったわけですけれども、工夫をして男性の方についても、必要があれば取っていただきたいという環境づくりに努めてまいりたいというふうに思います。","voiceIndex":48,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ヨーロッパ並みに育児も、また家のこともこなす男性が社会的に評価をされる時代を求めているわけですけれども、品川区の管理職の意識の現状はどのようになっているのか、またこの辺の努力目標もお聞かせいただきたいと思います。そういった面では、労働時間の短縮をしていかなければ、目標値を上げても実現をしていかないと思うんですが、この点はいかがでしょうか。","respondent":"桑村人事課長","answer":"全体の取得率というのは、平均で１５日か１６日というのが普通の線です。その意味では、２０日間の休暇の中の１５日から１６日取れるという環境自体は、それはそれなりに評価されていいんだろうというふうに思っています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先日、新聞に日本は太平洋地域のアジアの国々における女性の社会進出の割合が１３カ国中１１位、下から３番目です。特に学歴、管理職の割合、平均収入、大きな男女格差が見られるということで、やはりこの点がネックだと思うんですが、そういった面では自治体が特にこういうところでリードをしていくという、先駆的な役割があると思うので、その辺を本当に力を入れていただきたいなと思います。","respondent":"桑村人事課長","answer":"その点では、委員のおっしゃるような意味でのことは、十分進めているというふうに思ってあります。","voiceIndex":52,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日頃から消防団の皆さん、火災はもとより震災のときなど、地域に密着をした活動が行われていて、より一層の充実が求められていくと思うんですが、３消防団のアンケート調査が行われているんですけれども、品川区の消防団の運営委員会でもこの報告がされたんですが、消防団より求められている改善点をどう認識されているのか、また区でどのような支援ができるのか教えてください。","respondent":"久保田防災課長","answer":"この中で、今後検討していく課題というのがいろいろ挙げられたとは思うんですけれども、区でも消防団の活動本体については、これは東京都のほうでやる部分ですけれども、区のほうでも区としてできる支援をしていこうということで、これまでも本団、分団。","voiceIndex":54,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"施設設備に関してなんですけれども、消防団の活動の拠点を充実させてほしいというところで、私は荏原消防団が地域なんですけれども、荏原第一分団のところは地域活動センターというのが立派にありまして、会議室もあるし、完備をしているわけですけれども、３消防団、１７分団の中で３６も格納庫があるんですが、そこでトイレとか水道がないところのほうが多いと伺っているので。","respondent":"久保田防災課長","answer":"そういう中で、今、確かに消防団の人員は欠員になっているところもありますけれども、これを埋めていく方法として、区とても広報紙を活用して募集の案内を載せたり、あるいは消防署でやっているいろいろなＰＲ活動について。","voiceIndex":56,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"意見","question":"私も荏原の１５ある格納庫のうち九つまでは調査をさせていただいたんですけれども、組み立ての簡易的なバラックと言ったら悪いですね、あとプレハブ的なものとか、コンクリートブロックを重ねて、窓もなくて、４.７１m2の結構小さくて機材がやっとというところがあるんですけれども、１日の仕事の後、夜練習をしたり、せめてトイレとか水道をつけてほしいという声が届いています。","respondent":"久保田防災課長","answer":"この部分については、土地の提供等はこれまでもやってきましたので、そこの部分については継続していきますけれども、一つはやはり東京都のほうが、今後そういうことの充実についてどう考えていくかということが主になりますので、そういう声が出ていたということについては。","voiceIndex":58,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"都が主体というところなので、ぜひ区のほうからも意見を上げて、協力して進めていただきたいと思います。私はミニポンプ隊を十数年やっているんですが、長靴とヘルメットと銀色の防火服はあるわけですけれども、ユニホームが町会の持ち出しになっていて、私もずっと同じ服を着ているわけですので、ぜひその辺の助成を考えていただきたいと思います。","respondent":"久保田防災課長","answer":"これは地域の独自の活動として、それはそれで結構なことだと思います。区のほうも、そのほかに毎年ミニポンプ隊の補助金としては２万円差し上げてありますので、そういう中での活用で町会で工夫していただければというふうに考えております。","voiceIndex":60,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どこもユニホームをそろえてきていますので、ぜひよろしくお願いしたいと思います。最後、成人式なんですけれども、今年の成人式に参加された青年から、ぜひ区長の話を伺いたいという意向で参加したところ、大変混雑していて中に入れず聞けなかったというところでは、案内をしたからには、やはりその辺の予測があるだろうし、もっと丁寧に対応していただきたい。","respondent":"宮地総務課長","answer":"大変、参加率が高い成人式でございまして、イベントホールで区長の話が聞けるようにセッティングをしてありますので、その話がその方に届いたかどうか、ここでは何とも言えないんですけれども、案内はきちんとし。","voiceIndex":62,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は１項総務管理費の中の１目一般管理費、１４５ページの職員給与費、それから１５１ページの庁舎等維持管理費、１６２ページになりますけれども６目企画調整費、時間があれば４項選挙費で質問したいところがあります。各事業部ごとの予算編成という中で、またがったときの調整というのはどのようにされているかということを、まずお聞きしたいと思います。","respondent":"市岡企画財政課長","answer":"それ以外でも要求と実際の予算編成の中では、どのように編成したら一番その政策目的が達せられるかという観点で、主要に企画部のほうで調整をしまして、最終的な査定の中で決めていくという形を取ってあります。","voiceIndex":65,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば、二つの事業部で一生懸命やろうと思って考えていく。目的は一つ、区民のためということだと思うんですけれども、その中で予算編成ですとか、執行の部分はいいと思うんですけれども、成果が上がったとき、やはり事業部としては自分たちがやったんだよという思いがあるじゃないですか。その辺の調整というのは、うまく取れているのかなということをお聞きしたいんです。","respondent":"市岡企画財政課長","answer":"事業部制の中で、今のようなご懸念もあろうかと思いますが、例えば事務事業評価というふうな評価手法の中でも、それぞれの成果と達成度というものを公平に評価をするようになってありますので、予算編成上の必要からたまたま該当の科目が自分のところになかったからといって。","voiceIndex":67,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もちろん、そうあってほしいですけれども、事業部制というよさは逆に生かしてもらいたいんですけれども、それは各課の間でも出てくると思うんです。今、お答えを聞いていて思ったのは、区長表彰というのか区の中にもありますね。","respondent":"桑村人事課長","answer":"そういう意味で、表彰に値する場合は、両方の部署を表彰するというような形で、同じ項目でやっているものです。","voiceIndex":69,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２点目に、庁舎等維持管理費の関係なんですが、直接庁舎ではなくて、来年の９月までに見直さなければいけないという指定管理者制度の導入を、どういうふうに考えているかという点をお聞きしたいと思います。現在、区としては管理委託を行っている施設を直営にするか指定管理者にするという点で、まずどのぐらいの数が対象になってくるか教えていただきたいんです。","respondent":"榎本行財政改革担当課長","answer":"もしくは直営にしていくという、どちらかの選択肢という形になると思います。それの数につきましては、会館施設系、住宅施設系、スポーツ施設系、福祉施設系、それぞれありますけれども、細かいところもありますので、全体でざっと２０ぐらいの部分になると思います。","voiceIndex":71,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"既に、二つの施設が指定管理者を受けているはずです。平成１５年の第４回定例会で、二つの施設をまず条例改正して、平成１６年第１回定例会で指定したという状況は承知しているんですが、これからどのような形で進めていくのか、時間的なものとか。９月という制限だと、半年間は今までの委託で、そこから変わってくるのかどうか、その辺がある程度決まっていれば教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"法律上の期限は９月という、経過措置３年というところになっていますけれども、やはりいろいろ区の中で委託契約をしていくとか、予算で組んでいく場合には年度単位という形になりますので、今現在の想定スケジュールでいきますと。","voiceIndex":73,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、２０施設がこれから対象になっていく中で、規模の大きいものも小さいものも出てくると思うんです。企業なりＮＰＯなりが入ってきますけれども、やりやすい部分があると思うんですが、逆に小さい施設に応募がなかったようなケースがあった場合には、やはり指定管理者制度で条例を改正した後に、また直営に戻すというような形が、そこも条例改正になってしまうんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"委託できる場合には、大体条例でできる規定という形になっておりますので、そういう手法が取れるという形であれば、そこの団体に委託していくという形で、今現在の条例でもほとんどが管理運営委託できるという情報に基づいてやっておりますので、最悪というか。","voiceIndex":75,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"指定管理者制度になることによってサービスの低下のないように、今までどおりやってもらいたいと思う部分があります。短期間ごとに見直しをするようなケースですとか、先ほど福祉系というお話がありましたけれども、福祉系施設ですと、ある程度長期的に指定しなければいけない部分があると思うんですが、その辺はどのように考えたらいいんですか。","respondent":"榎本行財政改革担当課長","answer":"心身障害者福祉会館とぷりすくーる西五反田で導入を図っておりますけれども、その場合にも各所管ごとに個別に検討しまして、そういう事業が本当に募集をかけたほうがいいのか、それともかけないでやったほうがいいのか。","voiceIndex":77,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、行政処分で権限をある程度与えるということ、それを前提にした場合には、やはり企業の内容を区がチェックすると同時に、議会として例えばその会社の事業内容とか、決算内容みたいなものも、議会のほうにも出てくるような形になるわけですか。その辺に踏み込んじゃうと、まだ決まっていないのかどうか、それとももう既にある程度方向が出ているのか、その辺も教えてください。","respondent":"榎本行財政改革担当課長","answer":"実際上、今現在、例えば業務委託している企業についても、同じような形で業務委託部分についてのチェックはできますけれども、業務委託ではない会社固有の経理状況の部分がどこまで公開されるかとか、どこまでチェックできるかというところは、十分事前の事業計画なり。","voiceIndex":79,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"業務委託内容だけのチェックというと、その企業全体をつかまないと不安な部分はかなりあるんじゃないかなと思います。その部分だけのものが、ほかへ動いてしまう。その辺で、ないような形をきちんとしていただきたい。それとサービスの低下を招かないような、そんな中での対応をお願いしたいと思います。次の質問に入る時間がないので、これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"私は、職員の福利厚生と、時間がありましたら人権啓発についてお伺いします。","respondent":"桑村人事課長","answer":"ちょっと漏れているところがあったら、後でご指摘いただきたいと思います。一つは、１４５ページの職員共済組合業務経理等負担金ですけれども、業務経理という言葉で表しているとおり、共済組合の中で職員の人件費ですとか事務費の分を東京都と特別区が負担しております。","voiceIndex":83,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうしますと、最近マスコミを賑わせました、もちろん品川区ではありませんが、職員のスーツの支給とか、生命保険等の本人分の保険料を自治体が負担したというようなことは、品川区においてはないかということを確認させていただきたいと思います。","respondent":"桑村人事課長","answer":"これは、全くございません。それから、もう一つは、公費で今保険の話も出ていましたけれども、公費で退職金あるいは年金にかわるようなものを負担していた。あるいは、生命保険の負担をしていたです。これも品川区においてはございません。","voiceIndex":85,"id":"exchange-037"},{"speaker":"藤原委員","kind":"確認","question":"確認が取れてよかったです。安心しました。それと、職員互助会とか特別区職員互助組合についてですが、職員の負担と雇用主である区の負担について、割合はどのぐらいになっているんでしょうか。","respondent":"桑村人事課長","answer":"職員互助会ですけれども、これは職員の会費と区の負担は１対１です。それから、特別区職員互助組合ですけれども、これについては現在１対２です。平成１４年度までは１対３という割合だったんですが、見直しが進みまして１対２という数字です。","voiceIndex":87,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"今、質問をさせていただいていて、職員に対しての福利厚生というのは手厚いんだなというふうに感じます。今、人事課長のご答弁の中に、今見直されていますというようなご答弁が何回かあったんですが、今後どのような形で福利厚生というのは考えて見直していくのか、ご答弁願います。","respondent":"桑村人事課長","answer":"そういう意味では、無駄がある部分はあるんじゃないかというような考え方を基本的に持っておりまして、会費の見直しが平成１５年から一度進んでいるわけですが、さらに事業ももっと見直しをして、もう少しスリムにできないか。","voiceIndex":89,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"区民が納得するような福利厚生に努めていただきたいと思います。最後に１点、お伺いします。人権啓発費ですが、１４９ページに出ております。人権啓発というのはいろいろな形で品川区はされていると思うんですが、予算をつけてこの施策をして投資対効果といいますか、効果というのはどこで区として感じるのでしょうか、１点だけでいいですかご答弁をお願いします。","respondent":"武内人権啓発課長","answer":"そういう中で、一つには、品川区では人権尊重都市品川宣言を行っているんですけれども、そういうものに対して区民がその調査によってどの程度認識度が高まったか、そのような部分で効果というのを考えております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"１４９ページの危機管理室経費、１５３ページの子供１１０番の家オリエンテーリング等経費、１５５ページのわんぱくパトロール事業、時間がありましたら１５１ページのメールカー運行委託等についてお伺いしたいと思います。１月から危機管理室が設置されたというふうに伺っていますけれども、改めまして設置目的とどのような体制になっているのか、また主な活動というか事業の内容を教えてください。","respondent":"宮地総務課長","answer":"実際に立ち上がっている組織がない場合は、危機管理本部が立ち上がります。区長を本部長としまして、副本部長、そして総務部長の危機管理監、そして事務局を所管する総務課が危機管理室となり、現総務係職員が対応をしていくといった組織です。","voiceIndex":94,"id":"exchange-041"},{"speaker":"武内委員","kind":"質問","question":"来年度は２５万１,０００円の予算がついておりますが、これの主な内訳というか、内容について教えてください。","respondent":"宮地総務課長","answer":"２５万１,０００円の内訳ですが、ほとんど研修費用に費やされるものです。普及啓発をしていく部分の研修、そして書籍、事務連絡等の費用です。","voiceIndex":96,"id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"研修ということで、簡単で結構なので、どんな感じの研修なのかというのと、先ほどありました予測できないいろんな事件とかというお話がありましたけれども、主に災害に対してというふうに認識しているんですけれども、それ以外の例えば犯罪というか、近年ある子どもを巻き込んだような事件、こういったものに対しても危機管理室が何か対応されていくのか、その辺もお伺いいたします。","respondent":"宮地総務課長","answer":"ただ、ある中でも、まだ全体的な所管が係わっている場合とか、総合調整等が必要なものもありますので、そういった場合は、危機管理室のほうで関係部長を含めた所管の危機管理対策本部を設置しまして、そこでの調整を図るといったような関係を持っております。","voiceIndex":98,"id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"続きまして、子供１１０番の家オリエンテーリングということで、子供１１０番の家が今ありますけれども、夏休み等を利用して１１０番の家の方と交流を図りながらマップもつくっていくというふうに伺っていますけれども、マップに関しては全部の小学校でつくっていくのでしょうか。","respondent":"田村地域活動課長","answer":"子供１１０番の家オリエンテーリングの内容ですが、今現在考えていますのは、子供１１０番のシールは約１,０００世帯に現在張っているわけですが、平成 １１年に配布しまして、その後のフォローがないまま来たということで。","voiceIndex":100,"id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"５地区ということなので、各地区の小学校１校ずつをモデル的に通学路をやられる予定なんでしょうか。","respondent":"田村地域活動課長","answer":"今のところ、そのように考えております。","voiceIndex":102,"id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"確かに時間的なものとか、初めて立ち上げる事業なので、どうしても数としてはそういう形にならざるを得ないと思うんですけれども、今学区外から通って来られるような通学エリアもありますけれども、そうした場合はどの辺まで対応できるのかお聞きしたいと思います。","respondent":"田村地域活動課長","answer":"今回５地区でやって、やはり学区域の自由化だとか、あるいは別の区域内に通っている学校の問題がいろいろ出てくると思います。それはモデル実施する中で、今後いろいろと検討しなければならない課題を整理したいと、そのように考えております。","voiceIndex":104,"id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"ぜひ、なるべく早く、全小学校でマップづくりができるような体制整備をよろしくお願いしたいと思います。続きまして、わんぱくパトロールについてお伺いいたしたいと思います。主な事業の内容について、お知らせください。","respondent":"杉浦生活安全担当課長","answer":"５月の広報しながわで、２００名ぐらいを募集いたしまして、夏休み中に実施していきたいというふうに考えております。","voiceIndex":106,"id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"２００名ぐらい募集されるということですけれども、これもある程度地区とかそういうのを関係なく、希望者優先という形でお考えになっているのでしょうか。","respondent":"杉浦生活安全担当課長","answer":"おっしゃるとおりです。広報で募集するですので、そういうことになると思います。","voiceIndex":108,"id":"exchange-048"},{"speaker":"武内委員","kind":"質問・要望","question":"防犯グッズを配布するというふうに出ているんですけれども、何か具体的にこういうものというふうに決められているようでしたら教えてください。","respondent":"杉浦生活安全担当課長","answer":"まだ具体的に決めているわけではございませんけれども、子どもがもらって喜ぶような、そして防犯意識が高まるような、そういったものを考えてあります。","voiceIndex":110,"id":"exchange-049"},{"speaker":"武内委員","kind":"質問・要望","question":"わんぱくパトロールを経験するのは２００人ぐらいなので、それを受けて実際に子どもたちの目線で大人にはわからないような、こういうところが危険じゃないかとか、大人にも気づかないようないろんな意見が出てくると思うんですけれども、そういったものをぜひ同じ世代の子どもたちに情報として配信していくということが必要じゃないかと思うんですが、その辺までお考えになっていられるでしょうか。","respondent":"杉浦生活安全担当課長","answer":"実施後には、子どもたちに作文などを書いていただいて、そしてそれを発表することで、そういったものに生かしていきたいというふうに考えております。","voiceIndex":112,"id":"exchange-050"},{"speaker":"武内委員","kind":"質問・要望","question":"例えば体験をいろいろ語る場とか、今おっしゃったような作文等をぜひお考えいただきたいと思います。これは要望します。最後ですけれども、１５１ページのメールカー運行委託等ということでお伺いしたいと思います。単純にこれだけ比較すると経費が増えているように感じるんですけれども、この辺の事情を教えてください。","respondent":"鷹倉経理課長","answer":"庁舎内で届いた書類、あるいはここから発信する書類についての分類については区の職員、現在では嘱託員等がやっていたわけですけれども、ここの部分を一体としてやっていったほうがより効率的であろうということで、この部分も含めてメールカー運行業務委託等という形で。","voiceIndex":114,"id":"exchange-051"},{"speaker":"武内委員","kind":"質問・要望","question":"内容はわかりましたけれども、単純に私の勘違いだと思うんですが、今回の平成１７年度の予算は２,２００万円、事務事業評価では２,０００万円となっていて、単純に予算が上がっているんですけれども、何か違うところがあれば指摘をしていただきたいと思います。","respondent":"鷹倉経理課長","answer":"この予算書に出ていますのは、メールカー運行業務委託以外のものが出ております。私どもは今の拡大の部分も含めまして、ざっと一千二、三百万円ぐらいの数字になります。","voiceIndex":116,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"私は１５５ページの行政サービスコーナー経費に関連をいたしまして、全体的には行政窓口サービスという視点でお伺いしてまいりたいと思います。新規事業として、武蔵小山駅前にサービスコーナーをつくるということで予算が計上されております。これを開設するにあたりましての背景といいますか、どういった状況から設置することになったのか、まずその辺からお聞かせいただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"品川区におきましては、大井町サービスコーナーで現在やっております。夜間窓口ということで、火曜日の５時から７時まで実施していますけれども、平成１５年に大井町サービスコーナーで日曜日の営業を開始いたしました。","voiceIndex":120,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"大井町サービスコーナーの実績が、このような形にあらわれたのだろうと考えていますが、こういう出先機関といいますか、窓口を外部に展開できるといった技術的な背景としましては、やはり情報技術の裏づけがあって、そういった技術が進んだからこそ、このような外部への展開がどんどん図られてくるだろうなと思うんですけれども。","respondent":"田中情報システム課長","answer":"大井町サービスコーナー等の休日、夜間の部分ですが、従来ですと９時から５時の窓口の運用であったわけですが、今、戸籍住民課長がお答えしましたように区民ニーズがありました。","voiceIndex":122,"id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば新たに武蔵小山、既に大井町にありますが、いわゆる公的な証明書の発行業務は既になされております。今後のサービスコーナーの役割の考え方が、もしありましたらお聞かせいただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"サービスコーナーにつきましては、現状では戸籍住民課の分室という位置づけで実施してきております。それなりの嘱託非常勤の配置ということで、転入届等の届け出については行っておりません。非常に限られた範囲で、区民の需要にこたえるということで現在やってきております。","voiceIndex":124,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"私もちょうど目黒駅の東急の駅舎が地下にもぐる際に、近隣の地域の方々からの要望として、確か当時の中尾根企画課長の時代だったと思いますが、そういう要望があるということをお伝えをした記憶がありますが、ようやく大井町、そして今回武蔵小山とサービスコーナーの開設がなされましたが、今後の他の地区での展開の考え方をぜひお聞かせいただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"可能であれば、目黒区が現在設置しているところに、品川区のサービスコーナーも設けて一緒にやっていきたいということで、目黒区のほうには打診をしている状況です。","voiceIndex":126,"id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"一方、地域センターの動きというのは、むしろ既にあった窓口機能を縮小するような行動であったのではないかという、一つの受け止め方ができますが、サービスコーナーを新設したという動きと、これまでの地域センターの役割という部分での考え方について、ぜひお聞かせをいただきたいと思います。","respondent":"田村地域活動課長","answer":"現実的に、やはり現在のふれあいサポート活動を見ていきますと、町会、自治会をはじめ諸活動、区民まつり等の活動を地域センターが事務局として地域の方々と調整、いわゆるコーディネーター役を果たして、かなり成果が上がってきたというふうに実感しておりますので。","voiceIndex":128,"id":"exchange-057"},{"speaker":"田中委員","kind":"意見","question":"おそらくですが地域センターでの役割を地域業務として強化をするという視点で、窓口的な要素は縮小したということでありますが、その背景として一つは、行財政改革の流れの中で定数削減ということも、一つの見方として視野があって、人を減らすから仕事も減らすという色彩、また非常勤だから仕事ができないという要素があるように受け止められるんですが、そこはそうではなくて、ぜひサービスという視点で。","respondent":"山田区民生活事業部長","answer":"それぞれの特色を持たせて、どういう形で機能が十分に発揮できるかどうか、平成１７年度は少しＰＴを組んで検討していこうということになってありますので、ご理解いただきたいと思います。","voiceIndex":130,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"あそこに都税事務所があるということは、我々区民にとって果たしてどうなのかという思いもありますので、ちょっと時間がございませんので要望ということで、今後の庁舎の建て替えも含めて、そういった長期的なアレンジも含めて、区民にとっても総合的な窓口のあり方というのをぜひご検討いただき、区民サービスの向上につなげていただきたいと考えています。これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-059"},{"speaker":"本間委員","kind":"質問","question":"最初に、水と緑の市町村との交流事業についてお尋ねします。幾つかありますけれども、１５３ページに早川町との交流経費という部分がありますけれども、最近の利用状況といいますか、大ざっぱで結構ですが、例えば去年と比べてどうだというふうな形でわかったら教えてください。","respondent":"長田区民課長","answer":"早川町との交流の中で、利用実績という話ですけれども、平成１５年度につきましては２,０７６人に行っていただきました。この中心となるのは、品川区のほうで市民レベルでの交流を目指しているというようなことで、この動機づけとなる各種のツアーを実施しています。","voiceIndex":134,"id":"exchange-060"},{"speaker":"本間委員","kind":"質問","question":"２,０７６人という形で、置き替えてみますと向こうの人口を上回るような形の実績みたいな感じがしますけれども、私ども何回かお邪魔したことがあります。そのようなステータスにあるということ。それから、交通の便に非常に難があるということで、私どもも当初は随分躊躇していましたが、最近は南アルプス号というのができて、片道３時間半程度で行けるというのが出ました。","respondent":"長田区民課長","answer":"そういった意味では、早川町は大変人の気持ちの優しいところですので、こういったことでぜひ行政がツアーをずっと継続するのではなくて、自主グループなり何なり、育成をするような形へ持っていきまして、区民、町民レベルの、民間レベルの交流に持っていきたいと。","voiceIndex":136,"id":"exchange-061"},{"speaker":"本間委員","kind":"質問・要望","question":"最近、現地でもこちらから現地を訪れる人たちに対して、何か希望がありましたらというようなことで、年々区民の要望を取り入れながら利用実績も上げているというふうに聞いておりますが、交流事業でありますので、こちらからよさを求めていくと同時に、逆に向こうのほうからこちらに来るときに、例えば品川区を中心として、おそらく東京だと思いますが案内するには、例えば品川区だったらどこ。","respondent":"長田区民課長","answer":"ただ、ディズニーランドにつきましては、入園料もちょっと高うございまして、過去には行ったこともありますけれども、その事業の中で子どもの要望等も参考にしながら、これは早川町の事業ですので、早川町が主体的に判断をしているという状況です。","voiceIndex":138,"id":"exchange-062"},{"speaker":"本間委員","kind":"質問・要望","question":"細かく挙げるといろいろ出てこようかと思いますが、交流事業ですから、相手のよさを知ると同時に、また品川区あるいは東京のよさを知っていただきたいということで、不断の交流が続いていくといいなというふうに思っています。それから、湖でのボート遊びができるのかどうか。遊びはいろいろ聞きましたものですから、次から次と新しいのが出ているということですので、よろしくお願いします。","respondent":"長田区民課長","answer":"今回は３,４００調査区、２,８００世帯ぐらいを予定しています。これは平成１２年にも行われてありますけれども、大体調査区でおそらく５２７人ぐらいの増になるだろうと思います。","voiceIndex":140,"id":"exchange-063"},{"speaker":"本間委員","kind":"質問・要望","question":"前回より２万８,０００世帯増えているという状況です。そうしないと、真面目な方につきましては、１軒の家に足を運ぶのに１０回とか２０回というような話も出たことがありまして、大変真面目な人ほど悩むというような傾向があるようですので、その辺についての話し合う場だとか、ご指導をする場があるかどうか教えてください。","respondent":"長田区民課長","answer":"調査員の方々には、それぞれ各地域センターごとに３回から多いところでは５回ぐらいやっているところがありますけれども、そういった説明の場を設けまして、詳しい説明をしています。","voiceIndex":142,"id":"exchange-064"},{"speaker":"本間委員","kind":"意見","question":"既に、そういうふうな話題が出てきておりまして、なかなか協力者を募ることができないまま悩んでいらっしゃる地域もあろうかと思います。それから、出ていましたけれども、外国人居住者の件でも似たようなことが言えると思いますので、その辺の対応方について一言お願いします。","respondent":"長田区民課長","answer":"かなり最近では大型マンションができてきてあります。国勢調査の調査区は、大体１調査区４０世帯から７０世帯ぐらいで構成しておりますので、大型マンションになれば、それで割り返した数字の調査員が必要になるという形になります。","voiceIndex":144,"id":"exchange-065"},{"speaker":"本間委員","kind":"質問・要望","question":"ちょうどこれからそのような問題が話題になってくる時期ですので、ひとつ対応方について、いい仕事をしていただくためには、ひとつ元気づけてやっていただく方法をお伝えしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは職員費のことについて、特に非常勤職員の交通費と休暇の取得について伺いたいと思います。非常勤職員の交通費の支給ですけれども、平成１７年度募集から交通費は別途支給となりましたけれども、これまでとどのような政策変更、理由や背景があったのかということと、変わった非常勤職員の交通費と現在の常勤職員の交通費、それぞれ上限がどれぐらいになっているか、ご説明いただきたいと思います。","respondent":"桑村人事課長","answer":"その一つが、基本的には非常勤というのは勤務時間が短い、あるいは日数等についても少ない人数を効果的に入れる仕事がいいだろうというような基本的な考え方に基づいて、もう１回職の整理をさせていただいているのが一方です。","voiceIndex":148,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"区の職員だと、常勤だと最高５万５,０００円まで、その範囲であれば実費支給をしているわけですから、非常勤職員が２０日勤務でも８,４００円、常勤職員の５分の１程度しか支給されていないんですね。私は改めて正規職員と対等に扱うためにも、非常勤職員の方にも実費支給をやるべきではないかと思いますけれども、いかがでしょうか。","respondent":"桑村人事課長","answer":"特に、仕事についての理解のある区民の方を優先したいというのは、基本の考え方です。その意味では、一定の報酬額もお支払いしているわけですので、その中で区民の方でもいわゆるかかる費用というのものは、今後平成１７年度から対応していこうです。","voiceIndex":150,"id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"正規職員であれ、非常勤職員であれ、同一労働、同一賃金というのが大原則だと思うんです。私は交通費の支給を常勤職員と非常勤職員で差別をするというのは、人権上の問題だと思うんです。当然、憲法でも労働の原理、また労働基準法でも同一労働、同一賃金が原則なんですから、それをきちんと守るべきではないかと思いますけれども、区外の方の人数と見解を教えてください。","respondent":"桑村人事課長","answer":"すべての非常勤職員について、どこから来ているかというのは把握していませんけれども、例えば保育園等ですと９割以上が区内の方です。今の同一労働、同一賃金のお話ですけれども、同じ仕事をすれば同じ給料を払うというのは、それは同じだと思うんですね。","voiceIndex":152,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"９割の方が区民ということは、１割の方が区外からいらっしゃるということです。片道２１０円を超えてしまった場合は、すべて自腹になってしまうというのは、時代錯誤ではないかと思うんです。交通費と一緒に、もう一つ非常勤職員の休暇についてなんですけれども、まず非常勤職員にはどういった休暇があるのか、どのように説明をしているのか、そこから教えてください。","respondent":"桑村人事課長","answer":"非常勤職員によって休暇の種類といいますか、日数、時間によってかなり違いますので、基本的には労働基準法上の休暇は取得できるというような形で制定したものです。","voiceIndex":154,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"一例を紹介したいと思うんですけれども、すまいるスクールに勤務している非常勤職員から伺ったんですけれども、勤務条件、特に休暇についての説明が不十分だと話していました。そんなことも話していました。僕は耳を疑ったんですけれども、民間では就業規則、公務員職場では設置要綱だと思うんですけれども、品川区では非常勤職員に設置要綱の周知というのは、具体的にどのように行っているのでしょうか。","respondent":"桑村人事課長","answer":"採用する際に説明をさせていただいて、いわゆる説明会という形で勤務条件のあらましみたいなことでお話しをしておりますので、それを見ていただければというふうに思います。","voiceIndex":156,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"次世代育成をどう理解しているかと思うんですね。実際、私が伺いたいのは、周知について労働基準法第１０６条に沿って、きちんと行われているのかどうか、第１０６条をどう理解して、どう実施しているのか教えてください。","respondent":"桑村人事課長","answer":"個別の非常勤職員の説明については、各所管が行っていますので、そこの中身については私は知り得ていませんけれども、説明しているという内容については、きちんと基本的なものは説明していて、お話しをしていると思います。","voiceIndex":158,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"労働基準法第１０６条では何て書いてあるかというと、一番初めの説明会のときに話せばいいと書いてあるのでは決してないわけですね。「常時各作業場の見やすい場所へ掲示し、または備えつけること。例えばすまいるスクール、保育園、児童センター、学校の事務、いろいろ非常勤職員の方がいらっしゃいますけれども、ここできちんと行われているのかどうか、そこを伺っているので答えてください。","respondent":"桑村人事課長","answer":"先ほど申し上げましたように、説明会のときに、そこについての休暇等のあらましというのはつくってあります。これは来られた方にお渡ししているわけです。","voiceIndex":160,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"就労の環境の整備が位置づけられているわけですから、そこをどう理解しているのか、これからどうやって周知させていくのか、そこをきちんと答えていただきたいと思います。実際にそれぞれの作業場で設置要綱がきちんと見やすい場所にあるんですか、ないんですか、教えてください。","respondent":"桑村人事課長","answer":"休暇の権利というのは、基本的なところ載っていますけれども、これはお話しとして勤務条件のあらましということで、こういう休暇があります、こういうふうな形で取れますというものをお渡ししてご説明しているわけですので、どういう形で周知をすればお話しになるのか。","voiceIndex":162,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"どうしても堂々めぐりになっちゃうんですけれども、きちんと見える場所に掲示するように、また実物を職員に渡すように、また備えつけられるように、こうしてくださいと決まっているんですね。では、具体的に各所管にも聞きたいんですけれども、児童センターではどこに置いてあるのか、すまいるスクールではどこに置いてあるのか、また保育園の職場ではどこに置いてあるのか、それを教えてください。","respondent":"桑村人事課長","answer":"そういう意味では、先ほどから言っていますとおり、私どもの正規の職員の者についても掲示しているわけではございません。ご本人にその形のものは１年に１回、きちんとお渡ししているわけです。","voiceIndex":164,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"すまいるスクールの職員の例を出しましたけれども、多くの方が生理休暇があることも説明されたことがないと。産前産後の休暇があることも説明されたことがないと。育児時間についても説明されたことがない。有給休暇に関しては、職員の方から積極的に取るようにと言われるそうですけれども、こういった状況をきちんと把握をしていただき、適切に改善をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-076"},{"speaker":"築舘委員","kind":"質問","question":"１４７ページの国際友好都市交流事業、それから１６３ページのボランティア活動の連携のしくみづくりに関して、お聞きしたいというふうに思っております。スイスのジュネーヴ市との友好都市というのは、平成１８年、来年に１５周年になるということであります。","respondent":"宮地総務課長","answer":"その後、国際友好協会を通じて、またさまざまな事業を展開して現在まで至っているところです。","voiceIndex":168,"id":"exchange-077"},{"speaker":"築舘委員","kind":"質問","question":"その点、特に青少年の交流というのは、中学、高校のまだこれから夢を抱いている青少年のときにジュネーヴ市に行き、ポートランド市に行き、またオークランド市に行きということで、そういった形での国際人としての貴重な経験が、今後の日本人としての国際感覚を養い、そして素晴らしい日本を背負う青年が生まれるということになると思うんですけれども、その辺の国際交流における青少年の行き来の問題。","respondent":"宮地総務課長","answer":"そういうことを積極的に、今後とも助成という形でやっていきたいというふうに考えております。","voiceIndex":170,"id":"exchange-078"},{"speaker":"築舘委員","kind":"質問・要望","question":"まだ先の話ですけれども、来年度は１４周年、この予算は１４年目の予算ですから、そんなにはあれでしょうけれども、１５周年の予算の組み方というのはどんなふうになるのか、また規模的にはどんなものかというのがわかればお聞かせいただきたい。","respondent":"宮地総務課長","answer":"周年行事という形で、過去も５周年、１０周年というふうにやってきたものですから、今年度の秋の予算編成に向けて、１５周年を盛り上げるための補助金をどんな形でつけられるか、これから検討してまいりたいというふうに考えております。","voiceIndex":172,"id":"exchange-079"},{"speaker":"築舘委員","kind":"質問","question":"大変、市長も心待ちにしておりますので、高橋区長をはじめ議会の皆さん、また民間の皆さん方が来るということを期待しているものですから、その辺をよろしくです。次に、ボランティア活動の連携のしくみづくりですけれども、これはいろいろなボランティアがありますね。","respondent":"榎本行財政改革担当課長","answer":"特に区民の方から見て、区がどんな活動をやっているのかよくメニューがわからないという要望がございまして、そういった意味で、そういうメニューを総合的にきちんとつかみまして、こういうメニューがありますということで、本庁舎でも紹介しますし。","voiceIndex":174,"id":"exchange-080"},{"speaker":"築舘委員","kind":"質問","question":"それはなぜなのかなということもありますけれども、やはりどうしても単なるお手伝いの気持ちはあっても、職場に行くと具体的なことは職員の方がしっかりやっている部分もあるので、その辺の職員の方との連携というんですか、そういうのがうまくできているのかなという感じがするんですよ。","respondent":"榎本行財政改革担当課長","answer":"今回のしくみづくりというところは、情報提供の部分を中心にやっておりますけれども、その中でボランティアの方々がどういうふうにボランティアを継続しやすいかということで、それぞれの所管でやっている募集の情報、それから講座の情報。","voiceIndex":176,"id":"exchange-081"},{"speaker":"築舘委員","kind":"意見","question":"特に高齢者の方々も、お元気な方が多いわけで、シルバー大学は大変人気になっておりますが、せっかく知識を得て身につけたものを、どういうところで発揮するのかというようなところが、今ひとつはっきりと出せないといいますか、そういう部分が多少あるんじゃないかということ。","respondent":"榎本行財政改革担当課長","answer":"今、委員ご指摘の、特にそういう横の連携の部分を強化するために、やはりこういう情報の共有システムを使いたいです。","voiceIndex":178,"id":"exchange-082"},{"speaker":"嶋委員","kind":"質問","question":"私のほうからは３点、１４９ページの人権啓発費について、二つ目には１５５ページのわんぱくパトロール事業について、三つ目、１６２ページの防災対策費についてお伺いいたします。私も２３区の男女共同参画センター、女性センターにまいりましてトイレに入らせていただきますと、必ず洗面台の上にちょっとしたメモ書きが乗っております。何かなと手に取りますと、大抵暴力反対、ＤＶという形です。","respondent":"武内人権啓発課長","answer":"今、言われました各施設のトイレ等ということですけれども、それにつきましてはまた関係課と協議して進めていきたいなと思います。","voiceIndex":181,"id":"exchange-083"},{"speaker":"嶋委員","kind":"質問・要望","question":"そっとポケットに入れられるサイズのものが一番身近ですぐ役に立つ、お財布とか手帳に入れられるので、ぜひこれは身近なところにもっと置いていただきたいなと考えていますので、よろしくお願いいたします。二つ目ですが、わんぱくパトロールについてです。何か今のままではないと思いますが、一工夫、二工夫されていらっしゃるのか、もしありましたらお聞かせいただきたいと思います。","respondent":"杉浦生活安全担当課長","answer":"今のところ、服装として可愛らしい帽子をかぶらせて、子どもにパトロールをさせるとか、そんなような仕組みというか、そんなものを考えてあります。","voiceIndex":183,"id":"exchange-084"},{"speaker":"嶋委員","kind":"提案","question":"そういう意味で、高齢者の方も割と軽く音が出る笛ですので、こういうものを防犯グッズとして配っていただけたら、これも防災上にも、埋まったときに自分がここにいるということもできるので、多角的に広範囲に使えるので、そのときに一つの提案をさせていただきたいと思いますが、もしご意見がございましたらお聞かせいただきたいと思います。","respondent":"杉浦生活安全担当課長","answer":"貴重なご意見、ありがとうあります。ぜひ、にぎにぎしく出発し、そしてホイッスルなどを持たせて、思い出に残るものにさせていきたいなというふうに思っております。","voiceIndex":185,"id":"exchange-085"},{"speaker":"嶋委員","kind":"質問・要望","question":"防災対策費についてです。これはお聞きしたいんですが、今、防災レポート車というステッカーが張られているタクシーが区内を走っております。このことで、もし情報的に何かございましたら、役目的なものを教えていただきたいと思います。","respondent":"久保田防災課長","answer":"今、お話しのあった防災レポート車なんですが、申し訳ないですけれども、私承知しておりません。","voiceIndex":187,"id":"exchange-086"},{"speaker":"嶋委員","kind":"質問・要望","question":"もし、情報的にあったら、また後で教えていただきたいと思います。実は防災というステッカーを見ただけでも、区民はほっと安心して、品川区内に走っているタクシー会社もいろんな防災とか防犯で頑張っているのかなと考えています。そういう意味で、品川区の防犯、防災ですが、区内のタクシー会社と対策的なもので連携が、いざというときに緊急時、どのような対策になっているのかお聞きしたいと思います。","respondent":"久保田防災課長","answer":"その延長上として、計画の中では車両の確保としてタクシーを活用するというようにはなってありますので、当然連携についても、今後十分検討していく余地はあると考えています。","voiceIndex":189,"id":"exchange-087"},{"speaker":"嶋委員","kind":"質問・要望","question":"情報収集という部分でも、大変大事なところかなと思っていますが、今後、このようにタクシー業界とか、もう一つ私はタクシーの防犯レポート車のステッカーを見てから、品川区内を走っている公用車にも、ぜひこういう防犯、防災のステッカーとか、いざというときにとかという何かＰＲするものが張ってあったら、もっと安心、無事故という部分でもありますが。","respondent":"鷹倉経理課長","answer":"庁有車もいろいろな形で使っている場面がありますけれども、そういう趣旨にのっとった形の工夫ができるかどうか検討してみたいと思います。","voiceIndex":191,"id":"exchange-088"},{"speaker":"嶋委員","kind":"意見","question":"ぜひ、区内を走る車に関しても、清掃自動車も含めてと思いますが、品川区中がみんなが無事故、無事、安全を祈っているんだというものを区民に周知することが、大変安心のもとになるかと思いますので、ぜひ品川区に走っている公用車等にご配慮をいただけたらと思います。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":193,"id":"exchange-089"},{"speaker":"三村委員","kind":"質問","question":"私のほうからは１５５ページの防犯設備整備助成事業、１７５ページの誕生記念品支給経費、１６３ページの学校等の避難所機能の充実、１７５ページの住民基本台帳事務費についてお伺いいたします。最初に、防犯設備整備助成事業についてお伺いいたします。こちらの助成金の目的を教えていただけますでしょうか。","respondent":"杉浦生活安全担当課長","answer":"防犯設備整備の助成金につきましては、防犯カメラの助成です。","voiceIndex":195,"id":"exchange-090"},{"speaker":"三村委員","kind":"質問・要望","question":"こちらの防犯カメラ設置にあたっては、プライバシーへの配慮が欠かせないと思いますけれども、そういった助成金の支給に際しては、そういったプライバシーへの配慮がされているかどうか、きちんとその辺のところまで配慮されて助成金を支給されているのかお伺いいたします。","respondent":"杉浦生活安全担当課長","answer":"この助成制度につきましては、地域の合意がなされること。それから、防犯に関する継続的な活動がなされること。そういったことが助成の要件になっておりますので、その辺のところをクリアするように、区として指導していくという形になります。","voiceIndex":197,"id":"exchange-091"},{"speaker":"三村委員","kind":"質問","question":"私が区民委員会にいたときに、京都市に視察に行ったときに、そちらの商店街では商店街の人だけではカメラの情報が見られない。品川区においても検討会を設置いたしまして、防犯カメラ設置の条例を検討すべきではと思いますけれども、お考えをお聞きいたします。","respondent":"杉浦生活安全担当課長","answer":"この防犯カメラにつきましては、本会議で区民生活事業部長が答弁したとおり、商店街やまちの方の発意に基づいて補助制度を活用しながら設置を進めていくというものでありまして、区が主体となって一般的にまちを監視する防犯カメラをつけるということは考えてございません。","voiceIndex":199,"id":"exchange-092"},{"speaker":"三村委員","kind":"質問","question":"ぜひ、十分プライバシーに配慮した運営をよろしくお願いいたします。次に、１７５ページの誕生記念品支給経費についてお伺いいたします。この制度ができたのはいつ頃なのか、またその記念品がどのような経緯で選定されたのかお伺いいたします。","respondent":"冨田戸籍住民課長","answer":"誕生記念品支給経費につきましては、平成４年度から実施しているものです。","voiceIndex":201,"id":"exchange-093"},{"speaker":"三村委員","kind":"提案","question":"今回、こちらの経費を見ますと、１人当たり１,０００円程度経費計上をして支給をしているかと思うんです。ガラスの写真立ての経費を使って、そういった品川区でのオアシスルームですとか、ファミリーサポートですとか、産後支援ヘルパーのお試し利用券みたいなものを出したら、とても喜ばれるのではないかと思いまして、ご提案をしたいんですけれども、お考えをお伺いできますでしょうか。","respondent":"榎本行財政改革担当課長","answer":"今現在、子育てのほうにつきましては、次世代育成支援行動計画ということで、いろいろ具体的なものも検討しておりますので、その中で全体的にどういうふうにバランスを取ればいいのかというものを考えていきたいと考えています。","voiceIndex":203,"id":"exchange-094"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ、ご検討をよろしくお願いします。次に、１６３ページの学校等の避難所機能の充実についてお伺いいたします。防災の視点で学校が果たす役割としては、どのようにお考えでしょうか。現在学校ごとに避難所連絡会議が組織されているかと思いますけれども、小中一貫校建設にとなって廃校となる学校の避難所連絡会議は、今後どのようにされるのかお伺いをいたします。","respondent":"久保田防災課長","answer":"その一つが避難所連絡会議ということになるわけですけれども、今小中一貫校の絡みで廃校になったところですけれども、基本的にはそのまま学校は避難所として使うということになっていますので、避難所連絡会議もこのまま継続するということが基本的な考え方です。","voiceIndex":205,"id":"exchange-095"},{"speaker":"三村委員","kind":"質問","question":"こちらの学校の施設は、避難所の機能は残すということでよろしいでしょうか。","respondent":"久保田防災課長","answer":"建物としては残っておりますので、そのまま避難所として使っていくという考え方です。","voiceIndex":207,"id":"exchange-096"},{"speaker":"三村委員","kind":"質問","question":"そのまま建物が残されるということであれば、ぜひ施設の有効活用をお願いしたいんですけれども、そういった場合、施設利用の方法について公募等をされてはと思いますけれども、お考えをお伺いいたします。","respondent":"榎本行財政改革担当課長","answer":"こういう学校施設等、大規模施設の有効利用につきましては、庁内である程度原案をまとめてからお諮りするということで考えておりまして、今現在まだ庁内でのいろいろな案を練っているところです。","voiceIndex":209,"id":"exchange-097"},{"speaker":"三村委員","kind":"質問・要望","question":"１７５ページの住民基本台帳事務費についてお伺いいたします。私の今までの理解は、そんなところまではわからないというふうに理解していたんですけれども、ちょっと教えていただけますでしょうか。","respondent":"冨田戸籍住民課長","answer":"住民票の大量閲覧がありますけれども、そこに載せてある情報としては、住所、氏名、生年月日、性別、この４情報だけです。載せ方ですけれども、住所別になっていますので、例えば名字が同じであれば、ある程度の類推は可能かとは思いますけれども、一応そういう状況です。","voiceIndex":211,"id":"exchange-098"},{"speaker":"三村委員","kind":"質問","question":"そういった情報まで類推できるということは知らなかったんですけれども、そういったところで類推が可能ということであれば、今、高齢者をねらった犯罪ですとか、そういったことが多々あります。法律との関係がありますのでかなり難しいかとは思うんですけれども、犯罪防止の観点から住民情報の管理、類推ができないような操作等ができないのかお伺いしたいんです。","respondent":"冨田戸籍住民課長","answer":"閲覧の利用ですけれども、市場調査であるとか、世論調査であるとかというような利用の仕方がありますので、その際からすると、やはり住所順ということはやらざるを得ないのかなというふうに考えております。","voiceIndex":213,"id":"exchange-099"},{"speaker":"三村委員","kind":"質問","question":"高齢者をねらった犯罪等を起こす可能性があるということことで、国に対しての働きかけ等も、そういう情報を上げていくということもできるかと思うんですけれども、品川区としてはほかにも住民基本台帳の情報を利用される危険性がほかにも考えられるかどうか、ちょっとお伺いしたいんです。","respondent":"冨田戸籍住民課長","answer":"同時に、目的外使用しないようにということで、誓約書も出していただきますし、通常は鉛筆で転記をしているんですけれども、何件取ったのかとか、そういった形での調査の目的、内容についての把握に努めるようにしてきております。","voiceIndex":215,"id":"exchange-100"},{"speaker":"三村委員","kind":"質問","question":"本当に難しい問題なんですけれども、住民基本台帳ではなくて画面で見られるように変更するというお話だったんですけれども、その場合は住所ごとであるとか、年齢であるとか、そういった検索機能まで入っているんでしょうか。","respondent":"冨田戸籍住民課長","answer":"出し方としては、現在は簿冊形式で９１冊ありますけれども、住所順に北品川からずっと並んでいます。その順序で流していくだけです。編集機能は一切つけていませんので、ただ住所順に追いかけていくだけという状況です。今の紙の台帳と同じような状況です。","voiceIndex":217,"id":"exchange-101"},{"speaker":"三村委員","kind":"意見","question":"なかなか本当に難しい問題だと、法律で公開が義務づけられているので難しいとは思うんですけれども、一方で個人情報保護法も制定されておりますので、特にこういった情報は犯罪のもととなりますので、プライバシーに配慮した対応ができないか、国等にぜひ意見等を上げていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-102"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"１５７ページの各種団体分担金の三つ、若干昨年より上がっているんですけれども、新しい自治会館といいますか、区政会館にいよいよ移るわけですけれども、各区の分担金は増やさないという大原則といいますか、それが初年度から、多少引っ越しでかかるのかいろいろあるんでしょうけれども、２,０００万円ぐらい増えている理由を聞かせていただきたいのと、平成１７年度移るわけですから。","respondent":"榎本行財政改革担当課長、宮地総務課長、桑村人事課長","answer":"音声ファックス情報提供、それからパソコン通信の市内化ネットですとか、公共施設の案内予約システム、中小企業の総合支援システム。こちらにつきましては、今後早い時期にどういった形の処分になるか、利用になるかということで検討していくということを伺っております。今回、国勢調査を平成１７年度に実施するということで、先ほども３,７４０人というお話がございましたが、この人数が本年度加わっておりますので。","voiceIndex":221,"id":"exchange-103"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"できるだけ早く進んでいただきたいと、それはお願いしておきます。それがどういうところまで来ているんですかと聞いているので、「検討しています」では答えじゃない。検討しているでしょう、どういうことをですかという、そういうお答えをいただきたい。それから、これから先、分担金は増えないというふうに、これは約束ですから、きちんと議会にいつでも説明できるようにしておいていただきたい。","respondent":"榎本行財政改革担当課長、濱野助役、桑村人事課長、高橋区長","answer":"今、委員ご指摘の点を踏まえて、今後の区としての行動に生かしていきたいと考えています。幾つかの選択肢が出ておりますけれども、この場ではつまびらかにできませんが、早急に結論を出す予定です。職員構成等についてご説明申し上げたいと思います。それについて、教育委員の中から出す教育長ということでの選任同意です。選任されました教育長は、地方教育行政の組織及び運営に関する法律だと思いましたが、一般職に位置づけられるわけです。","voiceIndex":225,"id":"exchange-104"},{"speaker":"林（宏）委員","kind":"質問","question":"ここでやるのはおかしいかもしれませんけれども、教育費の冒頭に教育委員４人、報酬何がしと出ているわけですね。もう一つお伺いしたかったんですけれども、秋頃の新聞ですけれども、国家公務員との給与の差額、ラスパイレス指数で、２３区で品川区は２位。もう時間がないんですけれども、２月２３日、私の誕生日の日経新聞ですけれども、「国家公務員基本給一律５％下げ」という、大きな見出しが出ています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-105"},{"speaker":"山村委員","kind":"質問・要望","question":"私からは１７４ページ、住民基本台帳費の閲覧のことを聞こうと思ったんですが、１５分ほど前にほとんど聞かれてしまいましたので、だからといってなかなか新しい質問も思い浮かびませんので、少し困っているところですが、ちょっと違う範囲のことで、住民異動届を受理する際、運転免許証など写真つきの証明書の提示を品川区では求めているのかどうかというのを、まず教えていただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"平成１５年に施行は７月でしたけれども、品川区の本人確認に関する条例が制定されておりまして、戸籍、住民基本台帳関係の届け出、それから証明書発行に際しては、基本的には写真つきの証明書で本人確認をする。","voiceIndex":233,"id":"exchange-106"},{"speaker":"山村委員","kind":"質問・要望","question":"写真つきの証明書の提示を求めているというふうにお伺いしてよろしいと思うんです。それと、政府の規制改革・民間開放推進本部で住民票の自動交付機の設置基準を大幅に暖和することに決めたと思うんですが、これによりコンビニエンスストアなどにも交付機を設置しやすくなったとのことですが、このような談話を受けて、品川区は今後どのような考えなのか教えていただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"ある程度の普及がありませんと、自動交付機を置いても利用が実質できないということになりますので、それらを見ながら考えていきたいというふうに、現在は思っております。","voiceIndex":235,"id":"exchange-107"},{"speaker":"山村委員","kind":"質問・要望","question":"先ほど住基カードのことが出てきたので、住基カードのことも聞かせていただくんですけれども、住基カードの場合、即日交付の場合は自宅に郵送される照会書があれば受け取り可能とのことなんですが、照会書だけ奪ってきて、不正に住基カードをつくってお金を借りているような詐偽が発生しているそうなんですが、品川区では即日交付等で照会書があったとしても、本人確認を写真つきのようなものでしているのか。","respondent":"冨田戸籍住民課長","answer":"最初に申請をいただきます。その後、照会書を出してお持ちいただく。最終的に写真をつけた形でのカードを交付するということで、その都度本人確認を実施しております。写真つきの免許証等をお持ちでなければ、保険証とかその他いろいろな証明書類ですね。","voiceIndex":237,"id":"exchange-108"},{"speaker":"山村委員","kind":"質問","question":"三村委員が質問をされていなかったと思う部分だけ聞かせていただければと思います。先日、ＮＨＫのニュースを見ておりましたら、住民基本台帳の閲覧で、まず母子家庭を探し、その後、小学生、中学生の女子がいるかどうかを探して、ある男性が暴力を働いたとのことなんです。","respondent":"冨田戸籍住民課長","answer":"現状では、そこまではやっておりません。","voiceIndex":239,"id":"exchange-109"},{"speaker":"山村委員","kind":"確認","question":"本人確認とか写真つきの証明書の提示とか、そういうのはどうなされているんでしょうか。","respondent":"冨田戸籍住民課長","answer":"なお疑問が残れば、いろいろな個人しか知らない、その人しか知らない事項についても、若干の質問をするという取り扱いをしています。","voiceIndex":241,"id":"exchange-110"},{"speaker":"山村委員","kind":"質問","question":"品川区は完璧すぎて、私はこれ以上質問することがなさそうですので、この辺にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-111"},{"speaker":"山路委員","kind":"質問","question":"私は１７４ページ、住民基本台帳費の住民票取り扱い窓口のサービスについてお伺いをいたします。区民の方よりご相談をいただきまして、その内容についてお伺いをいたします。隣の区で児童手当をいただいていた方です。ところが、今年の２月まで全く申請するということを知らなかったそうです。そこで、住民票受け入れ窓口のサービスについては、どのように徹底をされているのかお伺いいたします。","respondent":"冨田戸籍住民課長","answer":"その記載のある方については、通常はそれなりのご案内をさせていただいているものです。もし、そういった説明がなかったということですと、その際は漏らしたのかなということで、大変失礼をしたことになります。申し訳ございません。","voiceIndex":246,"id":"exchange-112"},{"speaker":"山路委員","kind":"質問・要望","question":"私もこの話を聞きまして、国の制度でＩＴ化とかワンストップ化とか、オンラインシステムが非常に進んでいる現在にあって、どうしてそういうミスが生じたのか非常に疑問に感じたわけなんですが、全国どこの自治体でも漏れなく資格のある方はいただけるシステムだと思うんです。２３区でネットワークを組んでいるとか、そういうシステムはないのかどうか、お聞かせいただきたいと思います。","respondent":"冨田戸籍住民課長、辻田児童課長","answer":"住民基本台帳ネットワークシステムがありますけれども、そこで記録されているのは、住所、氏名、生年月日、性別の４情報のみですので、ただいまの児童手当等の情報は一切入っておりません。現在の形ですと申請が２月にあったという状況ですと、２月からというような形での支給になってしまうです。","voiceIndex":248,"id":"exchange-113"},{"speaker":"山路委員","kind":"質問・要望","question":"せっかく品川にお住まいの児童手当該当者が全員いただけるようになって、非常に喜ばしいかなと思っていたら、たまたま他区から引っ越されたこういうことがございましたので、区民サービスにおきましては気をつけていただきたい。そのために徹底と改善までいかないんですけれども、今後より区民サービスに徹底していただきたいと思いますが、どのようにお考えでしょうか。","respondent":"冨田戸籍住民課長","answer":"従来からやってきていることではありますけれども、件数もたくさんある際もありますので、そういう場合につきましても、十分慎重に取り扱うように伝えたいと考えています。","voiceIndex":251,"id":"exchange-114"},{"speaker":"山路委員","kind":"質問・要望","question":"申請制度というのは、非常に言葉では簡単なんですけれども、知らない区民がやっぱりいらっしゃるんです。もちろん品川区民は広報にも載りましたし、盛んに宣伝もされましたし、品川区に住んでいる人は問題なかったんですが、こういうために窓口に、せめて他区から引っ越して来た方は申請をしてくださいとか、きめ細かなサービスを今後これを機会にお願いしたいわけです。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは１５９ページのタウンミーティングと１４９ページの同和生活相談費についてお伺いしたいと思います。平成１６年度から４回のタウンミーティングが行われましたけれども、４回のテーマと参加人数、そしてそれに対する参加申し込みの人数と、今年度１年で合計何人の方が区長と直接話すことができたのか、その人数についてお聞かせいただきたいと思います。","respondent":"中川原広報広聴課長","answer":"平成１７年度の予定ですけれども、前回のところでご意見をいただきました子どもたちの意見をというお話もございましたので、１回は中学生を対象に行いたいと考えています。","voiceIndex":255,"id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"開かれた区政にということで、これをぜひ充実をさせていただきたいという立場で質問をします。皆さんに発言をということで２０名にされたということなんですが、希望者が全員参加できるようなタウンミーティングにぜひしていただきたいという思いなんですね。ぜひご参加ください」という形で載せていただいて、ＰＲもしていただきたいなというふうに思うんですけれども、いかがでしょうか。","respondent":"中川原広報広聴課長","answer":"回数を多くということですが、結構応募者の方は抽選といいますが、何回も手を挙げている方はご遠慮いただいているんですが、初めて応募している方には来ていただくようにしております。テーマと日程と会場等の予定を決めまして実施しているところです。","voiceIndex":257,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どちらにしても、４回で１００名というのは、これだけ大きく選挙広報に掲げているところからすると、やっぱり３３万人に対して１００名というのは少ない人数じゃないかなというふうに思うんです。それともう一つ、月見橋の家の３階でされていますけれども、総務部分室の広さと相談室の広さ、かなり広いという感じがするんですけれども、何m2ぐらいあるのか教えていただきたいと思います。","respondent":"武内人権啓発課長","answer":"先ほども人権意識調査のお話しをさせていただきましたけれども、区民意識調査の中で、同和問題について問題があると理解している方は、８割方があるというふうに回答しておりまして、また同和問題があるという方の中から。","voiceIndex":259,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"相談室の広さが３分の２ぐらいということですけれども、そうすると相談室の広さとして７０m2ぐらいあるわけです。私は広報広聴の相談室も見ましたけれども、ここはそんなになくて、ここの何倍あるんでしょうかというくらいの本当に広い、相談室の中は見せていただけませんでしたけれども、７０m2の部屋で１日１回あるかないかの相談というのは、本当に効率的と言えるのかということが１点です。","respondent":"武内人権啓発課長","answer":"１人の相談員の方が相談するには、７０m2で広いんじゃないかというようなお話ですけれども、差別の問題というのは、当事者１人が机と相談員に向かってするということではなくて、場合によっては複数の方にお出でいただいて相談になるという部分がありますので。","voiceIndex":261,"id":"exchange-119"},{"speaker":"伊藤委員","kind":"質問","question":"それは非常に評価いたします。予想もしないさまざまな災害、テロ等に対する品川区の初動態勢の確保ということを目的に危機管理室を立ち上げたわけですから、さらに進んで、今度は品川区の各事業部との連携、それからマニュアルづくり、それから管理室の仕組みと品川区の防災計画の整合性はどうなのかなという思いがありますので、そのことについての将来の検討方をお聞かせください。","respondent":"宮地総務課長、久保田防災課長","answer":"各事業部との連携につきましては、当然のことながらそれぞれの事業部で持っている危機管理に対するマニュアル、対応、方針ともすべて通じていなければいけませんので、そのマニュアルをまず収集する。当然ながら、本部長をはじめ副本部長には配備しながら、それから実際に対応する実戦部隊等についても、一応モデル的ですので配備をして、通信のやり方なりをやってみて、そのことを検証しながら今後につなげていきたいと。","voiceIndex":264,"id":"exchange-120"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もっと言うならば、一朝有事の際に、だれがどこに行って、どういうふうな仕事をするかということまで決めていきませんと、本当の目的は達成されないわけでありますので、当然今年から始まった組織でありますから、すぐにどうこうということではありませんけれども、せっかくつくったわけですから、やはりそれをもっと具体化して細分化して、システムとして立ち上げていくことをしていきませんと。","respondent":"宮地総務課長、久保田防災課長","answer":"おっしゃられたように、絵に描いたもちにはならないように、これが機能するように、そのレベルに応じた何か対応マニュアルをつくっていくように、これからやってまいりたいと考えております。実際のその辺の活動マニュアルについては、細かい点はこれからの検討になりますけれども、基本的には、そういう形での活用を図っていきたいというふうに思っております。","voiceIndex":267,"id":"exchange-121"},{"speaker":"伊藤委員","kind":"質問・要望","question":"研修費、退職金等に関連してでありますけれども、いろいろ聞いてまいりますと、品川区には、特別な指導が必要とされる職員が１０名から２０名ぐらいいるということを聞いております。品川区を定年退職を迎える前に、自己都合で退職された方が、品川区を相手に退職金に対する裁判を起こして、昨日その結果が出たということ聞きましたので、そのことについての内容を端的に教えてください。","respondent":"桑村人事課長","answer":"それについて、人事課と事業部サイドでお互いに、どういう対応をしていったらいいのかというようなことをやってきてあります。人数的なものは、委員おっしゃられた１０名から２０名なんですけれども、私どもの把握では、徐々にですけれども減っているというふうに認識しています。","voiceIndex":270,"id":"exchange-122"},{"speaker":"伊藤委員","kind":"意見","question":"裁判のことについては、あまり具体的なコメントはいたしませんけれども、当然のことであると私たちは思っておりますので、よろしくお願いいたします。それから、気になったのは、構造的な問題がないということですけれども、先ほどの年齢構造からすると、非常にいろんな問題がありそうだなという思いがします。これから適切な人事管理、対応をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":272,"id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"これは民間では電話料を削減しようということで、ＩＰ電話の導入を進めておりまして、どこかの自治体でも検討並びに導入ということで、現在動いているところもあるように聞きましたけれども、これについてどう思われるか、また区ではそれを取り入れるような検討ということは考えていますでしょうか、それについてお答えください。","respondent":"鷹倉経理課長","answer":"ＩＰ電話の話がございました。実は、品川区も一部ＩＰ電話を出先との関係で使ってあります。これを大きく広げていくかどうかという問題につきましては、もう少しＮＴＴの動向だとか、通信業界の動きを見極めていかなければいけないと、このような認識に立っているところです。","voiceIndex":274,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"実際、一部で検討並びに実態を見てこれから導入もあり得るという解釈で、今後先の話ですけれども、そういう検討もされているということでありがとうあります。午前２時頃なんですけれども、ご近所の方は延焼により焼き出されました。品川区には待機寮が２カ所あると思うんですけれども、ここは例えば深夜２時でも３時でも、４時前後でもどのようにすればそこに入れるような仕組みになっているのでしょうか。","respondent":"田村地域活動課長","answer":"それで現地に駆けつける。駆けつけたときに、先ほどお話のあった待機寮の鍵を持っていますので、時間に制限なくその鍵を開けてそちらに入れるという形になっております。","voiceIndex":276,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"例えば、深夜３時とか、早朝４時なんかは、まことに恐縮するということもあるんですけれども、確かに待機寮に近いお宅の方はいいと思うんですけれども、せっかく地域に地域センターなりシルバーセンターなり、多々ありますね。なかなか難しい。でしたら、そういうところを例えば町会長に鍵を渡して、一報は必ず区のほうにするにしても、身近な場所ですぐ入れるような取り組みをしてもらえないでしょうか。","respondent":"田村地域活動課長","answer":"ただし、町会が鍵を持ってということになると、行政情報も入っていますので機械警備を建物そのものをしていますから、地域センター全部に区内居住者がいる地域センターだけじゃないですけれども、やはりなるべく早めに来られる職員を態勢として組んで。","voiceIndex":278,"id":"exchange-126","title":"町会・自治会支援"},{"speaker":"須貝委員","kind":"質問・要望","question":"待機寮に入られない方ですね。たまたま朝まで呆然としてそこに立っていらっしゃった方も、翌朝ふと気づきまして、マンションなりアパートなりをどこか探さなければいけない。でも、それ以外はできません」ということなんですけれども、その辺も柔軟に考えて、とりあえず緊急の一時的な手段として、そういうような貸し出し等もやっていただけないかなという要望です。それと、今度焼け焦げた日用品があります。","respondent":"田村地域活動課長","answer":"ただ、全般にわたって最後までというのは現実的には無理なので、実際には駆けつけたときに、翌日の警察署の取り調べがあったり、先ほど言ったようなごみの処理だとかあるので、一覧表にして被災された方にお渡しして。","voiceIndex":280,"id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"最後に、先ほど話があったんですけれども、小学校に避難場所がありますね。災害に遭われたときに、みんな一時避難場所の小学校に行けと。中学校もあると思うんですけれども。そのときに、そこの鍵ですか、一応全部閉まっているわけですね。その辺はどういうふうになっているのでしょうか。","respondent":"久保田防災課長","answer":"小学校が避難所になっておりますけれども、鍵につきましては、これも地域の避難所連絡会議の中で、地元の町会の役員とか町会長が持って、いざというときにはその鍵で学校を開けていただくというような態勢づくりになってあります。","voiceIndex":282,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"ということは、学校の場合には町会長に鍵をお預けして、どうぞ入ってくださいと。でも、町会長に何かあったらどうするんだという議論に発展すると思うんです。だから、そういうものを登録制にして、例えば最低３人とか、そういう感じで渡すわけにいかないのでしょうか。つまり、いざというときに難しいのではないかと思うんですけれども、どうでしょうか。","respondent":"久保田防災課長","answer":"先ほど説明したとおり、町会長や町会の役員ということで、複数の方に持っていただくようになっております。","voiceIndex":284,"id":"exchange-129","title":"町会・自治会支援"},{"speaker":"藤田委員","kind":"質問","question":"私からは、１５１ページの庁舎等維持管理の中の屋上緑化についてお伺いしたいと思います。環境問題の取り組みの一つとして、屋上緑化の道筋をつけるという区役所の総合庁舎の屋上に緑化を昨年やりました。壁面緑化などの、南側にはない新たな工法を取り入れ云々」と、書かれておりますが、南側にない新たな工法というのは、どういう工法を考えられているのか聞きたいと思います。","respondent":"鷹倉経理課長","answer":"さらに残っているものということで、今もご指摘がございました壁面を利用するような手法、これがまだ区としてご紹介申し上げていないわけですけれども、その辺のところを伝えながら、壁面だけではないわけですけれども。","voiceIndex":288,"id":"exchange-130"},{"speaker":"藤田委員","kind":"提案","question":"そういう面で、ここには非常に子ども連れの若いお母さんがお弁当を食べたり、緑を楽しんだりしておりますけれども、そうした中で私が提案をしたいのは、草花をもちろん楽しんでいただくということと、もう一つは健康遊具といいますか、何か一工夫をしてはどうかなというふうに思っているんです。ですから、花を見ながらマッサージをしているということで、順番をつくって待っているんですね。","respondent":"鷹倉経理課長","answer":"今の足裏マッサージということで、いい提案をいただいたかと思います。ただ、重さ的にあまり重たくないものを使っていく必要がありますので、何らかの軽いものでそういうものができればというふうに考えてあります。","voiceIndex":290,"id":"exchange-131"},{"speaker":"藤田委員","kind":"質問","question":"もう１点、別な話になってしまうんですけれども、網戸ですね。網戸に色がついていると、例えば緑とか灰色とかありますね。これがあると、部屋から外の景色がわからないという、これは光の吸収とか反射とかいろいろあると思いますけれども、そういう外と部屋と一体になるような、そういう工夫というのはご存じですか。","respondent":"鷹倉経理課長","answer":"屋上ではなくて庁舎の中での網戸という理解で、普通の部屋での網戸。網戸というのはなかなかないわけですけれども、そういうスクリーン的なものがあるということは理解しています。","voiceIndex":292,"id":"exchange-132"},{"speaker":"藤田委員","kind":"質問","question":"なぜ、これを聞くかといいますと、今現在ずっと白いフェンスといいますか、棒の塀を立てていますね。ネットのところもありますけれども、要するに塀なんです。屋上をずっと取り囲んでいる柵というかフェンスというか、今これが白なんです。ですから、あそこに現在白く塗っている柵の色を検討してもらえないかと思っているんです。黒にするだけで、全然雰囲気が違いますよ、いかがでしょうか。","respondent":"鷹倉経理課長","answer":"今、藤田委員から色についての工夫をご提案いただきましたので、その点も参考にしながら、さらに検討を深めていきたいと、このように考えてあります。","voiceIndex":294,"id":"exchange-133"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひ、ひとつ検討していただきたいなと考えています。それと、最近皆さん緑に非常に関心があって、あそこに見えますね。みどりの相談を、ぜひ定期的にやってはどうかと。今現在エレベーターの前にパンフレットが置いてあるだけですので、ぜひこれは定期的に専門の相談員にあそこに来ていただいて、いろいろな相談をしてはどうかなというふうに思っているんですけれども、いかがでしょうか。","respondent":"鷹倉経理課長","answer":"その講師の先生方ともいろいろ相談しながら、どういう形で今ご提案の部分を生かしていけるか、今後検討していきたいと思います。","voiceIndex":296,"id":"exchange-134"},{"speaker":"藤田委員","kind":"質問・要望","question":"やはり、区民の模範になるような屋上緑化にするわけですので、ぜひ一つさまざまな意見があると思いますので、それを取り入れていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"私のほうから１５５ページの生活安全推進事業、１４９ページの職員研修費、１６３ページの事業部支援プロジェクト、１６９ページの地域センター等管理運営費について、それぞれお聞きしたいと思います。予算を見ると、あまり平成１６年度と変わらないんですが、その評価についてどのようにお考えになっているか、まずお聞きしたいと思います。","respondent":"杉浦生活安全担当課長","answer":"現在、原則として午前１１時出勤の午後７時４５分までの勤務です。犯罪の発生を見ますと、昨年の犯罪は５,８０７件ということで、５４０件ほどのマイナスになっておりますので、それなりの効果が上がっているというふうに考えております。","voiceIndex":300,"id":"exchange-136"},{"speaker":"西本委員","kind":"意見","question":"かなり犯罪等々が少なくなったということで、これから非常に期待するところであります。それにあわせて、我が町パトロールの件なんですが、これは地域の方たちにお願いしているわけですけれども、平成１７年度はメンバーをどういうふうに選定されるのか。要は、町会から推薦等々いろいろありましてお願いしていると思いますが、その辺は今後どのような形にしていくかお答え願います。","respondent":"杉浦生活安全担当課長","answer":"我が町パトロールのメンバーの選定ですけれども、昨年の５月に発足した段階で２年間の委嘱という形ですので、平成１７年度も変わらないメンバーという形になります。平成１８年度からは、さらにご希望の方を募りまして、更新という形になります。","voiceIndex":302,"id":"exchange-137"},{"speaker":"西本委員","kind":"意見","question":"２年間ということで、ほぼ同じ方たちにお願いできるのかなということなんですが、実際まだ１年にはなっていないと思うんですが、行ってどういうご意見等々があるのか。要は、報酬なく自主的にというところで何もないというのはあるかと思うんですが、交通費まで必要かどうかわかりませんけれども、実際に運営のための手当みたいなものができるかどうか、その辺の考え方もお願いします。","respondent":"杉浦生活安全担当課長","answer":"この我が町パトロールにつきましては、現在のところ発足以来、１５４回の活動で１,６３３名の方にパトロールに従事していただいております。非常に活性化が図られておりまして、これの呼び水となりまして、３７団体、１,３００名余の方々が防犯に立ち上がっているです。","voiceIndex":304,"id":"exchange-138"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、ここから波及していろんな団体のところでも、できることから参加するという機運をぜひ高めていただきたいというふうに思います。生活安全担当課長にお聞きしたいんですが、警視庁から来られて約１年半になるわけですけれども、地方自治体に来られて何か感じられることがあるのかどうか。それから、今後協働関係等を含めて、どういうふうにお考えになっていられるのか、その辺をお聞きしたいと思います。","respondent":"杉浦生活安全担当課長","answer":"今後の話ということになりますと、せっかくこうした自治体でいろいろな経験をしていますので、今後ももし戻るようなことがあれば、こうした貴重な体験を生かして、少しでも社会のお役に立ってまいりたいと考えております。","voiceIndex":306,"id":"exchange-139"},{"speaker":"西本委員","kind":"質問","question":"これからの職員像というのが変化していて、それに合わせた研修を組み込んでいくというお話なんですが、研修にもいろんな意味があると思うんですが、やはり一番大切なのは現場を知るということではないかと思うんです。それから、この項目の中に管理監督者研修というのがあるんですが、これはどういうものかを教えてください。","respondent":"桑村人事課長","answer":"特に新任になったときにどういう対応が必要ですとか、あるいは指導する場合のどういう手段がありますとか、あるいはマスコミについてどういう対応をすべきですとか、そういった意味での研修ですとか、また逆に、民間等々の職員と一緒にやるような研修にも出しているものです。","voiceIndex":310,"id":"exchange-140"},{"speaker":"西本委員","kind":"質問・要望","question":"現場のほうを経験する。次に、１６３ページの事業部支援プロジェクトなんですが、先ほどもボランティア活動の連携のしくみづくりがありましたが、仕組みはよくわかりました。それなりにいろんな場所を探しながら活動を進められているんですが、具体的な公の場で自由に使える活動の場があったらいいなというふうに言っている方も大勢いらっしゃるんですが、その辺の考え方はいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"今現在のところでは、情報の提供ということで進んでいますけれども、活動の場のほうは、今回プレス発表の中にもありましたが、ボランティア活動支援拠点整備事業というのも一方で進んでおりまして。","voiceIndex":312,"id":"exchange-141"},{"speaker":"西本委員","kind":"質問","question":"ぜひ、よろしくお願いしたいところです。もう一つ、政策支援情報システムというのがあるんですが、これはどういうものなのかご説明をお願いします。","respondent":"榎本行財政改革担当課長","answer":"政策情報支援システムにつきましては、今地図情報の部分がかなり電子的に使えるようになっているんですけれども、まだ全庁的に使える段階ではないところがありまして、そういうものを地図等でうまく組み合わせて、いろいろな政策立案をするときにシミュレーションができるとか。","voiceIndex":314,"id":"exchange-142"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し、具体的なところを教えていただきたいんです。事業部支援プロジェクトということは、各事業部に対する支援という形で、ＩＴ化のシステムをつくられるという意味なんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"事業部支援ということなので、各事業部が使いやすいように基盤整備をして、さらにどういうふうに使えるかという例示等も備えながら、いろんなシミュレーションをやったり、マーケティング調査をやったりとか、統計情報を視覚的に処理したりとか。","voiceIndex":316,"id":"exchange-143"},{"speaker":"西本委員","kind":"質問","question":"今のお話の中で、非常に興味がわくんですけれども、議会もそういう結果でも構わないんですけれども、そういうものが利用できるという方向にはされないのでしょうか。政策立案とか評価も含めて構築されていくと思うんですが、それをある一定の情報ということで一般の方が見れるという形にはならない仕組みなんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"今のところ庁内の支援システムという形で使っておりまして、若干その辺が個人情報の部分とか著作権の問題等がありまして、範囲を限定しないとかなり費用等もかかるという部分もありまして、事業部内の運用を前提として考えております。","voiceIndex":318,"id":"exchange-144"},{"speaker":"西本委員","kind":"質問","question":"最後に、地域センター等管理運営費のところなんですけれども、細かいお話になってしまうんですが、地域センターのまとめをするところは地域活動課になるんでしょうか、そこで管理をしているんですが、地域センターごとの、例えばふれあい掲示板なども含めて、どこにどういうものがあるのかというのが集中管理されていない部分があるんですね。","respondent":"田村地域活動課長","answer":"特に、ふれあい掲示板のお話が例にありましたので、定例的に月２回、１３の地域センターで所長会をやります。そこで私のほうから流す情報、向こうからもらう情報と、もろもろの情報交換を行います。","voiceIndex":320,"id":"exchange-145"},{"speaker":"西本委員","kind":"意見","question":"集中管理というのは、情報を周知するのに非常に大切なことだと思いますので、ぜひお願いしたいと思います。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":322,"id":"exchange-146"},{"speaker":"石田委員","kind":"質問・要望","question":"私は１６７ページの消防団運営費と、それからまた同じように１６３ページのボランティア活動の連携のしくみづくり、１５５ページの地域活動基盤整備補助、それから時間があれば １８１ページの個人演説会費の選挙の関係をちょっとお聞きしたいと思います。この状況を防災上、どういうふうにとらえているか、逆にどういうふうに見ていらっしゃるか、その辺の考えをまず教えていただきたい。","respondent":"久保田防災課長","answer":"当然ながら、これは東京都でそういうものを計画的に整備していくというような話になっているわけですけれども、防災上の観点からいうと、ポンプ自体の問題というのは、その中で同じように継続して維持していると思いますので、その辺については。","voiceIndex":324,"id":"exchange-147"},{"speaker":"石田委員","kind":"質問・要望","question":"歳入でも私はやったんですけれども、ぜひ意識をしっかり持っていただきたいのは、ここ数年、２３区で今の団小屋の整備は計画的にやるといっても、予算組みが１０件程度だったんですね。今年度の予算も１１件だった。都でどういう動きが必要なんだというところは、しっかり抑えていただきたいと思いますが、その辺の考え方を教えていただきたい。","respondent":"久保田防災課長","answer":"その辺で今後東京都の計画が品川区内にあるかどうかどうかについては、今後とも消防署を通じて情報を収集していきたいというふうに考えております。","voiceIndex":326,"id":"exchange-148"},{"speaker":"石田委員","kind":"質問・要望","question":"これは市町村民税を使っているわけですから、品川区として必要なものは必要と考えて、こういうことはこういうふうにしましょう、この地区だったらこうしましょう。それを消防団運営委員会でもいいけれども、それで抑えたならば、そういうことをしっかり私はやっていくべきだと考えていますので、それは後でまたお考えがあれば教えていただきたい。そういことをされているのかどうか、その点をお聞きしたい。","respondent":"榎本行財政改革担当課長","answer":"要は、側面支援という意味で、いろんな情報を発信するのをＰＲを手伝ってあげるという形はできるんですけれども、その活動の中まで入るかどうかというのも含めて、庁内の検討会議で検討して、今の段階では情報発信から第一歩をスタートしようということでまとまったところです。","voiceIndex":328,"id":"exchange-149"},{"speaker":"石田委員","kind":"質問・要望","question":"その際、希望でありますが、先ほど言いました公共機関というとらえ方をすると消防署とか警察署、この辺も個々に委嘱を含めたいろんなお願い事をしている部分もあって、受け手のところは全部が来ているというところもあるわけですから、その辺のところも合わせて、ぜひ集約をしていただきたいなと思うんですが、今後のことですけれども、その辺も一緒に合わせて検討していくのかどうかをお聞かせ願います。","respondent":"榎本行財政改革担当課長","answer":"今現在、そこの集約はしていないんですけれども、受け手の部分から見てわかりやすくしていくという意味で、その部分も含めて検討していきたいというふうに考えております。","voiceIndex":330,"id":"exchange-150"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほど、西本委員からも話がありましたけれども、ここの委嘱型のところに最終的に話を入れ込んで、全体を全部見れるところでやっていただきたいなと思うんです。そこで、町会なり、高齢者クラブなりに、そういうところが今あるとするならば、ぜひその辺のところも目を向けてほしいと思うんだけれども、その辺のところをピックアップして見るというようなことも考えられているのかどうか教えてください。","respondent":"榎本行財政改革担当課長","answer":"今回のボランティア活動の紹介窓口は、地域センターにもつくる予定でおりますので、各地域センターで町会・自治会等の関係と、あとはボランティアをしたいという助け合い精神にあふれた方たちが、お互いに顔が見えるような活動につなげていきたいというのもありますので。","voiceIndex":332,"id":"exchange-151"},{"speaker":"石田委員","kind":"質問","question":"ぜひ、よろしくお願いします。そういう形の中で、今度地域活動基盤整備補助の話に持っていきます。この前、ある町会で掲示板をつけたいと言ったときに、どうしてもつけられないところが１カ所ある。今、つけているところは４５cmぐらいの幅しかなくて何も張れないんだと。過去、そういう公的な部分に町会の掲示板を張らしたことがないということなので、それはお断りされて、それはそれで結構です。","respondent":"田村地域活動課長","answer":"委員お尋ねの公共施設等に張るということは、例えば公園だとか、そういうものについては任意の団体の町会の掲示板なので、そういうところに設置することはお断りしているという状況です。","voiceIndex":334,"id":"exchange-152"},{"speaker":"石田委員","kind":"質問","question":"８割以上、そういうものを張っているにも係わらず、建物も変わってきているわけですよ。どうしても張るところがないというようなときに、何で町会も任意の団体だと、こう来ちゃうんですか。時代も変わっているのであれば、町会ぐらいは必要に応じて、どうしてもだめというところは、それはちゃんとお願いするだけじゃなくて、だめと言われると、町会の人もさっき言ったけれども人がいいから、そうかなと。","respondent":"田村地域活動課長","answer":"石田委員、おっしゃるとおり張っている内容は、行政の情報がほとんどという状況です。ただ、先ほどの繰り返しになりますけれども、団体の性格というのをやはり考えて対応していかないと、公共施設に町会はいいけれども、ほかの任意団体が張れないのかという話にもなりかねない。","voiceIndex":336,"id":"exchange-153"},{"speaker":"宮崎委員","kind":"質問","question":"１４７ページの非核平和都市品川宣言事業についてお伺いしたいと思います。今年は非核平和都市品川宣言２０周年ということで、行事が予定されております。区の説明でも、非核平和都市品川宣言２０周年事業というふうに言っております。祈念展とかモニュメント作成となっておりますけれども、終戦６０年、被爆６０年、この思いというのがこの行事の中にどういうふうに入っているのかお伺いしたいんです。","respondent":"宮地総務課長","answer":"２日間のうち平和祈念展ということで、イベントホールで平和祈念展を開催するわけですが、その祈念展の中には、品川区が取り組んできた２０年の歩み、そして広島・長崎での悲惨な被爆の事実、実物を持ってまいりまして、実際にそこに展示をいたします。","voiceIndex":339,"id":"exchange-154"},{"speaker":"宮崎委員","kind":"質問・要望","question":"内容は、今後期待していきたいというふうに思います。今日は折しも東京大空襲６０周年、１０万人の方が一夜にして殺されました。そこで、質問したいんですけれども、品川区でも空襲がありました。この声を集めるという取り組みが特に大事だというふうに思うんですけれども、この辺の取り組み等の考え方について何かありますでしょうか。ぜひやってほしいと思うんですけれども、どうでしょうか。","respondent":"宮地総務課長","answer":"今回の記念事業の中でも、またさらにそれをＰＲして、多くの方に読んでいただきたいと考えていますので、既に１０周年でつくりました「明日へのメッセージ」、さらに活用してまいりたいというふうに考えております。","voiceIndex":341,"id":"exchange-155","title":"町会・自治会支援"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これをぜひ位置づけていただきたいと思うんです。このことは強く要望しておきたいと思います。北朝鮮も持ち始めた。その後の状況ついて、取り組みについてお伺いしたいということと、５月のＮＰＴの見直し検討会議に向けて、宣言をしている区として何らかの取り組み、保有国に向けて廃絶を訴えるなり、何らかの取り組みが必要ではないかというふうに思いますけれども、いかがでしょうか。","respondent":"宮地総務課長","answer":"私どもの非核平和都市品川宣言の普及啓発の取り組みにつきましては、ちょうど昨年から子どもたちが参加する広島への事業、そして長崎の事業ということで、子どもたちがより身近で実際に起こった広島・長崎に行って感じることが一番重要ではないかと考えております。","voiceIndex":343,"id":"exchange-156"},{"speaker":"宮崎委員","kind":"質問","question":"やっぱり、このときにしっかりと宣言にも核を持っている国、持てる国は即核兵器を捨てよと訴えている。今の答弁は納得できないんですけれども、もう１回答弁をお願いしたいと思います。こうした動きに対して、区は外側には全く何もしないということなんでしょうか。その辺の見解も、もう一度お伺いしたいと思います。なぜ、臨界前の核実験以降、抗議しなくなったのか、非常に疑問です。","respondent":"宮地総務課長","answer":"確かに平成１０年５月２９日のパキスタンの核実験に対する抗議が最後になっておりますが、これはいくらやってもただ抗議しているだけです。それはこれからの実際に子どもたちに身につけてもらうほうが、私どもといたしましてはより宣言の趣旨を普及啓発できるということ。","voiceIndex":345,"id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問","question":"今の抗議しているだけで、何にもならないという答弁は、本当にあきれてものが言えないというか、冗談じゃないよというふうに思うんです。世論が戦争を食い止めるかどうかなんですよ。じゃ、区のほうは、自分たちは抗議してもしようがないと思っていますというお話しをして、草笛さんに来てもらうことになっているんですか、そんなことはないと思うんですよね。どうでしょうか。","respondent":"本間総務部長","answer":"そういう中で、品川区は非核平和都市品川宣言をした区です。この宣言の趣旨にのっとりまして、この戦争の悲惨さ等を次世代につなげるような、そういう地道な事業に取り組んでいくということを、先ほど来総務課長から答弁していますので、ひとつよろしくお願いいたします。","voiceIndex":347,"id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は改めて時間もありませんので要望してきますけれども、今年は本当に重要な年でありますので、今の２０周年だけの取り組みも大事ですけれども、やっぱりもっとスケールを大きく見て、核戦争を食い止めるという取り組みの中に、品川区もこの流れの中に入っていくということが大事だというふうに強調して、重ねてこれを要望して終わらせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-159"},{"speaker":"木下委員","kind":"質問・要望","question":"私は１４７ページの国際友好都市交流事業について、それから１５５ページの生活安全推進事業について、それから職員費について質問させていただきたいと思います。それと、中国のハルビン市は人的交流は今は途絶えている話を聞いているんですけれども、どのようになっておりますでしょうか。","respondent":"宮地総務課長","answer":"ポートランド市につきましては、昨年平成１６年が２０周年を迎えた年で、２０周年目には向こうのネーザン・スミス市長一行が品川区を訪ねてまいりまして、区民レベルでの交流を図ったところです。","voiceIndex":351,"id":"exchange-160"},{"speaker":"木下委員","kind":"質問","question":"実は、この間、あるロータリークラブの方が、「フィリピンだとかタイだとか、そういうところから友好クラブにならないという申し入れがあるんだけれども、どうなんだろう」みたいな話が出た際に、「品川区は友好都市を持っているわけですから、そういうのに乗ってやったほうが、人の交流はもっと活発になるんじゃないでしょうか」とお話しをして、「それがジュネーヴ市とか。","respondent":"宮地総務課長","answer":"国際友好協会の中で、そういう議論が活発になり、本当に進めていくような機運が醸成されてきたときには、それはそれとして大いに意義のあることだと思いますが、あくまでも国際友好協会中心に事業展開等を進めていくような形で、今のところは考えているところです。","voiceIndex":353,"id":"exchange-161"},{"speaker":"木下委員","kind":"質問","question":"国際友好協会ということなんですけれども、姉妹都市、友好都市というのは、都市間で結ぶものですから、区にどういう気持ちがあるのかというのが一番先に来るかと考えています。","respondent":"本間総務部長、宮地総務課長","answer":"それともう一つ、国際友好協会のほうでは、区内に多くいらっしゃるアジアの国の方々と、品川区内でいろいろな品川区民と交流が図れるような事業展開を工夫しながらやっておりますので、姉妹都市。それぞれ派遣、受け入れとあるわけですけれども、この間、ポートランド市では平成１６年度までにこちらからの派遣は１１２名が行っておりまして、向こうからは８３名受け入れているところです。","voiceIndex":355,"id":"exchange-162"},{"speaker":"木下委員","kind":"質問","question":"今、総務部長の答弁で、姉妹都市、友好都市は三つというお話だったんですけれども、ハルビン市は友好都市に含まれないのか、私は詳しく知らずに申し訳ないんですけれども、教えていただければ。","respondent":"本間総務部長","answer":"ハルビン市につきましては、教育委員会のほうで教育交流ということで、自治体同士のおつき合いがあったですが、今現在は相手方の事情もございまして休止しているという状況です。ちょっとつけ加えますと、相手方の事情によりまして、現在は交流をしていないという状況です。","voiceIndex":358,"id":"exchange-163"},{"speaker":"木下委員","kind":"質問・要望","question":"やはり午後２時から３時というと、そんなに人通りが多いわけではないですから、朝方ですとか、夕方ですとか、朝の通勤時間帯ですとか、夕方の買い物の時間帯、人通りの多い時間帯に活動されれば、もっと区民の方に認知されますし、目立つ活動ができるのではないかな。たまにはそういう形で変更することができないかなということで、お願いしたいと思うんですけれども、いかがでしょうか。","respondent":"杉浦生活安全担当課長","answer":"しかしながら、画一的に午後２時、３時がよろしいかというと、必ずしもそうじゃないわけでございまして、時間についても同じく十分に検討していきたいというふうに思っております。","voiceIndex":360,"id":"exchange-164"},{"speaker":"堺委員","kind":"質問・要望","question":"質疑に入ります前に、委員長に許可をお願いしたいと思うんです。質疑の途中で資料を示しながら質疑をさせていただきたいと思います。私のほうからは１５５ページにありますふれあい掲示板管理費、７５６万２,０００円に関連して何点か確認をしながらお尋ねをします。最初に、現在区内に４８５本だったと思うんですが、ふれあい掲示板がありますけれども、設置目的について教えていただきたいと思います。","respondent":"田村地域活動課長","answer":"設置目的ですが、主に地域の情報の伝言板として活用する。さらに区からの広報、行政情報の広報として利用すると、そういう設置目的です。","voiceIndex":364,"id":"exchange-165"},{"speaker":"堺委員","kind":"質問・要望","question":"掲示するにあたっては、各地域センターにおきまして期限つきの承認印を押しながら掲示されると思うんですけれども、どのようにいいかどうかの判断、審査というんでしょうかされるのか。あわせまして、ふれあい掲示板でも掲示できないものが明示されておりますけれども、それはどういったものなのか、あわせてお尋ねをしていきたいと思います。","respondent":"田村地域活動課長","answer":"管理規約の３条によりまして、先ほどのご説明した２条が発行するもの以外に、次の禁止事項に触れるものは掲示することができないということです。１点目は、営利を目的とするもの。２点目が、政治・宗教活動に関するもの。３点目が、個人のプライバシーを侵害するもの。","voiceIndex":366,"id":"exchange-166"},{"speaker":"堺委員","kind":"意見","question":"そうしますと、各地域センターの所長の判断で決まっていくわけですが、品川区内に１３カ所の地域センターがあります。例えば、２カ所以上の地域センターにまたがって掲示するというような場合、確か本課協議と、要するに本庁の課長の判断というか、課の協議に委ねる。要するに、使用禁止の掲示物については、上も下も張れないという理解になるのかどうか、その辺もあわせてお尋ねをしておきたいと思います。","respondent":"田村地域活動課長","answer":"実は、先ほど連合会のお話しで、地域センターの管内でしたら地域センターの所長が連合会の事務局として手続で許可をするということで、連合会のほうから区内の１３地域センターあるいは２カ所以上をまたがってふれあい掲示板を利用する場合には。","voiceIndex":368,"id":"exchange-167"},{"speaker":"堺委員","kind":"意見","question":"今は特に区別なく、上も下も許可を得たものは張れるということのようです。例えば、区から土地を無償で借り受けて、なおかつ運営費の負担金や助成金を受けている私立保育園等が、政治活動と思われる活動の案内文書に名前を連ねたりあるいはそういったところが運動すると、これについてのお考えをお聞かせいただけますか。","respondent":"田村地域活動課長","answer":"実は、先ほどの管理規約の下に実施細目というものを定めています。その中には、特に例えば営利を目的とするものについては、実費弁済以上の会費、入場料を徴収するもの。","voiceIndex":370,"id":"exchange-168"},{"speaker":"堺委員","kind":"質問","question":"簡単に申し上げますと、区内の私立保育園８園で毎年約１２億６,０００万円近いお金が出ているわけですから、そういったところがそういったことをしていいのかどうかという、これは経理課の所管になるんですか、ちょっと教えていただけますか。","respondent":"鷹倉経理課長","answer":"今、問題になっているところの土地について、無償で貸し付けているわけですが、そこのところと今のふれあい掲示板との因果関係というのは、今の話でははっきりしないんですが、私どもこれは３０年ということで、あと５年ぐらいで期間が経過するというところなんです。","voiceIndex":372,"id":"exchange-169"},{"speaker":"堺委員","kind":"質問・要望","question":"わかりました。これがその写真です。「９条改憲に断固ノーの姿勢を示す九条の会アピールを発表し、全国民に賛同と連帯を呼びかけました」。これに関連する、このようなポスターがふれあい掲示板の使用禁止にあたる掲示物になるのかどうか、またそういうところに私立保育園の名前を連ねるということについて、問題がないのかどうか、その辺についてご見解をお聞かせいただきたいと思います。","respondent":"田村地域活動課長、金子保育課長","answer":"ほかの地域センターにも行ったので、先ほど冒頭お話ししたように、２地域センターに張りたいということなので、それでは本課で協議してくださいということで、私のところに協議に来ました。この法人自体がさまざまな活動をされる場合というのはあるとは思いますが、これが保育の運営に支障があるかどうか、あるいは保護者に対して署名やカンパあるいは加入等々で強制あるいは半強制になることはないかということについては。","voiceIndex":374,"id":"exchange-170"},{"speaker":"堺委員","kind":"質問","question":"そうしますと、使用禁止の対象になっている政治活動というのは、具体的にどういったところ、どういう内容、どういうことを指すんですか。どういうものはふれあい掲示板に張ってはいけませんよということになるのか、その辺を教えていただけますか。","respondent":"田村地域活動課長","answer":"先ほど、一番細かい定めとすると、実施細目ということが定めで、全部を網羅できる内容ではありません。","voiceIndex":377,"id":"exchange-171"},{"speaker":"堺委員","kind":"意見","question":"今の地域活動課長の説明だと、よく理解できないんですが、私が理解するには、さっきも申し上げましたように、あのポスターの中身に憲法９条を大切にしたい人とか、日本国憲法第９条を守りたいとか、さっきのいただいたお手紙も紹介しました。したがって、こういったポスターについては、この人たちがどのような考えを持って、どこにどういう形であろうと、それは自由が保証されているからいいと思います。","respondent":"田村地域活動課長","answer":"先ほど冒頭申し上げましたように、町会連合会の委託を受けて基準を定めて、それに従って判断するということで、繰り返しになりますけれども、今までの過去の許可をおろした内容を見ましても、できるだけ有効活用したいということで、原則的に除外をするのではなく。","voiceIndex":379,"id":"exchange-172"},{"speaker":"堺委員","kind":"質問","question":"何をもって明らかにあたっていないということを言うんですか。ここまではっきり憲法第９条ノーと、今国会でも憲法論議をされております。これは憲法に関してどうのこうの。いいんですよ、思想信条が認められているんですから。だけれども、そういった政治活動と禁止されている公の掲示板に、そういったものを掲示するということはいかがなものかということを言っているわけですよ、いかがですか。","respondent":"山田区民生活事業部長","answer":"中身について、日本国憲法そのものを語るという形を取ってありますので、私どももこちらについては、これが本当の政治活動ということにあたるかどうか慎重に判断しながら、今後審査をするときに、それぞれの所長の段階だけではなく。","voiceIndex":381,"id":"exchange-173"},{"speaker":"堺委員","kind":"質問・要望","question":"私も参考にこれを読みました。「区政や職員が区民から誤解や批判を招くことのないよう、一人ひとりに公務員としての強い自覚が求められております」ということになっているんですね。その辺から見て、我々はあくまでも公平中立でなければならないという我々職員、それに関してもう一度、この種の掲示板の対応について、区長の見解を求めます。","respondent":"高橋区長","answer":"憲法を守らなければならない我々は、憲法の遵守義務があります。しかしながら、その憲法の中で第９条を改憲したほうがいいか、それを守ったほうがいいかということは政治論争だと思います。そういうものにつきましては、私は政治行為だというふうに思っております。","voiceIndex":383,"id":"exchange-174"},{"speaker":"原委員","kind":"質問・要望","question":"端的に２点お伺いをして、時間内で終わりたいというふうに思っております。一つは、１６２ページの防災対策費、もう１点は１８３ページの国勢調査の２点です。特に、復興計画におけるマニュアル作成についてお伺いしたところ、その作成は前向きにやっていくと、そしてまた防災区民組織を有効に生かして検討していきたいというようなお答えをちょうだいしました。この部分について、お伺いをします。","respondent":"久保田防災課長、長田区民課長","answer":"したがいまして、今後そういったところは防災課だけではなくて、いろんなまちづくりの部門、それから商業の復興ということであれば産業関係、それから住宅関係、いろいろな面ありますので、そういった点では、やはり時間を相当かけて。国勢調査のお尋ねです。ご承知のように、今年の１０月１日を基準に国勢調査が始まります。これは５年に１回の調査で、国の最も基本となる調査です。規模等につきましては、１８万７,０００世帯ぐらいが対象になるだろうということ。","voiceIndex":386,"id":"exchange-175"},{"speaker":"原委員","kind":"質問","question":"定義もされていない。こういった組織をどう使っていくのか。だけど、そういうところから、果たして防災区民組織がマニュアルづくりの中で有効な活動ができるのかどうか、このところは非常に疑問に思っていますが、いかがですか。調査員と指導員と臨時職員に分かれて、アルバイトを使っていくんでしょうか、３,７４０人ですか。ここのところの状況は、どういう形を取ろうとしていらっしゃるんですか。","respondent":"久保田防災課長、長田区民課長","answer":"災害復興マニュアルについてですけれども、確かに、時間をかけてというお話もあるかと思うんですが、検討課題の中では、例えばほかの自治体のつくっているマニュアルを参考に見てみますと、まず震災が起きた後、応急対策に立ち上がる。臨時職員につきましては、５月頃から調査期間中、いろいろな意味での事務補助、あるいは地域センターにおける調査員に対する事務説明会を、確か平成１２年は五十数回だったと思うんですけれども。","voiceIndex":389,"id":"exchange-176"},{"speaker":"原委員","kind":"質問・要望","question":"もう時間がなくなってしまいまして、防災のほうは、もう少し内容もしっかり検討するとともに、早く行っていただきたいというふうに思っております。確かに、これはお金が出る話ですから、いろんなところからいろんな声が聞こえてきているので、その辺の考え方だけ教えてください。","respondent":"長田区民課長","answer":"それぞれの調査区につきまして、１人の調査員が持つ数は地区割りの難しさというのがありまして、５０世帯ぐらいを目安としたいわけですけれども、地区割りの関係で大体 ４０世帯から７０世帯を一つの調査区にしたいと考えています。","voiceIndex":392,"id":"exchange-177"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=842#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":115480,"voices":394}}]);
